window.__D("text/maamarei-admur-hazaken/c016",{"p":[[2101920171,"כך נעשי' בחי' לבוש למדות, והוא ענין לאה שמקבלת מיעקב לאחר שנשא אותה כו' שהן בבחי' דכר ונוק' כידוע וד\"ל.\n<b>אך</b> מעתה יש להבין מ\"ש כי שנואה לאה אחר שנשא אותה מאחר שהוא בחי' גילוי המח' שמקבל מן המדות שאז אינה בהעלם כו'. אמנם הענין הוא דעיקר הטעם בשנאת לאה להיות שהוא בבחי' תענוג תמידי שנפסק בה האהבה ונהפך מתענוג לצער גם במשפיע, כנראה בחוש שכל תענוג תמידי באיזה דבר מה לבסוף יהפך מאהבה לשנאה כמו הוקר<sup data-n=\"769\">36</sup> רגלך מבית רעיך פן תשבענו והקאותו כו' וכה\"ג, ומבואר למעלה בפי' לאה ל' נלאה כו' וזהו בין בהיות המח' בחי' מקבל מעצם החו\"ב דזיוגייהו תדיר כו' בין בהיותה בחי' מקבל מן המדות דיעקב הרי היא משוטטת בכל רגע כו', וזהו דזיווג יעקב ולאה בחול (וגם בזמן הגלות שנק' שינה אין המח' דבחי' לאה פנימית<sup data-n=\"770\">*36</sup> כמ\"ש אני<sup data-n=\"771\">37</sup> ישינה ולבי ער קול דודי דופק כו'). וזהו וירא ה' כי שנואה לאה ויפתח את רחמה להוליד ששה<sup data-n=\"772\">38</sup> בנים שהן ששה מדות חג\"ת כו', כי עיקר תולדות המדות הוא מן המח' דוקא שהרי כאשר לא יחשוב אדם בדבר מה הרי לא יתפעל ממנו כלל אם באהבה או ביראה ופחד כמ\"ש במ\"א. וז\"ש ששם<sup data-n=\"773\">39</sup> עלו שבטים שבטי י\"ה שיש ב' מיני מדות, א' שנולדים מבחי' בינה כנ\"ל והן התהוות המדות מעיקר מציאותן כמשל התינוק שמדותיו מתגדלי' ע\"י גידול השכל כנ\"ל, והב' בחי' מדות שנולדים בהתפעלות לחוץ אך שיש מציאותן כבר בלב כמו להתפעל באהבה לאוצר נחמד ומאכל טוב וכה\"ג שאין זה רק כאשר יעמיק מחשבתו בהאוצר והמאכל ואם לאו לא יתפעל כלל כו'. וז\"ש ולאה ילדה ששה בנים אחר שמקבלת מן המדות דיעקב והן שבטים דבריאה עולם המח' כו'. ויעקב לא השיג בשורש לאה בבינה אם הבנים ע\"כ אמר אעבדך ז' שנים ברחל שהי' סבור שהתולדה מהעלם אל הגילוי אינו אלא ע\"י רחל בחי' הדיבור כו'. וז\"ש בנשואי לאה ויהי<sup data-n=\"774\">40</sup> בבוקר והנה היא לאה שלא הי' יודע בה כלל מפני שהיתה למעלה ממדרגתו וע\"כ נשאת לו באופן שלא ידע בה כלל כי היא למעלה מבחי' הדעת דיעקב ע\"כ לא באה אליו בזיווג ויחוד רק בבחי' שלמעלה מן הדעת דוקא היפוך יחוד יעקב ורחל שהוא ע\"י הדעת דוקא כמו ואדם<sup data-n=\"775\">41</sup> ידע כו' וד\"ל.\n<b>ומעתה</b> יש להבין בענין מ\"ש ורחל היתה יפ\"ת וכן מ\"ש בשרה ורבקה יפ\"ת, ותחילה יש להקדים כלל א' אשר כל סיפורי מעשיות שבכל ספר הזה שהוא ספר בראשית הוא בבחי' מדריגה עליונה הרבה מכל הספרים האחרים כמו",[["769","36","<b>הוקר רגלך . . פן תשבענו והקאותו</b>: משלי כה, יז. שם, טז."],["770","*36","<b>פנימית</b>: בכת\"י ב: פנוי\"ה."],["771","37","<b>אני ישינה ולבי ער</b>: שה\"ש ה, ב."],["772","38","<b>ששה בנים . . חג\"ת</b>: ראה גם לקו\"ת להאריז\"ל פ' ויצא שם."],["773","39","<b>ששם עלו שבטים שבטי י\"ה</b>: תהלים קכד, ב."],["774","40","<b>ויהי בבוקר והנה היא לאה</b>: ויצא כט, כה."],["775","41","<b>ואדם ידע</b>: בראשית ד, א."]]],[2101920172,"ספר שמות וספר ויקרא ובמדבר כו', וגם שבספרים האלה נכתבו כל המצות שהן בחי' רצה\"ע מ\"מ ספר בראשית<sup data-n=\"776\">42</sup> למעלה מכולם, וראי' לזה ממה שמצינו במעשה<sup data-n=\"777\">43</sup> דאליעזר עבד אברהם שהוכפלו דבריו ב\"פ ובמצות הרבה לא נכתבו רק בדרך רמז וכמו שאמרו יפה<sup data-n=\"778\">44</sup> שיחתן של עבדי אבות מתורתן של בנים כו', וכה\"ג כל סיפורי מעשיות שכתב משה בספר זה גבוה הרבה גם מכל המצות הכתובים בספרי' אחרים, וע\"כ נק'<sup data-n=\"779\">45</sup> ספר בראשית בשם ספר הישר כמ\"ש הלא<sup data-n=\"780\">46</sup> היא כתובה על ספר הישר שהוא ספר בראשית דוקא כמ\"ש זה<sup data-n=\"781\">47</sup> ספר תולדות אדם. וי\"ל לכאורה למה נק' בשם ספר הישר דוקא. אך הענין הוא דפי' ישר הוא כאשר הוא ביושר בלי נטי' לכאן ולכאן, שכל דבר שנמשך ממנו קווין בנטיות לימין ושמאל וכיוצא אינו נק' ישר אבל ישר הוא דבר ההולך במישור בלי נטי' לאיזה צד כו'. וכך הוא בענין ספר בראשית שנק' ספר הישר שלמעלה מבחי' המשכות קווין לימין ושמאל כו'. כי הנה בספר שמות מתחיל בענין המצות שיש בהן בחי' התחלקות קווין לימין ושמאל כמו שידוע דרמ\"ח<sup data-n=\"782\">48</sup> מ\"ע הם מבחי' ה\"ח ושס\"ה ל\"ת הן מבחי' ה\"ג כו', אבל בספר בראשית<sup data-n=\"783\">49</sup> לא נזכר שום מצוה בבחי' המשכה למטה שהרי כל הדברי' שנזכר בספר זה אינו רק סיפורים מן אדם הראשון עד שנולדו י\"ב שבטים מיעקב וגלו לארץ מצרים, ומה שמסיים בו הספר הוא במ\"ש וימת<sup data-n=\"784\">50</sup> יוסף בן מאה ועשר שנים כו', ושרש הענין הוא כידוע דהאבות<sup data-n=\"785\">51</sup> הן המרכבה ואין<sup data-n=\"786\">52</sup> קורין אבות<sup data-n=\"787\">53</sup> אלא לשלשה שהן בחי' חג\"ת דאצי', ע\"כ כל אריכות הסיפור בספר הזה הוא בתולדות האבות ובפרטי העובדות שלהן כמו בחפירות בארות וכה\"ג ובסדר מסעותיהם כו' ובאברהם איש החסד סיפר כפי שרשו שהי' מרכבה לבחי' חסד וביצחק כפי שרשו בבחי' הגבורות והאריכות יותר הוא ביעקב להיותו בבחי' קו האמצעי כולל חו\"ג וגם ביוסף<sup data-n=\"788\">54</sup> שהוא בחי' יסוד ומסיים בו כמ\"ש וימת יוסף כו', וכ\"ז בבחי' האצי' קודם שניתנה התו' בבחי' המשכה למטה בבחי' יש מאין בהתחלקות קווין נפרדים כו', וגם שבאצי' יש קווין חג\"ת אבל המה מיוחדים בתכלית משום דאיהו<sup data-n=\"789\">55</sup> וחיוהי חד, וע\"כ נק' ספר הישר כמ\"ש",[["776","42","<b>ספר בראשית</b>: ראה גם ס' מאמרי אדה\"ז עה\"ת ח\"א ע' צב. מאמרי אדהאמ\"צ במדבר ח\"ב ע' תרמא."],["777","43","<b>במעשה דאליעזר עבד אברהם</b>: חיי\"ש כד, ב ואילך."],["778","44","<b>יפה שיחתן</b>: ראה ב\"ר פ\"ס, ח."],["779","45","<b>נק' ספר בראשית בשם ספר הישר</b>: ראה ע\"ז כה, א. מאמרי אדהאמ\"צ בראשית ע' תיד. וש\"נ."],["780","46","<b>הלא היא כתובה</b>: יהושע י, יג."],["781","47","<b>זה ספר תולדות אדם</b>: בראשית ה, א."],["782","48","<b>דרמ\"ח מ\"ע . . ה\"ח ושס\"ה ל\"ת . . ה\"ג</b>: ראה זח\"ב רעו, א. תקו\"ז בהקדמה ה, א."],["783","49","<b>בספר בראשית לא נזכר שום מצוה</b>: ראה גם תו\"א לך יא. סע\"ב. תו\"ח כאן ”רק מצות מילה לאברהם\". ולהעיר מרש\"י ר\"פ בראשית."],["784","50","<b>וימת . . מאה ועשר שנים</b>: ס\"פ ויחי."],["785","51","<b>דהאבות הן המרכבה</b>: ראה ב\"ר פמ\"ז, ו."],["786","52","<b>ואין קורין אבות אלא לשלשה</b>: ברכות טז, ב. וראה לקו\"ש ח\"ד ע' 1068. ח\"י ע' 97."],["787","53","<b>אבות . . חג\"ת דאצי'</b>: ראה מאו\"א מערכת אבות סכ\"ז. סידור שער חג הסוכות רנז, ג. ובכ\"מ."],["788","54","<b>ביוסף . . יסוד</b>: פרדס שכ\"ג (שער הכינויים) מערכת יוסף."],["789","55","<b>דאיהו וחיוהי חד</b>: תקו\"ז בהקדמה ג, ב."]]],[2101920173,"להגיד<sup data-n=\"790\">56</sup> כי ישר ה' כו', ולזה הטעם כל ספר בראשית בחי' מקור לכל מה שכתוב בספר שמות כו', ולזה גם כל סיפור הפשוט שבספר בראשית נכתב באריכות יותר מהרבה גופי תורה שלא נכתבו רק ברמז ובקצרה כמו וקשרתם לאות<sup data-n=\"791\">57</sup> כו' ודברי אליעזר הוכפלו באריכות כו' כנ\"ל וד\"ל.\n<b>ומעתה</b> יובן ג\"כ מה שנכתב בספר זה מן האמהות שהיו ג\"כ בחי' מרכבה למעלה כידוע הכל הוא למעלה בבחי' האצי' בבחי' הנוק' בבחי' ב\"ן שבכל פרצוף כמו אברהם ושרה בחי' מ\"ה וב\"ן ויצחק ורבקה כו' ויעקב ולאה ורחל הכל בבחי' האצי' שלזה ניתנה כל התורה להיות בחי' יחודים עליונים באצי' ע\"י המצות, ולזה הקדים ספר בראשית שבו נזכר עצם היחודים העליונים שבכל הפרצופים שבאצי' שהן באברהם ושרה כו' והמצות שבשאר הספרים אינו אלא לעורר ממטה למעלה כו' וד\"ל. ומעתה יובן גם בענין מ\"ש ענין יופי באמהות כמו בשרה ורבקה ובפרט ברחל שהיתה יפ\"ת ויפ\"מ כו', כללות הכוונה אינו ע\"ד הפשוט ביופי גשמי שהרי אמר שקר החן והבל היופי כו', אלא הכוונה הוא בבחי' שם ב\"ן שבכל פרצוף להיותה בחי' מקבל צריכה להיות בבחי' יופי עליון יותר מבחי' הדכר המשפיע כמ\"ש בבחי' נקבה למטה שאין<sup data-n=\"792\">58</sup> אשה אלא ליופי, וכמו שנראה בחוש בטבע הבריאה הנשים יותר יפות מן האנשים כו', לפי שהאשה מדריגתה למטה יותר מן האיש שהרי נשים<sup data-n=\"793\">59</sup> דעתן קלות כו' פיה<sup data-n=\"794\">60</sup> מלא דם כו' ע\"כ צריכה ליופי יותר משא\"כ האיש, וכמשל מי שיושב בחושך צריך לאבוקה גדולה להאיר יותר משא\"כ היושב במקום אורה כו'. וכך למעלה בבחי' המל'<sup data-n=\"795\">61</sup> שנק' אשה יראת ה' כידוע להיות שיורדת למטה מטה ביותר למקום נמוך חושך ואפילה להחיות ע' שרים כמ\"ש ומלכותו<sup data-n=\"796\">62</sup> בכל משלה כו', ע\"כ צריכה ליופי יותר, והוא ענין בחי' המשכת י\"ג מדה\"ר שנק' הארת פנים העליונים דא\"א שממשיך בחי' שע\"ה<sup data-n=\"797\">63</sup> נהורין למל' כמ\"ש יאר<sup data-n=\"798\">64</sup> ה' פניו אליך, אליך דוקא לכנ\"י שהיא בחי' המל' מטעם הנ\"ל וד\"ל.\n<b>אך</b> הנה מ\"ש ברחל יפ\"ת ויפ\"מ, ובשרה לא נאמר רק יפ\"מ, וכן ברבקה אמר טובת מראה ולא הזכיר בהן גם יפת תואר רק ברחל דוקא, הנה יובן בהקדים תחילה בביאור ענין ההפרש<sup data-n=\"799\">65</sup> בין תואר למראה ע\"ד הפשוט. דהנה ידוע שהתואר הוא תואר וציור האברים שתמונתם וסדר ציורם הוא באופן נאה ומהודר לעין כל",[["790","56","<b>להגיד כי ישר ה'</b>: תהלים צב, טז."],["791","57","<b>וקשרתם לאות</b>: ואתחנן ו, ח."],["792","58","<b>שאין אשה אלא ליופי</b>: ראה תענית לא, סע\"א."],["793","59","<b>נשים דעתן קלות</b>: שבת לג, ב. וראה מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תפט. וש\"נ."],["794","60","<b>פיה מלא דם</b>: שבת קנב, א."],["795","61","<b>המל' . . אשה יראת ה'</b>: משלי לא, ל. ראה תקו\"ז בהקדמה ו, א."],["796","62","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["797","63","<b>שע\"ה נהורין</b>: ראה סידור עם דא\"ח נב, ב בשם הזוהר. מאמרי אדהאמ\"צ בראשית ע' רפ. וש\"נ."],["798","64","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["799","65","<b>ההפרש בין תואר למראה</b>: ראה גם תו\"א ויצא כג, ב. סה\"מ תקס\"ד ע' יא."]]],[2101920174,"רואה, לפי שהתמונה של כל אבר בא במזיגה נכונה ביותר לא ארוך ולא קצר לא עגול ולא רחב יותר מכפי הצורך לנאות היופי וההידור, וכן כל אבר עם זולתו אין זה גדול מזה וכ\"א מועיל לחבירו לענין היופי וההידור שכ\"א מהן לפי הצורך במזיגה נכונה עד שבהתאחדם יחד יועילו כולם כא' לענין היופי, וזהו עיקר היופי תואר והתמונה, כמו בתואר פנים הנה יש בו ה' אברים כוללים המצח והעינים והחוטם והלחיים והפה עם לחי התחתון שבכל א' שייך ענין יופי התואר במזיגה נכונה כמו המצח לא ארוך ועגול או רחב יותר מכפי הצורך לענין היופי אלא במזיגה יפה מאוד וכן העינים לא גדולים או קטנים יותר מכפי הצורך אלא במזיגה יפה ונק' יפה<sup data-n=\"800\">66</sup> עינים כו' וכן החוטם במזיגה יפה כו' והשפתיים והלחיים יפים בתמונה נכונה ביותר עד שכ\"א מועיל לחבירו לענין היופי, שאם היו העינים גדולים גם שהלחיים והמצח והחוטם יפים בתואר הרי העינים מקלקלים כל ענין היופי וכן בשאר אברים כו', ועיקר היופי בתואר הוא בחי' התכללות מכל אבר א' לחבירו שבהשתתפם יחד יהי' כולל היופי דוקא מבין שניהם וכן מבין כולם יחד (בל\"א עּש פַאשט אֵינְש צו די אנדערע זייער), כמו הציור היפה שהגוונים מזוגים באופן נאה שכל גוון עם זולתו משתתפים ליפות זא\"ז כו' וד\"ל.\n<b>וככה</b> יובן למעלה בבחי' תואר העליון שהוא בבחי' כלים המגבילים ומתארים את האור בתואר יפה במזיגה נכונה, והוא כמו בחי' התכללות המדות כאשר מתכללים זע\"ז במזיגה יפה דוקא כמו נצח שבגבורה שבחסד עם נצח שבחסד שבגבורה, וכן בשאר כמה מיני התכללות כשהוא באופן טוב ויפה נק' טוב תואר במדות, כמו עד\"מ כאשר האדם טוב במדותיו יותר מדאי אין זה יפה וכאשר רע במדותיו יותר מדאי אין זה יפה אלא כאשר ממוזגים מדותיו במזיגה יפה ונכונה הוא הנק' איש יפה בתואר המדות, דהיינו שבחי' הכלים המתארים אורות המדות מתארים יפה ממוזג בכי טוב בלי נטי' לאיזה צד יותר מזולתו אלא אדרבה משתתפי' יחד להיות מבין אמצעות כולם בחי' היופי בתואר המדות כו' ונק' איש יפה במדות, וכה\"ג הוא ענין יופי התואר בפנים ששם המוחין שהוא עיקר יופי האדם כמו יוסף<sup data-n=\"801\">67</sup> שהי' יפ\"ת כו' דהיינו שחמשה האברים מצח ועינים כו' כולם בתואר יפה במזיגה נכונה כנ\"ל, ולמעלה היינו ג\"כ בחי' התכללות דד' שמות ע\"ב ס\"ג מ\"ה ב\"ן. דהנה ידוע בענין ראי'<sup data-n=\"802\">68</sup> שמיעה ריח דיבור שהם לנגד ד' אותיות דשם הוי', יו\"ד בחכ'<sup data-n=\"803\">69</sup> הוא בבחי' הראי' דעינים כשהן ממוזגים יפה כנ\"ל והוא בחי' שם ע\"ב<sup data-n=\"804\">70</sup> כמו עיני<sup data-n=\"805\">71</sup> העדה שהן בבחי' ע\"ב דחכ' כללות נש\"י דכתיב עינייך<sup data-n=\"806\">72</sup> כו'",[["800","66","<b>יפה עינים</b>: לשון הכתוב שמואל-א טז, יב."],["801","67","<b>יוסף שהי' יפ\"ת</b>: וישב לט, ו."],["802","68","<b>ראי' שמיעה ריח דיבור . . ד' אותיות</b>: ראה ע\"ח שער אח\"פ (ש\"ד) פ\"א."],["803","69","<b>בחכ' . . הראי'</b>: ראה ס' מאמרי אדה\"ז עה\"ת ח\"א ע' רסד ובהנסמן לשם. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תעא. וש\"נ."],["804","70","<b>בחכ' . . שם ע\"ב</b>: ראה ע\"ח שער טנת\"א (ש\"ה) פ\"א ובמפרשים שם."],["805","71","<b>עיני העדה</b>: ע\"פ שלח, טו, כד."],["806","72","<b>עינייך כו' אפך כמגדל</b>: שיר השירים א, טו. ד, א. שם ז, ה."]]],[2101920175,"אפך כמגדל כו', ושמיעה<sup data-n=\"807\">73</sup> בבינה שהוא בחי' ס\"ג שבבחי' אוזן<sup data-n=\"808\">74</sup>, וריח דחוטם בבחי' וי\"ו, ופה דיבור בחי' ה\"א בחי' ב\"ן, והמצח<sup data-n=\"809\">75</sup> הוא בבחי' הרצון שהוא בחי' כתר שלמעלה מהפנים שהן המוחין והלחיים תרין תפוחים כו' שם המזיגה בתמונה מהארת מקור המוחין כו' וכמ\"ש נאוו<sup data-n=\"810\">76</sup> לחייך בתורים וכה\"ג, וכל ד' שמות אלה הם ממוזגים יפה בלי יתרון לא' יותר על חבירו רק כפי הצריך ליופי תואר הפנים ע\"ד הנ\"ל בתואר המדות כו' וד\"ל.\n<b>וזהו</b> ורחל היתה יפ\"ת, בחי' רחל הוא בחי' עלמא דאתגלייא כידוע, ודוקא רחל היתה יפ\"ת לפי שבחי' המל' עיקר בנינה מבחי' התכללות כל האורות עליונים בבחי' מזיגת הכלים מכלים שונים, כמו מבחי' מזיגת התכללות דמל' שבחסד דז\"א עם מל' שבגבורה כו' מאיר במל' בחי' מזיגה זו וכך שאר כל התכללות דכלים דז\"א (וכמ\"ש<sup data-n=\"811\">77</sup> במ\"א בפי' למרבה המשרה), וע\"כ נק' כלה<sup data-n=\"812\">78</sup> שכלולה מהכל, וע\"כ רחל היתה יפ\"ת בפנים בד' שמות דע\"ב ס\"ג מ\"ה וב\"ן, ולכך יעקב<sup data-n=\"813\">79</sup> שהוא בחי' ת\"ת אהב את רחל (כי שופרי'<sup data-n=\"814\">80</sup> דיעקב כו' שהוא בחי' יחוד ת\"ת ומל' כידוע), משא\"כ שרה ורבקה גם שהן ג\"כ בחי' ב\"ן אבל הן בפרט מיוחד, כמו שרה בחכ' ב\"ן דמ\"ה דחכ'<sup data-n=\"815\">81</sup> מקור החסד כו', ורבקה בבחי' בינה, וע\"כ שרה נק' יפ\"מ ורבקה טו\"מ מאד, כי חכמת<sup data-n=\"816\">82</sup> אדם תאיר פניו נק' יפ\"מ דחסד<sup data-n=\"817\">*82</sup> מקור החכ' כו' ורבקה שהיא בחי' בינה שם גילוי התענוג נק' טו\"מ מאוד, אבל יפ\"ת אינו רק בחי' רחל מטעם הנ\"ל וד\"ל.\n<b>ובחי'</b> יפ\"מ הוא האורות המקיפי' המאירי' בפנים כמו חכמת אדם תאיר פניו, והענין הוא שהרי ידוע ההפרש בין תואר למראה שהתואר רק בציור יופי התמונה בלבד כנ\"ל, אבל המראה הוא מראה וגוון אור הפנים אם במראה לובן או במראה אודם אם הלובן זך ובהיר והאודם זך ובהיר וממוזג יפה זהו הנק' יופי במראה ואם אין האודם ולובן במזיגה יפה ונכונה אלא לבן ביותר מדאי או אדום יותר מדאי והתכללותם יחד אינו במזיגה כפי הצריך לענין היופי במראה אין זה יופי במראה כידוע. והנה ידוע ג\"כ שהיופי במראה זך ובהיר כפי הצריך לענין היופי וההידור במראה הוא הנק' הארת פנים שהפנים מאירים כמו אור המאיר ממש, כמו חכמת אדם תאיר פניו אור ממש וכן יאר ה' פניו באור<sup data-n=\"818\">83</sup> פניך יהלכון",[["807","73","<b>ושמיעה בבינה</b>: זח\"ג קלח, ב. מאמרי אדהאמ\"צ בראשית ע' כח. וש\"נ."],["808","74","<b>בבינה . . ס\"ג . . אוזן</b>: ראה ס' מאמרי אדה\"ז עה\"ת ח\"א ע' שכז ובהנסמן לשם."],["809","75","<b>והמצח . . הרצון</b>: ראה זח\"ג קכט, א. קלו, ב."],["810","76","<b>נאוו לחייך בתורים</b>: שיר השירים א, י."],["811","77","<b>(וכמ\"ש . . למרבה המשרה)</b>: ראה ד\"ה זה הנדפס לעיל בס' זה."],["812","78","<b>מל' . . נק' כלה</b>: ראה פרדס שכ\"ג (שער ערכי הכינויים) מערכת כל כלה."],["813","79","<b>יעקב . . ת\"ת</b>: זח\"א ויצא קנז, ב."],["814","80","<b>שופרי' דיעקב</b>: ב\"מ פד, א."],["815","81","<b>דחכ' מקור החסד</b>: ראה מאמרי אדהאמ\"צ בראשית ע' תקי. וש\"נ. דברים ח\"א ע' רלז. וש\"נ."],["816","82","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["817","*82","<b>דחסד מקור החכ'</b>: כ\"ה בכת\"י המעתיק כאן."],["818","83","<b>באור פניך יהלכון</b>: תהלים פט, טז."]]],[2101920176,"וכה\"ג, וכן אמרו פני<sup data-n=\"819\">84</sup> משה כפני חמה כו', וכמו צהבו<sup data-n=\"820\">85</sup> פניו של רבי וכה\"ג, והטעם הוא להיות שהמראה בפנים בא מבחי' אור המקיף דוקא שמאיר בפנים כמו מקיף דחכ' תאיר פניו בלחיים וכן איזה שמחה גדולה שבאה מבחי' מקיף דוקא יצהבו מראה הפנים ויאירו במראה יפה, ולהיפוך מבשורה רעה יתלבן הפנים ונק' פנים רעים וחשוכים כמו מדוע<sup data-n=\"821\">86</sup> פניך רעים כו', ע\"כ נק' הארת פנים דוקא וד\"ל. וכך יובן למעלה במ\"ש יאר הוי' פניו אליך שהוא מבחי' המקיפים די\"ג מדה\"ר כו' ואין אשה אלא ליופי לקבל מבחי' היופי העליון שבפנים העליונים שבא\"א מטעם הנ\"ל באריכות. וזהו שהיתה רחל יפ\"ת ויפ\"מ ג\"כ בבחי' התכללות במזיגה יפה כמו בענין יופי התואר בבחי' הכלים שהן האברים כנ\"ל וד\"ל (אבל שרה ורבקה גם הם מקבלים מהארת פנים ע\"כ נק' יפ\"מ או טו\"מ כו' אבל בדרך פרט ולא בדרך כללות הכל כרחל ע\"כ העידה התורה עלי' ורחל היתה יפ\"ת ויפ\"מ כו' אשר לא העידה התו' על שרה ורבקה כו' רק על רבקה נאמר והנערה טו\"מ כו' וד\"ל) (ומ\"ש שלמה שקר החן והבל היופי קאי גם על בחי' יפ\"מ שבמל' שאינו מתקיים רק לפי שעה מפני יניקת החיצוני' שמחשכי' וגם מצד עצמן שאינו בבחי' אמת דקו אמצעי, רק אשה יראת ה' היא תתהלל משום דנעוץ<sup data-n=\"822\">87</sup> תחילתן בסופן וסופן בתחילתן למעלה מעלה בבחי' הארת פנים דמקיף דחכ' כו' שהוא בבחי' קיום נצחי דנצחיות אא\"ס ב\"ה כידוע וד\"ל).\n<b>והנה</b> עדיין יש לתרץ הקושי' דלעיל במ\"ש יעקב אעבדך שבע שנים, למה מעצמו אמר ז' שנים דוקא אולי הי' לבן מתרצה גם בב' וג' שנים. אך הנה יש להבין עוד במ\"ש לבן ליעקב מלא<sup data-n=\"823\">88</sup> שבוע זאת וניתנה לך גם את זאת בעבודה אשר תעבוד עוד ז' שנים כו', דשבוע זאת היינו ז' ימי המשתה כדפי' רש\"י וכמשמעות שאמר בעבודה אשר תעבוד כו' ואח\"כ נאמר ויעש<sup data-n=\"824\">89</sup> יעקב כו' וימלא שבוע כו' ויבא גם אל רחל כו' ואח\"כ ויעבוד כו', דלפי זה בשביל לאה עבד ז' שנים בתחילה ובשביל רחל לא המתין רק ז' ימי המשתה והעבודה שעבד היתה אחר הנשואין כו'.\n<b>והנה</b> להבין כ\"ז יש להקדים שורש ענין בחי' יעקב ורחל, כי הנה כתיב כרחל<sup data-n=\"825\">90</sup> לפני גוזזי' נאלמה שטבע הרחל שתניח א\"ע לגזוז שערה שעיקר הצורך בה לצמרה ושערה ע\"כ נאלמה לפני גוזזי', ולמעלה היינו סוד גלות השכינה בע' שרים שנאמר נאלמתי<sup data-n=\"826\">91</sup> דומי' כו' שע'<sup data-n=\"827\">92</sup> שרים מקבלי' יניקה מבחי' שערות דעור",[["819","84","<b>פני משה כפני חמה</b>: ב\"ב עה, סע\"א."],["820","85","<b>צהבו פניו של רבי</b>: חולין ז, ב."],["821","86","<b>מדוע פניך רעים</b>: נחמי' ב, ב."],["822","87","<b>דנעוץ תחילתן בסופן וסופן בתחילתן</b>: ספר יצירה פ\"א מ\"ז."],["823","88","<b>מלא שבוע זאת</b>: ע\"פ ויצא כט, כז."],["824","89","<b>ויעש יעקב . . ויבא . . ויעבוד</b>: ויצא שם כח. ל."],["825","90","<b>כרחל לפני גוזזי' נאלמה</b>: ישעי' נג, ז. וראה לקו\"ת מסעי פח, ג. ובכ\"מ."],["826","91","<b>נאלמתי דומי'</b>: תהלים לט, ג."],["827","92","<b>שע' שרים מקבלי' . . מבחי' שערות</b>: ראה פירוש המלות לאדהאמ\"צ נז, א ואילך. ובכ\"מ."]]],[2101920177,"הנוק' שנק' רחל עקרת הבית כידוע, והיינו שנאלמה לפני גוזזי' בהיות שמקבלי' בבחי' הפירוד, משא\"כ בלי גזיזה הרי השערות טפלים ובטלים לגבי הרחל כו', וכמו בימי שלמה ודוד שהיו כל אומה\"ע נכנעים מאוד תחת מל' ישראל ומביאים מנחה ומסייעים כו', אבל בזמן הגלות אומרים ידינו<sup data-n=\"828\">93</sup> רמה כו' כוחי ועוצם ידי כו' לי יאורי כו' וכה\"ג. ונמצא שבחי' המל' נמשל לרחל ע\"ש השערות.\n<b>וכך</b> יובן למעלה בכמה מיני מדריגות אורות עליונים שנק' צאן<sup data-n=\"829\">94</sup> כמו צאינה וראינה בנות ציון כו', והוא עיקר ענין בחי' יעקב שהי' רועה צאן דוקא, שהרי אברהם<sup data-n=\"830\">95</sup> ויצחק הי' להם גם בקר וחמורים ואתונות וגמלים ויעקב לא הי' לו רק צאן (ומ\"ש ויהי<sup data-n=\"831\">96</sup> לי שור וחמור כו' זהו לאחר שנתעשר מן ריבוי הצאן כו'), וכל עבודתו הי' לרבות צאן בתחבולות שונות כמו ליחמנה<sup data-n=\"832\">97</sup> במקלות כו' כמבואר בפ' והי' משגיח עליהם במאכל מרעה ולהשקותם ברהטים כו' בטיב ההשגחה יותר מהכל כמבואר בפ', שהרי לא נזכר עבודה תמה כזו בצאן באברהם ויצחק רק ביעקב לבדו כו'. והענין הוא לפי ששורש יעקב הוא מבחי' התיקון שהוא רק בחי' ההתכללות דחו\"ג בכל מיני אופני התכללות, והוא ענין עקודים<sup data-n=\"833\">98</sup> נקודים ברודים וטלואים כו', להיות שרש בחי' יעקב<sup data-n=\"834\">99</sup> הוא ממדת הרחמים שהרחמים הוא עיקר בחי' התיקון בהתכללות דחו\"ג כו', כי הנה גם שחו\"ג עצמן הוא כלול כ\"א מזולתו כידוע שחסד כלול מן הגבו' ונק' גבורה שבחסד וכן חסד שבגבורה כו', כמ\"כ יש ריבוי פרטי התכללות כמו נצח שבגבורה שבחסד עד הוד שבחסד שבגבורה וכה\"ג, מ\"מ אין כל אלה בחי' התכללות אמיתית שהרי כל מה שמתחלק החסד לפרטי פרטיות כמה פעמים אין זה רק בבחי' מהות החסד עצמו וכן הגבורה בהתחלקו' פרטיות הכל בבחי' הגבורה רק מפני ריבוי ההתחלקות יוכל להיות ריבוי ההתכללות כמשל הרכבת דד' יסודות כו' כידוע, משא\"כ מדת הרחמים הרי היא מדה בפ\"ע שכולל החו\"ג, והתכללות זאת הוא ענין ביטול שניהם, שהרי ענין הרחמנות כך הוא שאעפ\"י שחייב עונש עפ\"י הדין מכ\"מ רחמנות יש עליו ונפטר מן העונש מצד הרחמנות, הרי בטלה מדה זו לחסד מאחר שאין הפטור רק מצד הרחמנות ואדרבא נותן מקום למדת הדין לומר שהוא חייב עונש רק שהרחמנות מבטלו וא\"כ יבטל להחסד לומר שאינו ראוי לו",[["828","93","<b>ידינו רמה . . כוחי ועצם ידי . . לי יאורי</b>: האזינו לב, כז. עקב ח, יז. יחזקאל כט, ג."],["829","94","<b>צאן כמו צאינה וראינה</b>: שה\"ש ג, יא. ראה סה\"מ תקס\"ה ח\"ב ע' תתמ. מאמרי אדהאמ\"צ בראשית ע' רכא. וש\"נ. לקו\"ש חט\"ו ע' 254. וש\"נ."],["830","95","<b>אברהם . . הי' . . בקר וחמורים</b>: לך יב, טז."],["831","96","<b>ויהי לי שור וחמור</b>: וישלח לב, ו. בתו\"ח בראשית ל, ג מציין בענין זה לפרש\"י (ויצא ל, מג)."],["832","97","<b>ליחמנה במקלות . . ברהטים</b>: ויצא ל, מא."],["833","98","<b>עקודים נקודים ברודים וטלואים</b>: ויצא ל, לט. לא, י."],["834","99","<b>יעקב הוא ממדת הרחמים</b>: ראה זח\"א פז, ב. תניא פמ\"ה. מאמרי אדהאמ\"צ בראשית ע' קנו. וש\"נ."]]],[2101920178,"ויבטל גם להדין ונמצא מתכללים חו\"ג התכללות אמיתית יותר מהתכללות עצמן כו' וד\"ל.\n<b>והנה</b> זהו עיקר בחי' יעקב בבחי' הרחמי' בכלל דחו\"ג וכל עבודתו הי' להוליד בחי' רחמים בכל פרט ופרט שבחו\"ג, מאחר שכל פרט דחסד כלול מחו\"ג כמו גם נצח שבחסד שבגבורה שבחסד יש בו ג\"כ חו\"ג ובחי' רחמים שבו כלולים כו', וזהו הי' עבודתו לעשות ריבוי התולדה בצאן שלמעלה מן התחלקו' ריבוי מיני רחמים בפרט כו' וכמ\"ש ורחמיו<sup data-n=\"835\">100</sup> על כל מעשיו הנמשך מכל פרטי המדות כנ\"ל, והיינו פי' רחמיך הרבים ל' ריבוי ההתחלקות, וזה תלוי בר\"ר דכתר שלמעלה מן החכ' כו' לפי שבריח התיכון כו' כידוע, וע\"כ הי' יעקב רועה צאן יותר מכולם, וכמו שנראה בקול הצאן שמעוררים בחי' רחמים יותר מקול שארי בהמות זולתם כידוע. וזהו שאהב יעקב לרחל כי שמא גרים רחל ממש כי בחי' המל'<sup data-n=\"836\">101</sup> נק' רחל, וגם להיותה רועה צאן ג\"כ וכמ\"ש ורחל<sup data-n=\"837\">102</sup> באה עם הצאן אשר לאבי' כי רועה היא כמ\"ש בזוהר כו' וד\"ל.\n<b>וזהו</b> שאמר יעקב אעבדך ברחל ז' שנים ולכאורה הל\"ל בעבור ומהו ברחל כו', אך הנה פי' ברחל היינו בתוך בחי' רחל כו'. דהנה ידוע בבחי' רחל למעלה שהוא עולם הדיבור בחי' עלמא דאתגלי' וכל עבודת יעקב הי' רק להמשיך בחי' רחמים בכל העולמות ודוקא בעלמא דאתגלי', והיינו אעבדך ז' שנים ברחל להמשיך ז' מדות עליונות ברחל בתוך עלמא דאתגלי' בחי' רחל עקרת הבית והן ז' שנים עליונים, כידוע בפי' ויהיו חיי שרה מאה כו' ושבע שנים כו' אלה שני חיי שרה וקאי על בחי' ז' השנים דסמוך לי' שהן עיקר שני חיי שרה<sup data-n=\"838\">103</sup> שהוא בחי' המל'<sup data-n=\"839\">104</sup> שנק' מטרוניתא כידוע, וגם כאן אמר יעקב אעבדך שבע שנים, בשנה הראשונה המשיך בחי' החסד ובשנה הב' מבחי' הגבו' כו' שהן מבחי' ז' מדות דאצי' כמ\"ש לך<sup data-n=\"840\">105</sup> הוי' הגדולה והגבורה כו' כידוע. והנה מה שהוצרך לז' מדות דוקא הענין הוא כי שרש בחי' יעקב הוא בחכ' שהוא יו\"ד דיעקב יו\"ד עק\"ב כו' ורצה להמשיך בחי' חכ' במל' שהוא בחי' רחל עקרת הבית כו' שנק' חכ' תתאה להנהגת עולמות, כמו עד\"מ דבר מלך כו' הנה בדיבורו מתגלה כל בחי' מדותיו כו' אם דברי אהבה וחסד או דברי רוגז ודין כו' הכל יוצא דרך הדיבור כו', אך מפני ריחוק ערך המל' מבחי' ח\"ע ע\"כ הוצרך יעקב לעבוד ז' שנים תחילה שהוא להמשיך לבחי' ח\"ע דרך בחי' הז' מדות ומז' המדות נמשך ברחל עלמא דאתגלי' כו'. והוא ענין בחי' התיקון וההתכללות של המדות בבחי' הרחמים שהוא ע\"י שם",[["835","100","<b>ורחמיו על כל מעשיו</b>: תהלים קמה, ט."],["836","101","<b>המל' נק' רחל</b>: פרדס שכ\"ג (שער ערכי הכינויים) מערכת רחל."],["837","102","<b>ורחל באה עם הצאן</b>: ויצא כט, ט. ראה זח\"ג קפז, סע\"א. סה\"מ תקס\"ה ח\"ב ס\"ע תרצה ואילך."],["838","103","<b>שרה . . המל'</b>: ראה ס' מאמרי אדה\"ז עה\"ת ח\"א ע' קלז. וש\"נ."],["839","104","<b>המל' שנק' מטרוניתא</b>: ראה אגה\"ק סכ\"ה (קלט, א)."],["840","105","<b>לך הוי' הגדולה והגבורה</b>: דברי הימים-א כט, יא."]]],[2101920179,"מ\"ה דחכ' דוקא כידוע, וזהו אעבדך לבחי' לובן העליון ז' שנים ברחל בתך הקטנה שהיא בחי' המל' שיורדת למטה מטה בבחי' הקטנות כי רועה צאן היא כנ\"ל. ובזה מתורץ הקושי' דלעיל למה לא אמר ב' וג' שנים, כי ידע שצריך לעבוד ז' שנים דוקא מטעם הנ\"ל וד\"ל.\n<b>ומעתה</b> יש להבין מ\"ש מלא שבוע זאת כו', דהנה לבן רמה את יעקב אחר שהשלים טוב עבודתו בבחי' התיקון בז' שנים ז' המדות בשביל רחל נתן לו את לאה שהיא בחי' עלמא דאתכסי' עולם המח', כי הנה לבן ראה שכל עיקר עבודת יעקב הוא להביא בחי' החכ' במדות בשביל אותיות הדיבור שיבוא הכל לידי גילוי אותיות, וא\"כ גם בחי' אותיות המח' בחי' אותיות הן, כמו עד\"מ מה שחפץ בלב מחשב באותיות המח' הרי מתלבש המדה שבלב בבחי' צירופי אותיות דמח', ואין הפרש כלל בין אותיות המח' לאותיות הדיבור שניהם אותיות וכלים להכיל המדות רק במח' האותיות בהעלם ובדיבור באים האותיות בגילוי אבל הצירופי' אחד הן שאותו הצירוף שרוצה לדבר חושב במח' וכן מה שחושב במח' מדבר בדיבור בצירוף א' בלי שינוי כלל, וכידוע דה\"ג<sup data-n=\"841\">106</sup> מנצפ\"ך המחלקות צירופי אותיו' הדיבור הן הן מבחי' ה\"ג מנצפ\"ך דאימא שמחלקת צירופי אותיות המח' כו', ולזה הטעם נתן ליעקב את לאה מטעם שאמר שאין<sup data-n=\"842\">107</sup> ראוי לתת את הצעירה לפני הבכירה כי המח' קודמת לדיבור כידוע וד\"ל.\n<b>אך</b> אחר שהי' יחוד יעק\"ב ולאה אמר לו מלא שבוע זאת כו' שהוא לאחר ז' ימי המשתה ולא הי' צריך לעבוד ז' שנים תחילה אלא לאח\"כ כנ\"ל. כי הנה עיקר העבודה הוא להביא את ז' המדות באותיות, כמו ע\"ד דוגמא ביו\"ד מאמרות דכתי' ויאמר<sup data-n=\"843\">108</sup> אלקי' יהי אור הרי מבחי' אור החסד דאצי' הנמשך ביום הא' נברא ממנו האור ע\"י צירופי אותיות הללו דמאמר יהי אור, וכן ביום הב' בחי' הגבורה נברא הרקיע ע\"י אותיות יהי<sup data-n=\"844\">109</sup> רקיע להבדיל כו' שנעשה צירופי אותיות הדיבור להכיל ולהגביל אור המדות ואם לאו לא הי' נברא בריאה יש מאין מאור המדות עצמן כידוע. וכך הוא בענין עבודת יעקב ז' שנים להביא בבחי' אותיות, אבל כאשר כבר באו המדות באותיות המח' ונתייחדו בה שזהו בחי' יחוד יעקב ולאה אז קרוב הדבר ממילא ומאיליו שיומשך ג\"כ אור שפע המדות גם בצירופי אותיות הדיבור שהוא בחי' רחל כו', כי מן המח' אל הדיבור אין זה עבודה כ\"כ כי בנקל לבוא העלם המח' לגילוי הדיבור כי צירופי' אחד הן בשרשן בבחי' ה\"ג מנצפ\"ך דאימא כו' כידוע דאימא<sup data-n=\"845\">110</sup> אוזיפת מנהא לברתא וכנ\"ל.",[["841","106","<b>דה\"ג מנצפ\"ך</b>: ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רלז. וש\"נ. דברים ח\"ג ע' א'כג. ואילך."],["842","107","<b>שאין . . הצעירה לפני הבכירה</b>: ויצא כט, כו."],["843","108","<b>ויאמר אלקי' יהי אור</b>: בראשית א, ג."],["844","109","<b>יהי רקיע להבדיל</b>: ראה בראשית א, ו."],["845","110","<b>דאימא אוזיפת מנהא לברתא</b>: ראה זח\"א ב, א. מאמרי אדהאמ\"צ דברים ח\"א ע' רלו. וש\"נ."]]],[2101920180,"<b>וז\"ש</b> מלא שבוע זאת רק בז' ימי משתה ושמחה ונתנה לך גם את זאת<sup data-n=\"846\">111</sup> שהוא בחי' המל' כמ\"ש בזאת<sup data-n=\"847\">112</sup> יבוא כו', ודוקא בז' ימי משתה ושמחה לפי שהשמחה מביאה מן ההעלם לגילוי כנראה בחוש שבשעת שמחה מגלה מצפוני לבבו בדיבור כו', וע\"כ בז' ימי משתה ושמחה יוכל להיות יחוד יעקב ורחל בחי' הדיבור בלי שיצטרך עבודה ז' שנים בתחילה דוקא כי כבר עבד ז' שנים בשביל גילוי אותיות וא\"צ רק להביא מן ההעלם לגילוי בלבד כו'. אך הנה לפ\"ז למה הוצרך לעבוד גם ז' שנים אחרות גם אחר נישואי רחל מאחר שזכה בה על ידי שמחה של ז' ימים מטעם הנ\"ל. אבל באמת ז' שנים שעבד לאחר נישואי רחל הוא להיות בחי' תולדה של השבטים שהוא בעולם הבריאה יש מאין שהי' יעקב סבר שיולדו לו מרחל דוקא, אך כאשר ראה ששנואה<sup data-n=\"848\">113</sup> לאה ויפתח את רחמה ורחל עקרה כו' וד\"ל.",[["846","111","<b>זאת . . המל'</b>: פרדס שכ\"ג (שער ערכי הכינויים) מערכת זאת."],["847","112","<b>בזאת יבוא</b>: אחרי טז, ג."],["848","113","<b>ששנואה לאה . . ורחל עקרה</b>: ויצא כט, לא."]]],[2101920181,"<h3>ענין מארז\"ל כל הקורא ק\"ש</h3>\n<b>ענין</b><sup data-n=\"849\">1</sup> מארז\"ל כל הקורא<sup data-n=\"850\">2</sup> ק\"ש בלא תפילין כאילו הקריב עולה בלא מנחה וזבח בלא נסכים, מה ענין זה לזה, יש להקדים תחלה כל עיקר הקרבנות והנסכים מהו. כי הנה הקרבנות נק' בשם אכילה כמשרז\"ל<sup data-n=\"851\">3</sup> ע\"פ ואם האכל יאכל בשתי אכילת הכתוב מדבר א' אכילת אדם ואחת אכילת מזבח וארז\"ל במגילה והשתי'<sup data-n=\"852\">4</sup> כדת של תורה אכילה מרובה משתי' שהנסכים נק' בשם שתי' וקרא כתי' לחמי<sup data-n=\"853\">5</sup> לאשי כו' וזה פלאי שהקב\"ה אוכל ושותה כביכול, הנה ביין כתי'<sup data-n=\"854\">6</sup> גבי יותם שהיין משמח אלקים ולהבין זה מה ענין השמחה לאלקים מן היין, צ\"ל תחלה כל עיקר ענין מהות השמחה גם באדם מה ענינה, כי הנה בכל דבר יש פנימיות וחיצוני' פי' מה שהוא בחי' משפיע לזולתו נק' חיצוניותו ומה שמקבל מלמעלה",[["849","1","<b>ענין מארז\"ל</b>: נדפס מגוכי\"ק הצ\"צ בס' תקע\"ב. ונמצא ג\"כ בס' מאמרי אדה\"ז על מארז\"ל ע' כח. ובשינויים ובתוס' הגהות בלקו\"ת שלח מא, ג. ובאריכות בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'קפח ואילך. ובשינויים באוה\"ת על מארז\"ל וענינים ע' ג. וראה עוד בהנסמן על מאמר זה בהמ\"מ ללקו\"ת שם (הוצאת תשד\"מ). וראה להלן ד\"ה אכלו רעים ששייך ג\"כ למאמר זה."],["850","2","<b>כל הקורא ק\"ש בלא תפילין</b>: ברכות יד, ב."],["851","3","<b>כמשרז\"ל ע\"פ ואם האכל יאכל</b>: פ' צו ז, יח. בלקו\"ת שם מציין: ”פ\"ק דזבחים י\"ג ב' כ\"ח ב' ושאר דוכתי\"."],["852","4","<b>והשתי' כדת של תורה</b>: מגילה יב, א. וראה עוד בארוכה בד\"ה על מארז\"ל זה בסה\"מ תקס\"ג ח\"ב ע' תקסו ואילך."],["853","5","<b>לחמי לאשי</b>: פינחס כח, ב."],["854","6","<b>כתי' גבי יותם שהיין משמח אלקים</b>: ראה שופטים ט, יג."]]],[2101920182,"הימנו הוא פנימיותו כמו בגשמיו' אין<sup data-n=\"855\">7</sup> לך עשב שאין לו מזל רוחני המכה בו ואומר לו גדל, ירקות מן הלבנה והגפן מהחמה ופירות מהכוכבים כו' והיינו מן הרוחני' שבהם, והנה מה שהם משפיעי' למטה נק' חיצוניותם ומה שהם בחי' מקבלים מלמעלה מהם כמו שאנו אומרים ומקבלים דין מן דין הוא פנימיותם, עם היות כי ברוחנית לא שייך התחלקו' לומר חלק זה פנימי וזה חיצוני אלא כולו אחד רק שכלול מב' כחות א' שמקבל וב' שמשפיע ולזאת נק' ב' בחינות כמו הבחינות שבכסף שהוא כך וכך בחי' על היות בו כך וכך בחי' סיגי' והרי אעפ\"כ אינן בהתחלקות אדרבה שהם מעורבי' זב\"ז בתכלי' עד שכולו כאחד רק שיש בו בכללותו ב' ענינים שוני' כסף וסיג ונק'<sup data-n=\"856\">8</sup> בחינות כו', וכמ\"כ יובן מזה גם בבהמה שיש בה חיות רוחניות ונלקח מפני שור שבמרכבה הרוחני ויש בה ב' בחי' אלו א' מה שהחיות נמשך ומתפשט בגופה וב' מה שמקבל חיות ממקורו, וכן גם באדם שיש לו גם נפש המשכלת הנמשכת מפני אדם ומתפשט ומתלבש במוח שבראש הרי מובן ביותר ב' הבחי' הנ\"ל א' מה שמתפשט להחיות הגוף נק' חיצוניותו וב' מה שמקבל ממקורו כו', ובאמת יש בכל א' ג' בחי' א' פנים פי' שפונה למעלה ב' מה שפונה למטה להשפיע ג' עצמיותו שהוא הממוצע וכידוע זה בל' עו\"ע שכל עילה דבוק בעילתו כו' והן ג\"כ בחי' ג' אבות אברהם<sup data-n=\"857\">9</sup> איש החסד ונמשל למים שיורדי' מגבוה לנמוך להשפיע למטה ויצחק בחי' אש שפונה למעלה ויעקב הוא המחבר ונק' בריח התיכון כו'.\n<b>והנה</b> ענין השמחה הוא התגלות הפנימי' ולכך נעשה אדום ופניו צהובות כי החיות הרוחני נובע ומתגלה בדמים כו' ולכן נכנס<sup data-n=\"858\">10</sup> יין גשמי יוצא סוד התגלו' הפנימי' הרוחני' כי היין אינו אלא רק מעורר שעל ידו מתגלה הפנימי' ואז נהפך לאיש אחר ממש כנרא' בעליל, ועד\"ז יובן ג\"כ ענין משמח אלקים כי ואתה<sup data-n=\"859\">11</sup> מחי' את כולם כתי' וחיות זה הוא בבחי' השתלשלות בכל עולם לפי ערכו ותכונתו, בעולם השפל שלנו החיות הוא בדצח\"מ גשמיים ובעולם המלאכי' ברוחני' ולמעלה מהם בעולם הנשמות כו', וא\"כ הנה בכל בחי' החיות שבכל עולם יש בו ב' בחי' הנ\"ל א' מה שמשפיע למטה הימנו ב' מה שמקבל מלמעלה ממנו כמ\"ש גבוה<sup data-n=\"860\">12</sup> מעל גבוה שומר וגבוהים עליהם, ופי' משמח אלקים היינו להיות א\"ס ב\"ה נמשך מהעלם לגלוי וכמ\"ש יאר<sup data-n=\"861\">13</sup> ה' פניו אליך שפנימיותו מתגלה והיינו ע\"י ניסוך היין שהוא ג\"כ בחי' גלוי ההעלם שנסחט מן הענבים.\n<b>ועתה</b> יובן ענין הקרבנות שנקראי' אכילה כי כמו עד\"מ אכילת האדם שניזון ממאכלים גשמיי' שלמטה בערך ממנו שע\"י שמתבררי' באצטומכא ונדחה",[["855","7","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. ועוד."],["856","8","<b>ונק' בחינות כו'</b>: ראה אוה\"ת על מארז\"ל וענינים (הנ\"ל) ס\"ע ד, ובהנסמן בשוה\"ג שם."],["857","9","<b>אברהם איש החסד</b>: ראה בהנסמן בהמ\"מ בס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תקפ."],["858","10","<b>נכנס יין</b>: עירובין סד, א. וש\"נ."],["859","11","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["860","12","<b>גבוה מעל גבוה שומר</b>: קהלת ה, ז."],["861","13","<b>יאר ה' פניו אליך</b>: במדבר ו, כה."]]],[2101920183,"הפסולת ומהמובחר נעשה חיות ומחבר הנפש עם הגוף ואם לא יאכל כמה ימים יוכל למות מחמת רעב כו' כך הוא ענין הקרבנות מבהמות גשמיות שנפשותן נלקח' מפני שור שבמרכב' כנ\"ל וכשמקריבי' אותם ושורפי' גופם ע\"ג המזבח אזי נפשם עולה ומתכללת במקורה הוא בחי' פני שור שבמרכבה וגורם עי\"ז המשכת והתחברות א\"ס ב\"ה בעולמות כו'.\n<b>והענין</b> דכמו הלחם הגשמי מחבר הנפש עם הגוף ע\"י שמתברר תחלה באצטומכא ונדחה הפסולת והמובחר הוא שנעשה ממנו חיות ועליו נאמ' לחם לבב אנוש יסעד שסועד הלב ומגביהו להיות עי\"ז בו המשכת והתפשטות החיות מן המוח כך יש למעלה מלאכי'<sup data-n=\"862\">14</sup> הנק' קרביי' ומיעי' כמ\"ש המו מיעיי לו המבררים את נפש הבהמ' העולה ממטה למעלה הנק' בשם לחם והפסולת נדחה לחוץ ומתהוי' מזה כל טוב גשמי בברכת הארץ להצמיח פירות כו', נ\"ל<sup data-n=\"863\">15</sup> ע\"ד פסל<sup data-n=\"864\">16</sup> לך מפסולתן של לוחות נתעשר משה, כמ\"ש אם<sup data-n=\"865\">17</sup> בחקתי תלכו ונתתי גשמיכם בעתם ונתנה הארץ יבולה כו', והמובחר עולה למעלה ונכלל בחיות הקדש וניתוסף כח בהם ועי\"ז והחיות<sup data-n=\"866\">18</sup> נושאות את הכסא היא הנק' לב העליון פי' שמעלי' אותה להיות בה עי\"ז המשכת והתפשטו' החיות משלמעלה מאצי' ונק' בשם אכילה שסועד הלב כביכול, ואח\"כ השתי' והיא הנסכים הוא ענין המשכת א\"ס ב\"ה מעילא לתתא והיו<sup data-n=\"867\">19</sup> מנסכי' יין בשיתי' שמגיעי' עד התהום כי הנה קודם<sup data-n=\"868\">20</sup> בה\"ע הי' מים במים ואח\"כ ביום ב' אמר יהי<sup data-n=\"869\">21</sup> רקיע ויהי מבדיל בין מים למים וביום ג' אמר יקוו המים אל מקום אחד הוא התהום ותראה היבשה כו' והנה ענין מים עליוני' היינו ברוחני' כי החכמה<sup data-n=\"870\">22</sup> נק' מים שאין להם גוון כו' אמנם קודם שהי' ההבדלה בין מים למים אזי גם מים תחתוני' היו בחי' רוחני' מאחר שהיו מתאחדי' עם מים עליוני' ד\"מ השמרים כשהם מעורבי' ובלולי' עם היין אזי גם הם אינן גסים כ\"כ והיו כיין, משא\"כ בהתבררם כשנפרדי' מן היין עם היות כי היין נעשה מנוקה מכל סיג ומשובח יותר מאשר הי' תחלה בהיותו מעורב בשמרים אבל השמרי' נשארי' פסולת לגמרי, כמ\"כ קודם שהבדיל ביניהם גם מים",[["862","14","<b>מלאכי' הנק' קרביי' ומיעי' כמ\"ש המו מיעיי לו</b>: ירמי' לא, יט. ראה זח\"ג רלד, ב. יהל אור ע' שפב."],["863","15","<b>נ\"ל . . נתעשר משה</b>: תיבות אלו נרשמו בגוכי\"ק אדמו\"ר הצ\"צ בצד הגליון."],["864","16","<b>פסל לך מפסולתן של לוחות נתעשר משה</b>: שמות לד, א. נדרים לח, א. ועוד."],["865","17","<b>אם בחקותי תלכו</b>: ע\"פ ר\"פ בחוקותי."],["866","18","<b>והחיות נושאות את הכסא</b>: לשון הפייט במוסף דר\"ה אחר קדושת כתר — נוסח אשכנז (ד\"ה והחיות). בחיי תרומה כה, יו\"ד בשם פדר\"א. וראה שמו\"ר ספכ\"ג."],["867","19","<b>והיו מנסכין יין בשיתי' שמגיעי' עד התהום</b>: ראה סוכה מט, א. אוה\"ת על מארז\"ל וענינים (הנסמן לעיל בתחילת המאמר) ע' ג' ואילך וע' ט."],["868","20","<b>קודם בה\"ע הי' מים במים</b>: ב\"ר פ\"ה, ב. שמו\"ר פ\"נ, א. וראה גם אוה\"ת בראשית כט, א."],["869","21","<b>יהי רקיע . . יקוו המים</b>: בראשית א, ו. ט."],["870","22","<b>החכמה נק' מים</b>: ראה פרדס שעה\"כ בערכו. קהלת יעקב מע' מים אות ט."]]],[2101920184,"תחתוני' היו בחי' רוחניו' וכמ\"ש ורוח<sup data-n=\"871\">23</sup> אלקי' מרחפת ע\"פ המים ובודאי לא הי' מרחפת על מים גשמיים כו' משא\"כ אחר שהבדיל אזי מים עליוני' נזדככו יותר אבל מים<sup data-n=\"872\">24</sup> תחתוני' נתגשמו יותר עד שהיו למים גשמיים ממש ולזאת הם בוכים אנן בעינן למהוי קדם מלכא, וע\"כ הי' שופכי' היין עד לתהום שהוא היותר אחרון שבהשתלשלות שעד שמה נמשכ' השפע מלמעלה והוא הפיוס למים תחתוני' הנ\"ל שממשיכי' להם ג\"כ הארה מלמעלה מא\"ס ב\"ה.\n<b>ועתה</b> יובן ג\"כ ענין מאמרז\"ל כל הקורא ק\"ש בלא תפילין כאילו הקריב עולה בלא מנחה כו' כי הנה ענין מנחת נסכי' הוא שהיו מקריבים סולת בלול בשמן, והנה הסולת והשמן הוא בחי' צומח שעצמותו הוא דומם שהוא למטה בערך מקרבנות כמו העולה פר לריח ניחוח כו' שיש בו נפש וחיות רוחניות משא\"כ הסלת והשמן, ואעפ\"כ עולה בלא מנחה אינו כלום כי העולה היא העלאה ממטה למעלה שהנפש הרוחני' שבפר מתעלית למעלה ומנחה בהקרבת צומח גשמי הוא ענין ההמשכה למטה בגשמיות כי הרי התכלי' הוא להיות המשכות למטה דוקא כו' וכמ\"כ ממש הוא ק\"ש בלא תפילין כי מצות ק\"ש בדבור פה אחד ואהבת כו' הוא בחי' רוחניות והתפילין הם ג\"כ פרשיות אלו רק שנכתבו ע\"ג קלף גשמי ובדיו גשמי והקורא ק\"ש בלא תפילין שהוא בחי' רוחני' העלא' ממט' למעלה בלא המשכה מלמעלה למטה בגשמיות ע\"י התפילין דומה למקריב עולה בלא מנחה וזבח בלא נסכים שהוא ג\"כ העלא' בלא המשכה כנ\"ל ומנחה<sup data-n=\"873\">25</sup> ונסכים הכל א' כדפרש\"י, ובאמת בחי' מנחה ונסכים הוא יותר גבוה מהעולה והזבח כי מנחה ונסכים הן ג' בחי' חב\"ד השמן<sup data-n=\"874\">26</sup> הוא בחי' חכמ' ולכן צף ע\"ג יין, והיין הוא בחי' בינה והסלת הוא בחי' דעת כאמרם אין<sup data-n=\"875\">27</sup> התינוק יודע לקרות או\"א עד שיטעום כו', והיא הנותנת כי להיותם יותר גבוהים לכן הם דוקא שנשפלו בבחי' ההמשכה למטה משא\"כ העולה והזבח אינן רק בבחי' העלאה כי גם למטה הם רוחני' בערך יותר מהנסכים כנ\"ל על היותן בשרשן למטה במדרג' משרש הנסכים והיינו בחי' חג\"ת פני אריה פני שור כו', ומה שאכילה מרובה משתי' הוא כענין מארז\"ל אין<sup data-n=\"876\">28</sup> לך טפה יורדת מלמעלה אא\"כ טפיים עולים כנגדה מלמטה והרי א\"כ איפוא האכילה שהיא ממטה למעלה צ\"ל מרובה מהשתיה שהיא ההמשכה שממעלה למטה כו'.",[["871","23","<b>ורוח אלקים מרחפת</b>: ראה בראשית א, ב."],["872","24","<b>מים תחתונים . . בוכים אנן בעינן</b>: ראה ת\"ז ת\"ה (יט, ב). מדרש עשה\"ד ס\"ב. תוס' הרא\"ש בראשית בתחילתו."],["873","25","<b>ומנחה ונסכים הכל א' כדפרש\"י</b>: ראה רש\"י ברכות שם (יד, סע\"ב)."],["874","26","<b>השמן הוא בחי' חכמ'</b>: ראה מאו\"א ש, סמ\"ח. תניא ספנ\"ג, ובהנסמן בהמ\"מ שם."],["875","27","<b>אין התינוק יודע לקרות או\"א</b>: ברכות מ, א."],["876","28","<b>אין לך טפה יורדת מלמעלה</b>: ראה הנסמן בארוכה בהמ\"מ ללקו\"ת (הוצאת תשד\"מ) שלח מב, ב. ובלקוטי הגהות לתניא ע' קמה."]]],[2101920185,"<h3>אכלו רעים שתו ושכרו דודים</h3>\n<b>אכלו</b><sup data-n=\"877\">1</sup> רעים<sup data-n=\"878\">2</sup> שתו ושכרו דודים, אני ישנה ולבי ער וגומ', ובזהר אכלו רעים לעילא פי' חו\"ב שנק' תרין רעין דלא מתפרשין והם י\"ה, שתו ושכרו דודים לתתא זו\"נ שנק' ו\"ה. והענין כי חכמה היא חכים<sup data-n=\"879\">3</sup> ולא בחכמה ידיעא, פי' שמה שנקראת בשם חכמה הוא רק ע\"ש העתיד שממנה משתלשל ומתהוה בחי' השכל למטה, אבל מ\"מ לא בחכמה ידיעא שאינה ממהות החכמה הידועה שלנו רק שהיא מקור, ונודע בפי' רחום שהענין הוא מקור הרחמים כי הרי למעלה לא יתכן רחמים גלוים שהוא בחי' התפעלות ושינוי כו'.\n<b>והנה</b> מ\"מ מחכמה ואילך הוא בחי' השתלשלות כמשל משכל למדות כו' יש מיש, אבל החכמה<sup data-n=\"880\">4</sup> מאין תמצא שלא בדרך השתלשלות אלא כענין שנאמר שם כבוד מלכותו כו' שמדת מל' דא\"ס בלבד מחי' אותו, וההמשכה שממדת מל' אינה בחי' גילוי חיות פנימי רק ששמו נק' עליהם כמשל המלך שאין עצמותו מתפשט במדינה כו' ומ\"מ הוא למעלה מההארה דחכמה אף שמאירה בפנימיות. וזהו מ\"ש<sup data-n=\"881\">5</sup> תמיד בזהר אסתלק יקרא דקוב\"ה בכולהו עלמין, שזה פלאי לכאור' מהו המעלה בהסתלקות יקרא כו'. אך ר\"ל אסתלק על בחי' גילוי ההארה שמבחי' כתר מל' דא\"ס שהיא בבחי' מקיף בלב ומ\"מ הוא מתגלה יותר מגילוי החיות דחכמה אף שהארתה בבחי' פנימית והיינו מצד עצם יתרון האור כו'. ולז\"א החכמה מאין תמצא כי הרי אין המשפיע בגילוי כמו מחכמה ולמטה שעצמיו' החכמ' מתלבש במדות כו' רק אבא<sup data-n=\"882\">6</sup> יונק ממזלא כי מ\"מ גם מכתר נמשך איזה הארה בבחי' פנימי' אבל הוא רק בבחי' שערות בלבד כערך חיות שבשערות לגבי עצם החיות שבמוחי' שבראש כו'. אמנם אח\"כ מחכמה לבינה נמשך השפע בהשתלשלות. וזהו אכלו רעים שהם תרין ריעין דלא מתפרשין כו'.\n<b>ול'</b> אכלו הוא עפמ\"ש ואם<sup data-n=\"883\">7</sup> האכל יאכל בשתי אכילות הכתוב מדבר א' אכילת מזבח כו' ובמגילה<sup data-n=\"884\">8</sup> אכילה מרובה משתיה כו', שהקרבנות נק' בשם אכילה והנסכים בשם שתיה. כי כמו עד\"מ ענין אכילת אדם בגשמיו' ולחם<sup data-n=\"885\">9</sup> לבב אנוש",[["877","1","<b>אכלו רעים שתו ושכרו דודים</b>: נדפס כאן מגוכי\"ק הצ\"צ תקע\"ב [1116 כז, ב]. ונמצא בס' מאמרי אדה\"ז על כתובים ח\"ב ע' קמו. מאמר זה נמצא באריכות ובשינויים בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'ריב ואילך [שם נרשם מאמר זה בהמשך לד\"ה לה\"ע הנסכים, שהוא מקביל לד\"ה ענין מארז\"ל כל הקורא ק\"ש בלא תפילין דלעיל]. וראה נו\"א ממאמר זה באוה\"ת שה\"ש כרך ב' ע' תצב ואילך (שם מתחיל: אני ישנה). ועוד קיצורים והגהות מהצ\"צ באוה\"ת שם כרך ג' ע' תתקיג ואילך."],["878","2","<b>אכלו רעים . . אכלו רעים לעילא . . תרין רעין</b>: שה\"ש ה, א. זח\"ג ד, א. ועוד."],["879","3","<b>חכים ולא בחכמה ידיעא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."],["880","4","<b>החכמה מאין תמצא</b>: איוב כח, יב."],["881","5","<b>מ\"ש תמיד בזהר אסתלק יקרא דקוב\"ה בכולהו עלמין</b>: ראה זח\"ב סז, ב. קכח, ב. קפד, א."],["882","6","<b>אבא יונק ממזלא</b>: ראה זח\"ג רפט, ב. ע\"ח שער הכללים פ\"ה."],["883","7","<b>ואם האכל יאכל בשתי אכילות הכתוב מדבר</b>: צו ז, יח. זבחים יג, ב. כח, ב."],["884","8","<b>ובמגילה אכילה מרובה משתיה</b>: יב, א."],["885","9","<b>ולחם לבב אנוש יסעד</b>: תהלים קד, טו."]]],[2101920186,"יסעד ע\"י שמתברר באצטומכא והמובחר שנתברר סועד הלב פי' שמגביהו ומקשרו עם המוח, שבמוח הוא משכן הנפש ולכן אם<sup data-n=\"886\">10</sup> לא יאכל ז' ימים ימות כי תסתלק הנפש שבמוח ותפרד מהלב, וע\"כ לחם דוקא יסעד אף שהיין מרבה דם יותר אבל ענין סועד הלב הוא התיישבות דעתו של אדם דהתקשרו' הלב אל המוח הוא ע\"י לחם דוקא שהוא בחי' דעת כמארז\"ל עה\"ד<sup data-n=\"887\">11</sup> חטה היתה כו', וכך הוא ענין הקרבת בהמה גשמיו' שנלקחה מפני שור שבמרכבה, כי כמו שג'<sup data-n=\"888\">12</sup> שותפים באדם כך גם בבהמה, אלא שבאדם הנפש הוא מבחי' פני אדם שבמרכבה שכלול גם פני נשר ופני שור ובישראל נוסף נפש אלקי' מאדם שעל הכסא כו', ובבהמות הוא מבחי' פני שור שבמרכבה, וע\"י הקרבן ע\"ג המזבח נכללת במקורה שבמרכבה ועי\"ז והחיות<sup data-n=\"889\">13</sup> נושאות את הכסא, שלכן נק' מרכבה כדוגמת המרכבה בגשמיו' שנושאת הרוכב למקום שלא הי' באפשרי לו להגיע בעצמו וממשיכות א\"ס ב\"ה מלמעלה מאצי' באצי'. וזהו ענין אכלו ריעים, כי ההמשכה היא ראשונה באו\"א שנק' תרין ריעין דלא מתפרשין כו'.\n<b>ואח\"כ</b> שתו ושכרו דודים הוא ניסוך היין בשיתין<sup data-n=\"890\">14</sup> שבמזבח שמגיעי' עד לתהום. כי הנה מקודם<sup data-n=\"891\">15</sup> בריאת העולם הי' מים במים ואח\"כ אמר יהי<sup data-n=\"892\">16</sup> רקיע כו'. והענין שמקודם הי' הכל רוחנית שגם מים תחתוני' היו רוחניים שלכן רוח<sup data-n=\"893\">17</sup> אלקים היתה מרחפת ע\"פ כל המים, עד שאח\"כ עשה רקיע והבדיל ביניהם ואז ירדו מים תחתוני' להיו' גשמיים, וכנודע<sup data-n=\"894\">18</sup> בענין אמ\"ר אור מים רקיע שבחי' אור הוא בחי' חכמה וכן מים הם בחי' חכמה אלא שאור הוא בחי' הפנימי' והרוחני' דחכמה ועד\"ז היו גם המים טרם שהבדיל ביניהם ולאחר ההבדלה אזי מים תחתוני' נתגשמו ולכן המה בוכי'<sup data-n=\"895\">19</sup> אנן בעינן למהוי כו'. ולכן מנסכים להם יין להמשיך שם הארת א\"ס ב\"ה כי היין<sup data-n=\"896\">20</sup> משמח אלקים, פי' וענין השמחה הוא התגלו' הפנימי', כי בכל דבר יש פנימי' וחיצוני' כמו אין<sup data-n=\"897\">21</sup> לך עשב שאין לו מזל",[["886","10","<b>אם לא יאכל ז' ימים ימות</b>: ראה רמב\"ם הל' שבועות פ\"ה ה\"כ. ובכ\"מ."],["887","11","<b>עה\"ד חטה היתה</b>: ראה ברכות מ, א. ב\"ר פט\"ו, ח. ובכ\"מ."],["888","12","<b>שג' שותפים באדם</b>: נדה לא, א."],["889","13","<b>והחיות נושאות את הכסא</b>: ראה לעיל ד\"ה ענין מארז\"ל כל הקורא ק\"ש. וש\"נ."],["890","14","<b>בשיתין שבמזבח שמגיעי' עד לתהום</b>: ראה לעיל שם. וש\"נ."],["891","15","<b>מקודם בריאת העולם הי' מים במים</b>: ב\"ר פ\"ה, ב. שמו\"ר פ\"נ, א."],["892","16","<b>יהי רקיע</b>: בראשית א, ו."],["893","17","<b>רוח אלקים היתה מרחפת</b>: ע\"פ בראשית א, ב."],["894","18","<b>וכנודע בענין אמ\"ר אור מים רקיע</b>: ע\"פ תהלים יט, ג. ראה זח\"ב קלו, ב. קסז, א. ע\"ח שער המלכים (שי\"א) פ\"ו. אוה\"ת חיי\"ש כרך ד' תשפח, ב. וראה ס' הערכים חב\"ד כרך ג' ס\"ע תיב ואילך. וש\"נ."],["895","19","<b>בוכי' אנן בעינן למהוי כו'</b>: ראה ת\"ז ת\"ה (יט, ב). מדרש עשה\"ד ס\"ב. בחיי ויקרא ב, יג. ועוד."],["896","20","<b>היין משמח אלקים</b>: ע\"פ שופטים ט, יג. ברכות לה, א."],["897","21","<b>אין לך עשב</b>: ב\"ר פ\"י, ו. וראה לעיל ד\"ה ביום השמע\"צ וביאוריו."]]],[2101920187,"וכן ממגד<sup data-n=\"898\">22</sup> תבואות שמש כו' הרי המזל הוא מקבל מלמעלה ומשפיע למטה וזהו ענין פנימי' וחיצוני' שבו, וכמ\"ש בפרדס<sup data-n=\"899\">23</sup> שכל עילה דבוק בעילתו כו', והשמחה היא התגלות הפנימית לחוץ. וכך הוא ענין משמח אלקים גילוי פנימי' אלקותו ית' בעולמות. וההמשכה היתה עד התהום גם במים תחתוני' שהם למטה במדרגה כו', כידוע שיש הבדלה בין אצי' לבי\"ע והוא סוד הרקיע הנ\"ל שבו וע\"י נעשה השינוי מאצי' לבריאה, ושרשו מה\"ג דאלקי' שבבינה, ואין<sup data-n=\"900\">24</sup> הגבורות נמתקים אלא בשרשן שבבינה, והיינו ע\"י היין ששרשו שם כו'. ולכן אכילה מרובה משתי', כי העיקר הוא להיו' תוספת אורו' באצי' והיינו ע\"י הקרבת הפרים ואלים כו', ואח\"כ השתי' היא לתתא להמשיך מאצי' לבי\"ע, ושם אין נצרך כ\"כ התעוררות מלמטה. וזהו השיעור שבכתוב לפר כך וכך נסך<sup data-n=\"901\">25</sup> וכן לאיל ולכבש לפי ערך ההמשכה שבאצי' כך צ\"ל הנסך להמשיך בבי\"ע כו'.\n<b>וזהו</b> אכלו ריעים לאו\"א שהוא המשכה מלמעלה מאצי' באצי' וזהו לעילא, ושתו ושכרו דודים לתתא זו\"נ להשפיע בבי\"ע. ומשחרב בהמ\"ק אזי תפלה במקום קרבנות כמ\"ש ונשלמה<sup data-n=\"902\">26</sup> פרים שפתינו כו'. וע\"ז משיבה כנ\"י אני<sup data-n=\"903\">27</sup> ישנה בגלותא מרוב הצרות ושעבוד מלכיות היא בבחי' שינה הסתלקו' המוחי' ואינן מאירי' לעורר עי\"ז להיות אכלו ריעי' ושתו דודי' כו', כמו השינה בגשמיו' שהמאכל<sup data-n=\"904\">28</sup> מביא את השינה מקיטורי' העולי' בראש כו'. וע\"ז משיב הקב\"ה ולבי ער שהוא ית' נק' צור<sup data-n=\"905\">29</sup> לבבי, וכתי' הנה<sup data-n=\"906\">30</sup> לא ינום ולא יישן שומר ישראל, ועי\"ז קול דודי דופק ע\"י עסק התורה הקל<sup data-n=\"907\">31</sup> קול יעקב כו'.",[["898","22","<b>ממגד תבואות שמש</b>: ברכה לג, יד. וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תרב. וש\"נ."],["899","23","<b>וכמ\"ש בפרדס שכל עילה דבק בעילתו</b>: ראה גם תו\"א יתרו סט, א."],["900","24","<b>ואין הגבורות נמתקים אלא בשרשן שבבינה</b>: ראה פע\"ח שער השופר פ\"א. לקו\"ת להאריז\"ל וישב לט, א. תניא פל\"א. ובכ\"מ."],["901","25","<b>השיעור שבכתוב לפר כך וכך נסך</b>: פינחס כד, יד."],["902","26","<b>ונשלמה פרים שפתינו</b>: הושע יד, ג."],["903","27","<b>אני ישנה בגלותא</b>: שה\"ש ה, ב. זח\"ג צה, א."],["904","28","<b>שהמאכל מביא את השינה מקיטורי' העולי' בראש</b>: ראה סה\"מ תקס\"ט ע' רכט (ובהוצאה הראשונה הוא בע' ריב) וע' רמח (רלא) ואילך. תו\"ח חיי\"ש קכה, ב. שמות ח\"א לח, ב (ובהוצאה הראשונה נב, ב). פיה\"מ לאדהאמ\"צ נה, ג. נו, ג. אמרי בינה קט, ב. קל, ג. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' לד. הנחות תקע\"ז ע' קצא. סה\"מ תרע\"ח ע' קלא. ובכ\"מ."],["905","29","<b>צור לבבי</b>: תהלים עג, כו."],["906","30","<b>הנה לא ינום ולא יישן</b>: תהלים קכא, ד."],["907","31","<b>הקל קול יעקב</b>: תולדות כז, כב."]]],[2101920188,"<h3>ואת גביעי גביע הכסף</h3>\n<b>ואת</b><sup data-n=\"908\">1</sup> גביעי<sup data-n=\"909\">2</sup> גביע הכסף תשים בפי אמתחת הקטן כו'. כתיב כוס<sup data-n=\"910\">3</sup> ישועות אשא ובשם הוי' אקרא, הנה כוס<sup data-n=\"911\">4</sup> גימ' פ\"ו והוא ג\"כ גימטריא דגביע עם הכולל והוא גימטריא<sup data-n=\"912\">5</sup> דשם אלקים כידוע. והענין הוא כידוע בכונות דכוס של קידוש על היין דוקא, שבחי' הכוס הזה הוא בחי' הכלי לקבל החסדים דאימא שהוא היין<sup data-n=\"913\">6</sup> שהוא בבחי' בינה כו'. וביאור הדברים ידוע שהדיבור הוא בחי' אותיות<sup data-n=\"914\">7</sup> שהן בחי' כלים להכיל ולהקיף מה שבתוכו, כי הרי הכל מתיישב באותיות הדיבור, כמו אור השכל שהוא רוחני במקומו בכלי המוח ונמשך ובא באותיות הדיבור ומתיישב ומתעלם בו כמו שמתיישב ומתעלם המים והיין בתוך הכוס, וכך למעלה בחי' אותיות<sup data-n=\"915\">8</sup> דיבור העליון שבדבר ה' עשה את הכל וכמ\"ש ואתה<sup data-n=\"916\">9</sup> מחי' את כולם א\"ת וה' מוצאות הפה כו' כידוע הנה כללות כל האותיות של הדיבור נעשין כמו בית קיבול כללי לקבל מהמוחין והמדות המשפיעין בו ונק' כוס והוא גימטריא פ\"ו כמו שם<sup data-n=\"917\">10</sup> אלקים להיותו בחי' צמצום להגביל האורות כו' וד\"ל.\n<b>וזהו</b> כוס ישועות אשא שיש כאן ב' דברים, הא' ענין הגבהת הכוס למעלה כמ\"ש אשא, והב' שנק' כוס ישועות שמלא חסדים שנק' ישועות, והיינו ענין שע\"ה נהורין דא\"א שמאיר במל' כמו וישע<sup data-n=\"918\">11</sup> ה' אל הבל כו', כידוע דק\"ן<sup data-n=\"919\">12</sup> נהורין יש מכבר באור אבא כמ\"ש בע\"ח בענין כי יקרא קן צפור כו' ולתשלום שלימות החסדים נמשך עוד רכ\"א נהורין שהוא שע\"ה עם ה\"ח הכוללים, וז\"ש דוד כוסי<sup data-n=\"920\">13</sup> רויה גימטריא רכ\"א שהוא<sup data-n=\"921\">14</sup> מדות א\"א, וזהו כוסי רוי\"ה רכ\"א הנוספים, והוא בחי' כוס ישועות דלעתיד שיהי' בתכלית השלימות מהארת א\"א כו', אבל עכשיו",[["908","1","<b>ואת גביעי</b>: מאמר זה הוא הנחת כ\"ק אדהאמ\"צ משנת תקע\"ב. וראה ס' מאמרי אדה\"ז עה\"ת ח\"א בהוספות ע' 18. ונמצא בשינויים והגהות מהצד בד\"ה ענין יוסף ואחיו באוה\"ת מקץ כרך ב שמ, ב ואילך. שמה, א ואילך. כרך ו תתשה ב ואילך. וראה גם פלח הרמון להרה\"ח הר\"ה מפאריטש ע' 218 ואילך."],["909","2","<b>ואת גביעי גביע הכסף</b>: מקץ מד, ב."],["910","3","<b>כוס ישועות אשא</b>: תהלים קטז, יג."],["911","4","<b>כוס גימ' כו' אלקים</b>: זח\"ג רמה, סע\"א. רעג, סע\"א. וראה חידושי אגדות מהרש\"א ברכות נא, א (ד\"ה עשרה). ובכ\"מ."],["912","5","<b>גימטריא דשם אלקים</b>: ראה ע\"ח שער המוחין פ\"א (ש\"כ) פ\"א. ובכ'מ."],["913","6","<b>היין שהוא בבחי' בינה</b>: ראה זח\"ג קכז, א. מאמרי אדהאמ\"צ ויקרא ח\"א ע' לג. וש\"נ."],["914","7","<b>אותיות שהן בחי' כלים</b>: ראה תניא שער היחוד והאמונה פ\"ד. לקו\"ת מטות פב, ג. ובכ\"מ."],["915","8","<b>אותיות דיבור העליון</b>: בכת\"י ב: אותיות הדיבור כמו אור שכל העליון."],["916","9","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו. ראה תניא שם פ\"ב. מאמרי אדהאמ\"צ דברים ח\"ב ע' שצט. וש\"נ."],["917","10","<b>שם אלקים . . צמצום</b>: ראה תו\"א תולדות כא, א. מאמרי אדהאמ\"צ בראשית ע' קעג. וש\"נ."],["918","11","<b>וישע ה' אל הבל</b>: בראשית ד, ד. ראה מאמרי אדהאמ\"צ דברים ח\"ב ע' תתעב."],["919","12","<b>דק\"ן נהורין . . באור אבא </b> [בכת\"י ב: בא\"א]<b> . . כי יקרא קן צפור</b>: תצא כב, ו. ראה ע\"ח שער א\"א (שי\"ג) פי\"ד. מאמרי אדהאמ\"צ דברים ח\"ב ע' תתעא. וש\"נ."],["920","13","<b>כוסי רויה גימטריא רכ\"א</b>: תהלים כג, ה. יומא עו, א. ראה מאמרי אדהאמ\"צ דברים ח\"א ע' כג. וש\"נ."],["921","14","<b>שהוא מדות א\"א</b>: בכת\"י ב: שהוא א\"א."]]],[2101920189,"אין המל' מקבל רק ה\"ח כוללים והוא שנק' כוס ישועות אשא בכוס<sup data-n=\"922\">15</sup> של ברכה דעכשיו בה'<sup data-n=\"923\">16</sup> אצבעות שמגביהין הכוס וכן לענין בחי' כוס דקידוש, ומ\"ש כוסי רויה הוא לעתיד בכוס של ברכה שיברך דוד לעתיד כמאמר רז\"ל שיעשה<sup data-n=\"924\">17</sup> הקב\"ה סעודה לעתיד ונותן כוס של ברכה לאברהם כו' עד דוד שאמר לי נאה לברך ואותו הכוס יהי' ביין<sup data-n=\"925\">18</sup> המשומר בענביו מששת ימי בראשית כידוע וד\"ל.\n<b>והנה</b> ביאור ענין ה\"ח כוללים שנמשך בכוס של ברכה דעכשיו כמ\"ש כוס ישועות אשא כו' היינו בחי' חסד שבחסד חסד שבגבורה חסד שבת\"ת כו'. ויובן זה עד\"מ בכלי הדיבור שאנו רואים שיש בגלוי הדיבור דבר חסד ואהבה וגם דברי דין ורוגז גדול כו', אך יכול להיות שגם בדברי דין ורוגז הקשה יש בו מבחי' החסד והאהבה הגדולה בהעלם, והוא כמו כאשר ייסר איש את בנו בדברי תוכחות מגולה מאהבה מוסתרת שמחמת אהבה דוקא ירבה דברי תוכחה בדברי כעס ותערומות בהגזמ' דינין ועונשין או דברי שנאה והרחקה יתירה רק כדי שישוב מדרכו הרעה לטובה, שאין בכל הדברים האלה רק בחי' טוב וחסד שמחמתם דוקא יתקרב לדרך הטוב וכה\"ג. וכמ\"כ יש בחי' חסד בכל המדות כמו התפארות והניצוח ונק' חסד שבת\"ת וחסד שבנצח דהיינו בחי' החסד שיצא מחמת מדה זו כמו בחי' חסד<sup data-n=\"926\">19</sup> שבגבורה מדת הדין הנ\"ל וכללותם נק' ה\"ח (כי בחי' יסוד אינו מדה בפ\"ע רק שבו כלולים כל<sup data-n=\"927\">20</sup> ה\"ח הללו והוא בחי' יוסף כמו שיתבאר בעז\"ה). וז\"ש כוס ישועות אשא לקבל ה\"ח הללו שיבואו בכוס הזה כדי להשפיע לעולמות וכמ\"ש והוכן<sup data-n=\"928\">21</sup> בחסד כסא שאין קיום העולם רק בחסד דוקא, ואח\"כ בשם הוי' אקרא להמשיך מכל האורות העליונים דשם הוי' הפרטיים בדיבור להיות השפע באה בפרטות לכל העולמות מריש כל דרגין עד סוף הכל וז\"ש אקרא בדיבור אך דוקא לאחר שכוס ישועות אשא בבחי' ה\"ח הנ\"ל וכמ\"ש כי<sup data-n=\"929\">22</sup> אמרתי עולם חסד יבנה כו' וד\"ל (או פי' ובשם הוי' אקרא להמשיך בשם הוי' ממקור החסדים כי נעוץ<sup data-n=\"930\">23</sup> תחילתן בסופן דוקא כידוע וד\"ל).\n<b>והנה</b> ידוע דדוד הוא מרכבה לבחי' המל' שמלאה דינין כו' כי עיקר ענין בנין<sup data-n=\"931\">24</sup> המל' הוא מבחי' הגבורות כידוע, וע\"כ הוצרך לקבל ה\"ח שנק' ישועות",[["922","15","<b>בכוס של ברכה . . שמגביהין הכוס</b>: ברכות נא, א."],["923","16","<b>בה' אצבעות</b>: ראה שו\"ע אדה\"ז חאו\"ח סקפ\"ג ס\"ז."],["924","17","<b>שיעשה הקב\"ה סעודה לעתיד</b>: פסחים קיט, ב."],["925","18","<b>ביין המשומר בענביו</b>: ראה ברכות לד, ב. ובכ\"מ."],["926","19","<b>חסד שבגבורה מדת הדין הנ\"ל וכללותם</b>: בכת\"י ב: חסד שע\"י מדה\"ר וכללותם."],["927","20","<b>כל ה\"ח הללו</b>: בכת\"י ב: ה' מדות הללו."],["928","21","<b>והוכן בחסד כסא</b>: ישעי' טז, ה."],["929","22","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["930","23","<b>נעוץ תחילתן בסופן</b>: ספר יצירה פ\"א מ\"ז."],["931","24","<b>בנין המל' הוא מבחי' הגבורות כידוע</b>: ראה מאמרי אדהאמ\"צ דברים ח\"א ע' ריח. וש\"נ."]]],[2101920190,"להמתיק הגבו', וידוע שאין<sup data-n=\"932\">25</sup> מיתוק הדין אלא בשרשו דוקא שהוא בבחי' גבורות דאימא דבינה<sup data-n=\"933\">26</sup> מינה דינין מתערין כו', וביין הוא בחי' המתקת הדינין דבינה ונק' יין<sup data-n=\"934\">27</sup> המשמח אלקים שממתיק לגבורות דשם אלקים<sup data-n=\"935\">28</sup> דבינה ומל' כו', וכמו שאנו רואים שהיין ישמח לב האדם להפוך כל מדות אשר בשכלו מרע לטוב מדין לחסד מפני שנעשה לבו טוב מן היין, כמו כטוב<sup data-n=\"936\">29</sup> לב המלך ביין מצוה להוציא כל האסירים מבית האסורים וימחול לשונאיו כו' וכה\"ג וכמ\"ש בזהר דכל<sup data-n=\"937\">30</sup> חירו וכל חידו מן היין. אך זהו בחי' הטוב והחסד שביין דהיינו שכח הדין שבו נמתק לחסד, כי יש ביין כח הדין להתכעס יותר כמו עובדא דרבה<sup data-n=\"938\">31</sup> דשחטי' לרבי זירא כו' וכה\"ג, אך בחי' החסדים שביין גוברין על כח הדין שבו ואז הן בחי' חסדים טובים הבאים בתגבורת גדולה לעשות לפנים משורת הדין הרבה כמו למחול לחייבים ביותר ולאהוב גם השונא כנ\"ל, וגם אנו רואים כאשר טוב לבבו ביין יגלה כל מצפוניו כמ\"ש נכנס<sup data-n=\"939\">32</sup> יין יצא סוד, והוא ג\"כ תוקף גלוי אור החסד שיורד ביותר מההעלם לגילוי, שהרי גם מהיות נעלם בהעלם אחר העלם יוצא לידי גילוי ע\"י היין שיוצא סוד גם היותר כמוס ע\"כ יין גימטריא סוד (והוא גם בחי' הסוד שבחכמה דזקן<sup data-n=\"940\">33</sup> דעתי' סתום ונעלם בתכלית ונק' חכמה סתימאה והוא בהיותו בן<sup data-n=\"941\">34</sup> ע' שנה דוקא שאז זמן שלימות גדלות המוחין דחו\"ב ממקורם הנעלם כו' ואעפ\"כ יוצא גם סוד זה ע\"כ יין גימטריא ע'). וכך יובן למע' בבחי' מיתוק הגבורות שבכוס דמל' שהוא ע\"י בחי' יין דבינה בחי' חסדי' דאימא שיש בהם כח ותגבורת גדולה להמתיק כל דין לחסד כנ\"ל ולצאת מן ההעלם כו', ומהם נמשך ה' חסדים חסד שבחסד חסד שבגבורה חסד שבת\"ת כו' וכנ\"ל. וזהו ענין כוס דקידוש וכוס של ברכה, דכוס גימטריא אלקים דבינה שמקבל מבחי' החסדים דבינה מפני שאין מיתוק הדין אלא בשרשו דוקא כידוע וד\"ל.\n<b>ואמנם</b> הנה עכשיו אין המל' מקבל רק ה\"ח בכוס של ברכה והן ה' חסדים כוללים דיסוד<sup data-n=\"942\">35</sup> שנק' קנה הכל ק\"ן אורות דאבא עם ה' חסדים כוללים",[["932","25","<b>שאין מיתוק הדין אלא בשרשו</b>: ראה פע\"ח שער השופר פ\"א. לקו\"ת להאריז\"ל וישב לט, א. תניא פל\"א ובכ\"מ."],["933","26","<b>דבינה מינה דינין מתערין</b>: ראה זח\"ג י, סע\"ב. יא, רע\"א. מאמרי אדהאמ\"צ דברים ח\"ב ע' שעז. וש\"נ."],["934","27","<b>יין המשמח אלקים</b>: ע\"פ ס' שופטים ט, יג."],["935","28","<b>אלקים דבינה</b>: ראה זח\"א ב, א ובמקדש מלך שם. שם (תוספתא) בראשית לא, ב."],["936","29","<b>כטוב לב המלך ביין</b>: אסתר א, י."],["937","30","<b>דכל חירו וכל חידו</b>: ראה זהר תולדות קמב, ב. תרומה קמז, א."],["938","31","<b>דרבה דשחטי' לרבי זירא</b>: מגילה ז, ב."],["939","32","<b>נכנס יין יצא יצא סוד</b>: עירובין סה, א. ראה מאמרי אדהאמ\"צ בראשית ס\"ע תקסח ואילך."],["940","33","<b>דזקן דעתי' סתום ונעלם</b>: ראה זהר (אדרא רבא) נשא קכח, ב. אמ\"ב (קה\"ת תשמ\"ה) שער התפילין קל, ד."],["941","34","<b>בן ע' שנה</b>: ראה ס' מאמרי אדה\"ז עה\"ת ח\"א ע' רי. ס' מאמרי אדהאמ\"צ בראשית ע' רפט. וש\"נ."],["942","35","<b>דיסוד שנק' קנה הכל</b>: ראה פע\"ח ש\"ט (שער העמידה) פ\"ג."]]],[2101920191,"וזהו קנה<sup data-n=\"943\">36</sup> חכמה כו', אך עיקר הקבלה<sup data-n=\"944\">37</sup> הוא ביין שבכוס שהן ה\"ח דאימא והוא מזל ונקה (וזכרהו<sup data-n=\"945\">38</sup> על היין הוא בחי' ה\"ח דאבא כו'), אבל לעתיד יהי' כוס של ברכה דדוד מלכא משיחא בתכלית שלימות ה\"ח ממקורם שהוא בבחי' א\"א והיינו רכ\"א לוגין יין המשומר בענביו כו' והוא ענין תכלית<sup data-n=\"946\">39</sup> ושלימות הארת אור מא\"א רכ\"א ויהי' כללותם שע\"ה נהורין כנ\"ל. וז\"ש כוסי רויה פי' כוסי שמכבר שנק' כוס ישועות יהי' רויה גימטריא רכ\"א נוסף על החסדים הראשונים. וז\"ש אלה<sup data-n=\"947\">40</sup> דברי דוד האחרונים דקאי לעתיד שיהי' עליית המל' בכתר כמ\"ש נאום<sup data-n=\"948\">41</sup> הגבר הוקם על גימטריא מאה כו' כידוע וד\"ל. וע\"כ יהי' הכוס ביין המשומר בענביו מששת ימי בראשית שהוא בחי' בינה דא\"א שנק' מוחא<sup data-n=\"949\">42</sup> דשקיט ושכיך על דורדייא כו' כמ\"ש במ\"א וד\"ל.\n<b>אך</b> הנה בחי' גביע הכסף דיוסף הוא למעלה מבחי' כוס ישועות דדוד. כי הנה ידוע בשורש בחי' יוסף שהוא בבחי' יסוד שלמעלה מבחי' מל' וכל החסדים העליונים שבכל האורות העליונים מאירים ומתכנשים ביסוד דוקא, וכמ\"ש כי<sup data-n=\"950\">43</sup> כל בשמים כו' שיסוד<sup data-n=\"951\">44</sup> נק' כל דאחיד בשמיא וארעא והיינו וקנה הכל, ופי' כל היינו כללות כל החסדים, והמל'<sup data-n=\"952\">45</sup> נק' כלה שמקבלת מבחי' כל דיסוד כידוע. וזהו שהי' יוסף יפה תואר ויפה מראה שהוא בחי' ההתכללות מכל האורות וכלים יחד שזהו ענין תואר ומראה, התואר הוא בבחי' תמונת הגבלת הכלים והמראה בבחי' האורות, וכמ\"ש<sup data-n=\"953\">46</sup> במ\"א בענין רחל יפת תואר ויפת מראה שהיופי הוא בבחי' ההתכללות ממזיגה נכונה בין באורות בין בכלים שנק' תואר ומראה, רק שברחל<sup data-n=\"954\">47</sup> הוא בבחי' המל' המקבל מהכל וביסוד הוא בחי' יוסף הוא בחי' דכר המשפיע הכל כו' וע\"י דוקא יצא כל אור ושפע מהעלם לגילוי כמ\"ש ויוסף<sup data-n=\"955\">48</sup> הוא השליט על הארץ הוא המשביר כו', ונק' יתו\"ם<sup data-n=\"956\">49</sup> ר\"ת יפה תואר ויפה מראה, אך הוא יתום מאמו ולא מאביו לפי שבינה<sup data-n=\"957\">50</sup> עד הוד אתפשטת ולא יותר אבל אור אבא מאיר",[["943","36","<b>קנה חכמה</b>: משלי ד, ה."],["944","37","<b>הקבלה</b>: בכת\"י ב: הכוונה."],["945","38","<b>וזכרהו על היין</b>: פסחים קו, א. ראה סידור עם דא\"ח רכא, ד."],["946","39","<b>תכלית ושלימות הארת</b>: בכת\"י ב: תוס' הארת."],["947","40","<b>אלה דברי דוד האחרונים</b>: שמואל-ב כג, א."],["948","41","<b>נאום הגבר הוקם על גימטריא מאה</b>: שמואל שם. ראה שו\"ע אדה\"ז או\"ח רסמ\"ו. מאמרי אדהאמ\"צ בראשית ס\"ע רצ."],["949","42","<b>מוחא דשקיט ושכיך על דורדייא</b>: ראה מאמרי אדהאמ\"צ בראשית ע' רצ ובהנסמן שם."],["950","43","<b>כי כל בשמים . . דאחיד בשמיא וארעא</b>: דברי הימים-ב כט, יא. ראה זח\"א לא, סע\"א. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשמב. וש\"נ."],["951","44","<b>שיסוד נק' כל</b>: ראה זח\"ג פינחס רנז, סע\"א. מאמרי אדהאמ\"צ במדבר ח\"א ע' פב. וש\"נ. דברים ח\"ב ע' תרפז. וש\"נ."],["952","45","<b>והמל' נק' כלה</b>: פרדס שכ\"ג (שער ערכי הכינויים) מע' כל כלה."],["953","46","<b>וכמ\"ש במ\"א בענין רחל</b>: ראה לעיל ד\"ה ורחל היתה יפ\"ת."],["954","47","<b>שברחל . . המל'</b>: פרדס שם מע' רחל."],["955","48","<b>ויוסף הוא השליט</b>: מקץ מב, ו."],["956","49","<b>יתו\"ם ר\"ת יפה תואר</b>: ראה ע\"ח שער הכללים ספ\"ד. אוה\"ת בהעלותך כרך ו ע' א'תשסו, ובמ\"מ שם."],["957","50","<b>שבינה עד הוד אתפשטת</b>: ראה זח\"ג פינחס רכג, ב. ביאוה\"ז תשא נד, ג. אמרי בינה (קה\"ת תשמ\"ה) שער התפילין קכ, ד."]]],[2101920192,"גם ביסוד דנמצא אינו יתום מאביו וכמ\"ש אלה<sup data-n=\"958\">51</sup> תולדות יעקב יוסף כו'. ולפ\"ז כל בחי' שפע אור החסדים שנמשך מאור אבא שהוא מקור כל החסדים נמשך ומאיר בבחי' יסוד<sup data-n=\"959\">52</sup> ונק' כנישו דכל נהורין וע\"כ נק'<sup data-n=\"960\">53</sup> טוב כידוע.\n<b>וזהו</b> וילקט<sup data-n=\"961\">54</sup> יוסף את כל הכסף, פי' כי הכסף<sup data-n=\"962\">55</sup> שרשו בבחי' החסד כידוע, ויוסף הוא בחי' יסוד ליקט כל אורות החסדים שנמשכים ממקור החסדים שבאבא והביאם ביתה פרעה<sup data-n=\"963\">56</sup> לשון פריעה וגילוי שהוא בחי' בינה ומל' ששם בחי' גילוי כל נהורין. והענין הוא שכל החסדים דאבא הביאם בבינה ומל' להגביר ולהמתיק גם גבורות דאימא לחסדים ע\"כ הוא למעלה הרבה מבחי' כוס ישועות דדוד, דדוד הוא בחי' המל' הנצרך לקבל חסדים דאימא בלבד שהוא בחי' יין המשמח שבתוך הכוס כנ\"ל, אבל יוסף שהוא בעצם ממקור החסדים שמהפך גם לגבורות דאימא לחסדים לא הוצרך ליין בתוך הגביע אלא בלא יין הי' הגביע שלו מצד עצמו מבחי' החסדים העצמיי' וע\"כ הי' גביע של כסף דוקא ולא הי' צריך להגביהו לקבל חסדים כמו כוס ישועות אשא אלא אדרבה הי' מורידה למטה מטה כדי להמתיק בו כל דינין הקשין. וזהו שאמר ואת גביעי ביו\"ד דחכמה המיוחד ליוסף דוקא גביע הכסף, גביע גימטריא פ\"ו ע\"ה והוא בחי' שם אלקים גימטריא פ\"ו שנמתק בחסדים, וזהו שהי' מנחש בו להמתיק בו גבורות קשות שנאחזים בנחש<sup data-n=\"964\">57</sup> דקטנות דיסוד כמ\"ש במ\"א, וז\"ש כי<sup data-n=\"965\">58</sup> נחש ינחש איש אשר כמוני דוקא שמקבל מה\"ח דאבא שלמעלה מה\"ח דאימא כידוע. וזהו ההפרש בין גביע לכוס כו' וד\"ל.\n<b>וזהו</b> ואת גביעי גביע הכסף תשים בפי אמתחת הקטן שהוא בחי' צדיק<sup data-n=\"966\">59</sup> תחתון בחי' בנימין כידוע וע\"כ נק' קטן כמו דוד<sup data-n=\"967\">60</sup> הוא הקטן וזהו בפי אמתחת הקטן דוקא. והענין הוא כי שרש בנימין הוא מבחי' הגבורות כמ\"ש בן אוני, אך אביו קרא לו בנימין מבחי' החסד דקו הימין כו', וע\"כ ציוה יוסף לשום גביע הכסף שלו ששרשו במקור החסדים דאבא כנ\"ל בפי אמתחת בנימין הקטן כדי",[["958","51","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב."],["959","52","<b>יסוד . . כנישו דכל נהורין</b>: ראה זח\"א יח, א. לג, א. ובהנסמן במאמרי אדהאמ\"צ בראשית ע' רפה."],["960","53","<b>יסוד . . נק' טוב</b>: ראה זח\"ב קכח, ב. (והגהות מהרח\"ו שם). זח\"ג כא, א. קנ, א (והגהות מהרח\"ו שם). ובכ\"מ."],["961","54","<b>וילקט יוסף</b>: ויגש מז, יד."],["962","55","<b>הכסף . . החסד</b>: ראה זח\"ב קטו, א. זח\"ג רעז, א. ובכ\"מ."],["963","56","<b>פרעה לשון פריעה וגילוי</b>: ראה זח\"א רי, א. ובהנסמן במאמרי אדהאמ\"צ בראשית כאן ע' רצה."],["964","57","<b>בנחש דקטנות דיסוד</b>: ראה גם מאמרי אדהאמ\"צ דברים ח\"ב ע' תרטו."],["965","58","<b>כי נחש ינחש</b>: מקץ מד, טו."],["966","59","<b>צדיק תחתון . . בנימין</b>: ראה זהר זח\"א קנג, ב. מאמרי אדה\"ז עה\"ת ח\"ב ע' תתצה ובהנסמן לשם. מאמרי אדהאמ\"צ דברים ח\"ב ע' תעא."],["967","60","<b>דוד הוא הקטן</b>: שמואל-א יז, יד."]]],[2101920193,"להמתיק גבורות שלו בחסדי' ולהיות אחוז וקשור בחבלי עבותות בצדיק עליון בחי' יוסף ע\"י גביע זה של כסף דיוסף, וכידוע בענין וידעת<sup data-n=\"969\">62</sup> כי שלום אהליך שהוא שלום בית דמקבל בחי' התקשרות המקבל במשפיע ושלום דמשפיע במקבל וז\"ש יעשה שלום לי שלום יעשה כו', וזהו תשים בבחי' התקשרות דמשפיע צדיק עליון במקבל צדיק תחתון, והוא בחי' רוחא<sup data-n=\"970\">63</sup> דשביק בגווה כו' שזהו ע\"י בחי' החסדים דדכורא כי<sup data-n=\"971\">64</sup> אין אשה כורתת כו', וזהו ובנימין<sup data-n=\"968\">61</sup> בכה על צוואריו<sup data-n=\"972\">65</sup> כו' כמ\"ש במ\"א וד\"ל.\n<b>והנה</b> כל ענין מכירת יוסף<sup data-n=\"973\">66</sup> למצרים דוקא ואשר הי' בבית האסורים בבור עשר שנים הוא ענין גלות בחי' צדיק עליון בחי' יסוד כמ\"ש ענו<sup data-n=\"974\">67</sup> בכבל רגליו כו' אמרת ה' צרפתהו שהוא בחי' צירוף ובירור דצדיק עליון בהיותו אסור בגלות כמ\"ש מלך<sup data-n=\"975\">68</sup> אסור ברהטים כו', וכ\"ז מפני שהי' צריך להיות גלות ישראל במצרים שהוא בחי' גלות השכינה בחי' מל' כמ\"ש אנכי<sup data-n=\"976\">69</sup> ארד עמך מצרימה כו' וכמאמר רז\"ל גלו<sup data-n=\"977\">70</sup> לאדום שכינה עמהם כו', ולהיות כי טומאת מצרים היא בתחתיות המדריגות דקליפות אבי אבות הטומאה דנו\"ן שערי טומאה והי' חשש גדול פן לא יוכל להיות יציאת ישראל מגלות מצרים כי יגבר כח הקליפה הקשה עד שישתקעו שם כמ\"ש אשר<sup data-n=\"978\">71</sup> שלט האדם באדם כו' כי אין<sup data-n=\"979\">72</sup> חבוש מתיר א\"ע מאחר שהשכינה היא בגלות ומלך<sup data-n=\"980\">73</sup> אלקים על גוים שמחי' אותם בע\"כ כו' כמ\"ש ומלכותו כו', וע\"כ חשב ה' מחשבות לבלתי יהיו נדחים בארץ מצרים בסוד גלות השכינה לעולם ח\"ו, ע\"כ גלגל מכירת יוסף בחי' צדיק עליון למצרים שבחי' כח הדכר הוא הרבה יותר וכמו שאמרו האיש<sup data-n=\"981\">74</sup> דרכו לכבוש כו', והי' יוסף בבחי' גלות תחילה שם כמ\"ש הצדיק<sup data-n=\"982\">75</sup> אבד אבד בגלותא כו' וענו בכבל רגליו, וכ\"ז הי' תועלת להיות בחי' התנשאות מל' יוסף להכניע לכל הגבורות הקשות דמצרים כמ\"ש וילקט יוסף כל הכסף כל החסדים כו' כנ\"ל, ובפרט בשבע<sup data-n=\"983\">76</sup> שני הרעב",[["969","62","<b>וידעת כי שלום אהליך . . יעשה שלום לי</b>: איוב ה, כד. ישעי' כז, ה. ראה סנהדרין צט, ב. תו\"א תרומה פ, ד. מאמרי אדה\"ז על כתובים ח\"ב ע' קפה."],["970","63","<b>רוחא דשביק בגווה</b>: ראה זח\"ב צט, ב. ע\"ח שער מ\"ן ומ\"ד (של\"ט) דרוש ז, ח. מאמרי אדהאמ\"צ דברים ח\"א ע' כד. וש\"נ."],["971","64","<b>כי אין אשה כורתת</b>: ראה סנהדרין כב, ב."],["968","61","<b>בן אוני . . בנימין</b>: וישלח לה, יח."],["972","65","<b>ובנימין בכה על צוואריו</b>: ויגש מה, יד. ראה אמרי בינה שער הק\"ש לב, א."],["973","66","<b>יוסף . . בבית האסורים . . עשר שנים</b>: ראה פדר\"א פל\"ט וברד\"ל שם."],["974","67","<b>ענו בכבל רגליו . . אמרת ה' צרפתהו</b>: תהלים קה, יח. שם, יט."],["975","68","<b>מלך אסור ברהטים</b>: שה\"ש ז, ו."],["976","69","<b>אנכי ארד עמך מצרימה</b>: ויגש מו, ד."],["977","70","<b>גלו לאדום שכינה עמהם</b>: ספרי מסעי לה, לד. ראה הנסמן במאמרי אדהאמ\"צ דברים ח\"ב ע' תלה."],["978","71","<b>אשר שלט האדם באדם</b>: קהלת ח, ט."],["979","72","<b>אין חבוש מתיר א\"ע</b>: ראה ברכות ה, ב."],["980","73","<b>ומלך אלקים על גוים . . כמ\"ש ומלכותו</b>: תהלים מז, ט. שם קג, יט."],["981","74","<b>האיש דרכו לכבוש</b>: יבמות סה, ב."],["982","75","<b>הצדיק אבד אבד בגלותא</b>: ישעי' נז, א. ראה זח\"ב יא, א."],["983","76","<b>בשבע שני הרעב</b>: ראה רש\"י, ורמב\"ן ולקח טוב לויגש מז, יט."]]],[2101920194,"שקנה<sup data-n=\"984\">77</sup> אותם ואת אדמתם לפרעה בחי' מל' כמ\"ש<sup data-n=\"985\">78</sup> במדרש שמל אותם, וזהו אמרו ה\"א<sup data-n=\"986\">79</sup> לכ\"ם זר\"ע וזרעתם את האדמה שנתן להם ה' חסדים מגולים להיות בכחם לזרוע את האדמה וכמ\"ש ונתן<sup data-n=\"987\">80</sup> זרע לזרע ולחם לאכל שהוא בחי' ה\"ח שנמשכים מיסוד לזרוע את האדמה כו' וכמ\"ש לו המצרים תן<sup data-n=\"988\">81</sup> לנו זרע ונחי' ולא נמות והאדמה לא תשם כו'. והנה ע\"י שמל אותם הסיר בחי' קליפה הקשה שלהם ביותר הנק' ערות<sup data-n=\"989\">82</sup> מצרים והוחלש כחם מאוד, והי' דבר זה תועלת גדול לדור הנולד הבא אחריהם שלא הי' להם כח חזק כ\"כ להשתעבד ולהתגבר על ישראל בגלותם, ומלבד שלא נשתקעו אצלם אלא שהוקל להם השיעבוד ולא נטמאו בטומאתם כמאמר רז\"ל שהיו<sup data-n=\"990\">83</sup> מצויינים שם כו', וגם משך הזמן דגלותם הי' רק פ\"ו<sup data-n=\"991\">84</sup> שנה, כידוע דעיקר קושי השיעבוד לא הי' רק פ\"ו שנה (וזהו פ\"ו שנה דמרים בזמן<sup data-n=\"992\">85</sup> רד\"ו והיינו כמנין גימטריא דשם אלקים שהוא פ\"ו כנ\"ל), וכמו שאמרו בטעם קריאת שם מרים שאמרו שהיתה בת פ\"ו שנה כשנפסק הגלות דוימררו<sup data-n=\"993\">86</sup> את חייהם בזמן רד\"ו כו' ובתחילת הגלות וימררו את חייהם נולדה מרים וע\"כ קראה שמה מרים ע\"ש המרירות דוימררו את חייהם כו' וזה הי' בזמן<sup data-n=\"994\">87</sup> קכ\"ד בבואם למצרים ובזמן רד\"ו נגאלו שאז היתה בת פ\"ו שנה ובזמן זה נאמר וידע<sup data-n=\"995\">88</sup> אלקים שנמתק שם אלקים כו' וד\"ל.\n<b>והנה</b> כמו שמבואר למעלה בבחי' כוס ישועות דדוד שיהי' בחי' עלי' לעתיד שנאמר כוסי רויה כו' לקבל שע\"ה נהורין מאור א\"א כו', כך יהי' בחי' עלי' לבחי' יסוד בחי' יוסף צדיק עליון בבחי' יסוד דא\"א וע\"י כמ\"ש צדיק<sup data-n=\"996\">89</sup> כתמר יפרח כארז בלבנון ישגה, וז\"ש מכנף<sup data-n=\"997\">90</sup> הארץ שמענו צבי לצדיק כו' מכנף הארץ דוקא, והוא כאשר יהי' עלי' לבחי' המל'<sup data-n=\"998\">91</sup> שנק' ארץ כו' כמ\"ש אשת<sup data-n=\"999\">92</sup> חיל עטרת בעלה וכן נקבה<sup data-n=\"1000\">93</sup> תסובב גבר, משא\"כ עכשיו כאשר המל' מקבלת מז\"א ומ\"ה<sup data-n=\"1001\">94</sup> מברר",[["984","77","<b>שקנה אותם ואת אדמתם לפרעה</b>: ויגש שם, יח-כג."],["985","78","<b>כמ\"ש במדרש שמל אותם</b>: ב\"ר ס\"פ צ. תנחומא מקץ ו. רש\"י מקץ מא, נה."],["986","79","<b>ה\"א לכ\"ם זר\"ע</b>: ויגש שם, כג."],["987","80","<b>ונתן זרע</b>: ישעי' נה, י."],["988","81","<b>תן לנו זרע</b>: ע\"פ ויגש שם, יט: ותן זרע."],["989","82","<b>ערות מצרים</b>: לשון הכתוב ישעי' כ, ד. וראה מקץ מב, ט. יב."],["990","83","<b>שהיו מצויינים שם</b>: ראה ספרי תבוא כו, ה."],["991","84","<b>פ\"ו שנה . . קושי השעבוד . . נולדה מרים</b>: ראה תנחומא (בבער) בא ז. מאמרי אדהאמ\"צ בראשית כאן ע' רעט. וש\"נ."],["992","85","<b>בזמן רד\"ו</b>: תנחומא מקץ ח. רש\"י מקץ מב, ח."],["993","86","<b>דוימררו את חייהם</b>: שמות א, יד."],["994","87","<b>בזמן קכ\"ד בבואם למצרים</b>: ראה תנחומא (בבער) בא ז."],["995","88","<b>וידע אלקים</b>: שמות ב, כה. וראה גם מאמרי אדהאמ\"צ במדבר ח\"ב ע' תשפד."],["996","89","<b>צדיק כתמר יפרח</b>: תהלים צב, יג."],["997","90","<b>מכנף הארץ שמענו</b>: ע\"פ ישעי' כד, טז."],["998","91","<b>המל' שנק' ארץ</b>: ראה זח\"א בראשית לא, ב."],["999","92","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד."],["1000","93","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["1001","94","<b>ומ\"ה מברר לב\"ן</b>: ראה ע\"ח שער נת\"א (ש\"ה) פ\"א. מאמרי אדהאמ\"צ דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."]]],[2101920195,"לב\"ן כמ\"ש והוא<sup data-n=\"1002\">95</sup> ימשול בך כידוע אין עלי' לבחי' יסוד כ\"כ, וזה פלא לכאורה שהרי כאשר מ\"ה מברר לב\"ן יש כח יותר בבחי' הדכר מבחי' הנוק' ובחי' יסוד הוא בבחי' ז\"א דדוכרא, ולעתיד יהי' כח בנוק' שהוא בחי' המל' יותר עד שתהי' עטרת בעלה מאיזה טעם יהי' עלי' לבחי' יסוד יותר מעכשיו כו'.\n<b>אך</b> הנה ראי' ברורה לדבר זה אנו מוצאים ממה שמצינו שלעתיד יהי' הבכור יוסף ועכשיו בכור<sup data-n=\"1003\">96</sup> יעקב ראובן ולא יוסף, וז\"ש ביוסף בכור שורו כו' דקאי לעתיד, ולזה הטעם גם העבודה<sup data-n=\"1004\">97</sup> לעתיד יהי' בבכורים ולא בכהנים, כידוע שהעבודה הי' בבכורים מיד שיצאו ממצרים כמ\"ש קדש<sup data-n=\"1005\">98</sup> לי כל בכור פטר כל רחם כו' וקדושה זאת היתה לעבודה כמ\"ש כי<sup data-n=\"1006\">99</sup> לי הקדשתי כל בכור בהכותי כל בכור כו', אך מפני<sup data-n=\"1007\">100</sup> חטא העגל נפסקה העבודה מן הבכורים ונתנה לכהנים בני אהרן, אבל לעתיד תחזור העבודה לבכורים כמקדם, אמנם לא כמו דין בכור<sup data-n=\"1008\">101</sup> דעכשיו שהוא לאב דוקא כמו הכהנים דעכשיו שהן דוקא בני אהרן למשפחותם<sup data-n=\"1009\">102</sup> לבית אבותם כתיב דכל שאביו כהן כשר לכהונה ולא כשאמו כהנת, אבל בבכורים דלעתיד לא יתייחסו לבית אבותם להיות בכור לאב דוקא אלא בכור לאמו דוקא כמ\"ש קדש לי כל בכור פטר כל רחם, פטר כל רחם דאמו דוקא, ואם הוא בכור לאמו אע\"פ שאינו בכור לאב כשר לעבודה, ואם יש לאדם כמה נשים ולכל אחת נולד בן בכור כולם כשרים לעבודה, רק לענין דין הירושה<sup data-n=\"1010\">103</sup> אינו נוטל פי שנים אלא בכור לאב דוקא שנק' ראשית<sup data-n=\"1011\">104</sup> אונו ולו דוקא משפט הבכורה לענין הירושה, אבל לענין העבודה לא בעינן ראשית אונו אלא שיהי' פטר רחם בלבד (ואפשר שאם הוא בכור לאב ראשית אונו ואינו בכור לאמו שכבר ילדה בן מאיש אחר לא יוכשר לעבודה אע\"פ שלו משפט הבכורה לענין הירושה מאחר שלא נק' פטר רחם כו'). ובאמת דבר זה פלא גדול הוא למה יהי' הפרש בין דין הירושה ליטול פי שנים שאינו אלא כשהוא בכור לאב מטעם שהוא ראשית אונו, בין דין העבודה שהוקדש בכור פטר כל רחם דוקא ולא בכור לאב, ולמה לא יהי' דין",[["1002","95","<b>והוא ימשול בך</b>: בראשית ג, טז."],["1003","96","<b>בכור יעקב ראובן . . בכור שורו</b>: וישלח לה, כג. ברכה לג, יז."],["1004","97","<b>העבודה לעתיד יהי' בבכורים</b>: ראה ס' הגלגולים פכ\"ג. מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תקצד. וש\"נ."],["1005","98","<b>קדש לי כל בכור</b>: בא יג, ב."],["1006","99","<b>כי לי הקדשתי . . כל בכור</b>: בבמדבר ג, יג (ועד\"ז בהעלותך ח, יז): כי לי כל בכור ביום הכותי כל בכור . . הקדשתי לי כל בכור."],["1007","100","<b>מפני חטא העגל נפסקה</b>: במאמר זה באוה\"ת מקץ ע' 686 כותב ע\"ז: ושם ברבות נשא רפ\"ו מבואר שירדו מגדולתם על מעשה העגל (וצ\"ע דבגמרא שם זבחים דקי\"ו ע\"ב משמע שמסיני נצטוו על הכהנים ע\"ש בפרש\"י)."],["1008","101","<b>בכור דעכשיו שהוא לאב</b>: ראה גם מאמרי אדהאמ\"צ בראשית ס\"ע דש. אוה\"ת שם ע' שדמ."],["1009","102","<b>למשפחותם לבית אבותם</b>: ראה רש\"י קידושין (במשנה) סו, ב ד\"ה כהנת."],["1010","103","<b>הירושה . . בכור לאב</b>: ראה אוה\"ת שם ע' שדמ: כדתנן במשנה רפ\"ח דבכורות."],["1011","104","<b>ראשית אונו ולו . . משפט הבכורה</b>: תצא כא, יז."]]],[2101920196,"העבודה בבכורים כמו בכהנים שהם מתיחסים לבית אבותם דוקא ולא לאמותם כו'.\n<b>אך</b> להבין כל זה יש להקדים ענין הידוע הנ\"ל דעכשיו בחי' הדכורא עיקר ובחי' הנוק' טפל שהרי בחי' דכר משפיע השפע לנוק' והנוק' לית לה מגרמה כלום כמשל הלבנה שמקבלת מן השמש וכך כתיב ואל<sup data-n=\"1012\">105</sup> אישך תשוקתך לקבל תמיד והוא ימשול בך כו' שהמקבל למטה במדריגה מן המשפיע, ולזה הטעם הבעל<sup data-n=\"1013\">106</sup> יורש את אשתו כו' ועיקר הירושה בא מן כח האב, ולזה הטעם גם בדין משפט הבכורה לענין הירושה ליטול פי שנים אינו אלא כשהוא בכור לאב ראשית אונו דוקא (ואע\"פ שאין<sup data-n=\"1014\">107</sup> נותנים לאדם פרנסה אלא בשביל אשתו כמ\"ש להניח<sup data-n=\"1015\">108</sup> ברכה אל ביתך כו' מ\"מ כל השפע ברכה מתייחס דוקא אל האיש אע\"פ שהאשה היא עקרת הבית נושאת ונותנת כו'), והיינו משום דמ\"ד דדכורא עיקר ולכך הוא מושל כמ\"ש להיות<sup data-n=\"1016\">109</sup> כל איש שורר כו' (וכידוע דמ\"ד<sup data-n=\"1017\">110</sup> מברר למ\"ן דנוק' כו' כמו משל הגשמים<sup data-n=\"1018\">111</sup> שמרוים לארץ והולידה והצמיחה ובלא גשמים לא תצמיח כך האשה<sup data-n=\"1019\">112</sup> לא תלד במ\"ן שלה כ\"א ע\"י קבלתה בחי' מ\"ד כו'), אבל לעתיד כתיב הנני<sup data-n=\"1020\">113</sup> בורא חדשה בארץ נקבה תסובב גבר שבחי' הנוק' יהי' למעלה במדריגה מבחי' דדכורא וכן אמר אשת חיל עטרת בעלה דבחי' ב\"ן יהי' למעלה משם מ\"ה כו' ואז לא תהי' בחי' הנוק' בחי' מקבל להיות אל אישה תשוקתה אלא אדרבא תסובב גבר ותהי' עטרת כו' (ולא כמו קודם חטא עה\"ד שהיו זו\"נ שוין בקומתן כמ\"ש ויהי<sup data-n=\"1021\">114</sup> האדם ואשתו כו'), משום דלאחר תשלום כל הבירורים דבחי' ב\"ן<sup data-n=\"1022\">115</sup> יתעלה למעלה משם מ\"ה המברר כו' כמ\"ש במ\"א וד\"ל.\n<b>וע\"כ</b> זהו שלעתיד לא תהי' העבודה בכהנים<sup data-n=\"1023\">116</sup> ששרשן בבחי' החסדים דז\"א בחי' דכורא אלא בבכורים שהן פטר כל רחם דוקא, משום דבחי' הנוק' עיקר ובחי' הדכר טפל ע\"כ אין העבודה רק בבכור לאמו דוקא כמו שהי' העבודה",[["1012","105","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1013","106","<b>הבעל יורש את אשתו</b>: ב\"ב קיא, ב."],["1014","107","<b>שאין נותנים לאדם פרנסה</b>: ראה ב\"מ נט, א."],["1015","108","<b>להניח ברכה אל ביתך</b>: יחזקאל מד, ל. ראה יבמות סב, ב."],["1016","109","<b>להיות כל איש שורר</b>: אסתר א, כב."],["1017","110","<b>דמ\"ד מברר למ\"ן</b>: בכת\"י ב: דמ\"ה מברר לב\"ן."],["1018","111","<b>הגשמים שמרוים לארץ</b>: ע\"פ ישעי' נה, י."],["1019","112","<b>האשה לא תלד במ\"ן שלה</b>: ראה מאמרי אדהאמ\"צ בראשית ע' שה. ויקרא ח\"ב ע' תר. וש\"נ."],["1020","113","<b>הנני בורא חדשה בארץ</b>: ע\"פ ירמי' לא, כה [ושם: כי ברא ה' חדשה בארץ. וראה בהמ\"מ במאמרי אדהאמ\"צ בראשית ע' שו. ויקרא ח\"ב ע' תערב]."],["1021","114","<b>ויהי האדם ואשתו</b>: ע\"פ בראשית ב, כה."],["1022","115","<b>ב\"ן יתעלה למעלה משם מ\"ה</b>: ראה גם מאמרי אדהאמ\"צ דברים ח\"ג ע' א'רי. וש\"נ."],["1023","116","<b>בכהנים . . החסדים</b>: ראה זח\"ג כז, א. מאמרי אדהאמ\"צ דברים ח\"ג ע' תתעג. וש\"נ."]]],[2101920197,"בבכורים קודם חטא העגל דכתיב קדש לי כל בכור פטר כל רחם דוקא, כי קודם חטא העגל הי' בדוגמא דלעתיד אחר תשלום כל הבירורים חירות ממות כו' מפני שכאשר עמדו בהר סיני פסקה<sup data-n=\"1024\">117</sup> זוהמתן, רק מפני חטא העגל חזרה<sup data-n=\"1025\">118</sup> הזוהמא דנחש הקדמוני ע\"כ צריך בירור ותיקון ע\"י בחי' שם מ\"ה דדוכרא כו' ולזה נתנה העבודה לכהנים, ולעתיד תחזור העבודה לבכורים משום שנאמר אשת חיל עטרת בעלה כו', ועיקר הבכור הוא פטר רחם דוקא ולא בכור לאב, ומ\"ש למשפחותם לבית אבותם היינו רק עכשיו מטעם הנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ עליית מעלת יוסף צדיק עליון בחי' יסוד לעתיד בזמן עליית המל' דוקא כנ\"ל ולא עכשיו משום דיוסף הי' בכור לאמו רחל ולא לאב כי ראובן בכור יעקב עכשיו שכח הדכר עיקר כנ\"ל, אבל לעתיד יהי' עלי' לבחי' הנוק' רחל עקרת הבית אשת יעקב כמ\"ש מושיבי<sup data-n=\"1026\">119</sup> עקרת הבית כו', וכאשר תתעלה בחי' רחל יהי' יוסף בכור ולא ראובן כי בכור לאמו עיקר יותר מטעם הנ\"ל שהעבודה לעתיד בבכור לאמו דוקא כו'. וזהו מכנף הארץ דוקא שמענו צבי לצדיק כו' כאשר יהי' אשת חיל עטרת בעלה כו'.\n<b>ובזה</b> יובן ענין הפטורה דפ' ויגש בעובדא דיוסף עם מצרים שמדבר לעתיד דוקא בבחי' עליית יסוד ומל' כנ\"ל, והוא נבואת יחזקאל במ\"ש קח<sup data-n=\"1027\">120</sup> לך עץ אחד וכתוב עליו ליהודה<sup data-n=\"1028\">121</sup> ולישראל חבריו שהוא בחי' המל' ועץ<sup data-n=\"1029\">122</sup> אחד ליוסף עץ אפרים בחי' יסוד וקרב<sup data-n=\"1030\">123</sup> אותם אחד אל אחד והיו לאחדים בחי' יחוד דיסוד ומל' ולא<sup data-n=\"1031\">124</sup> יחצו עוד לשתי ממלכות כו' ומלך אחד יהי' לכולם, עד ודוד<sup data-n=\"1032\">125</sup> עבדי נשיא להם לעולם וד\"ל, דכתר<sup data-n=\"1033\">126</sup> שם טוב עולה על גביהם גם בהיות העבודה לעתיד בבכורים שיהי' במקום כתר כהונה דעכשיו כו' וד\"ל.",[["1024","117","<b>פסקה זוהמתן</b>: ראה שבת קמו, רע\"א."],["1025","118","<b>חזרה הזוהמא</b>: ראה מאמרי אדה\"ז עה\"ת ח\"א ע' שלד — ובהמ\"מ לשם בע' תעז."],["1026","119","<b>מושיבי עקרת הבית</b>: תהלים קיג, ט."],["1027","120","<b>קח לך . . ולישראל חבריו</b>: ע\"פ יחזקאל לו, טו [ושם: ולבני ישראל]."],["1028","121","<b>ליהודה . . המל'</b>: ראה מאו\"א מע' יהודה ס\"ו. מאמרי אדהאמ\"צ בראשית ע' רצט. וש\"נ."],["1029","122","<b>ועץ אחד ליוסף עץ אפרים</b>: ע\"פ יחזקאל שם."],["1030","123","<b>וקרב אותם . . והיו לאחדים</b>: יחזקאל שם, יז (בדילוג)."],["1031","124","<b>ולא יחצו עוד . . ומלך אחד</b>: יחזקאל שם, כב (בשינוי הסדר)."],["1032","125","<b>ודוד עבדי נשיא</b>: יחזקאל שם, כה."],["1033","126","<b>דכתר שם טוב עולה על גביהם</b>: אבות פ\"ד מי\"ג. [מכאן עד סיום המאמר ליתא בכת\"י ב]."]]],[2101920198,"<h3>וידבר אלקים גו' וארא</h3>\n<b>פ' וארא תקע\"ב</b>\n<b>וידבר</b><sup data-n=\"1034\">1</sup> אלקים<sup data-n=\"1035\">2</sup> אל משה ויאמר אליו אני הוי', וארא אל אברהם כו' ושמי הוי' לא נודעתי להם, הודעתי אין כתי' כאן אלא נודעתי, הענין בהקדים להבין מה זה תשובה עמ\"ש משה תחלה למה<sup data-n=\"1036\">3</sup> הרעות כו', אך כי טענת משה למה הרעות הי' על מה ולמה מגיע יסורים כ\"כ לישראל ולזה השיבו וידבר אלקים אני הוי' כי גם שם אלקים אע\"פ שלדעתך הוא דין גמור אבל עפ\"י האמת הוא כאחד עם הוי' שהוא מדה\"ר כי דין<sup data-n=\"1037\">4</sup> רחמי הוא רק לאחזאה לאתנהג בהון עלמא, אבל הוא ית' לאו דאית לי' צדק ידיעא ולא משפט ידיעא ולאו מכל אינון מדות איהו כלל ובהשפלתו למטה אזי מתכללים כאחד כו'.\n<b>וביאור</b> זה יובן בהקדים להבין עוד מ\"ש ושמי הוי' לא נודעתי להם דהלא כמה מקראות מליאים דבר הכתוב, וירא<sup data-n=\"1038\">5</sup> הוי' אל אברם כו' ויאמר הוי' אל אברם לך לך כו' והוי' אמר המכסה אני מאברם כו' וכהנה רבות. אך הענין כי יש ב' בחי' הוי' כמ\"ש ויקרא<sup data-n=\"1039\">6</sup> הוי' הוי' ופסיק טעמא בגווייהו כי אין ערוך כלל בין בחי' הוי' שבבחי' השתלשלות מדה\"ר מדה\"ד דהיינו שהרחמים הם במדה וגבול ונמשכים מי\"ה צמצום והתפשטו' להיות חכים ומבין כו'. לבחי' הוי' הא' שהוא לפני ההשתלשלות. ואבות העולם עם היות כי הן<sup data-n=\"1040\">7</sup> הן המרכבה אברהם<sup data-n=\"1041\">8</sup> אוהבי ופחד יצחק לא הגיעו בזה רק עד בחי' הוי' שבהשתלשלות. וזהו באל שדי",[["1034","1","<b>וידבר גו' וארא</b>: המאמר נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. ונמצא בשינויים והגהות באוה\"ת וארא (כרך ז') ע' ב'תקמט ואילך וע' ב'תקסג ואילך. וקיצורים על המאמר באוה\"ת וארא (כרך ח') ע' ב'תתצג. ותוכן מהמאמר בשינויים והוספות: בד\"ה עיר קטנה בסה\"מ תרכ\"ו ע' קיד ואילך [וע\"ש בהמ\"מ שהוא מיוסד על ד\"ה ששים המה מלכות להצ\"צ משנת תרי\"ח]. ד\"ה ששים המה מלכות בסה\"מ תרל\"ט ח\"א ע' קיא ואילך וע' קטז ואילך. ד\"ה לריח שמניך וד\"ה ששים המה בסה\"מ תרל\"ט שם ע' רלט ואילך וע' רפ ואילך. ובשינויים בסה\"מ תר\"מ ח\"א ע' ס ואילך. ובשינויים והוספות בד\"ה עיר קטנה בסה\"מ תרנ\"ב ע' רפג ואילך. וראה בהנסמן עוד לקמן פיסקא: והענין.\nמאמר זה הובא ונזכר באוה\"ת ויצא קצז, ב. שמות ע' ב'תקי. וארא ע' ב'תקנז (ביאור ע\"פ וארא דתקע\"ב). בא ע' רצ. ב'תריב. ב'תרכב. בשלח ע' תקיח. תקלה. תשא ע' א'תתקטו. ויקרא ע' תקסו. בהעלותך ע' שלח (ע\"ש). עקב ע' תקכט. דרושים לר\"ה ע' א'תב. נצבים ע' ב'עד. נ\"ך ע' תקכז. תתקמג."],["1035","2","<b>וידבר . . וארא אל אברהם . . הודעתי אין כתי' כאן</b>: וארא ו, ב-ג. פירש\"י עה\"פ. ובכ\"מ."],["1036","3","<b>למה הרעות</b>: שמות ה, כב."],["1037","4","<b>דין רחמי . . לאחזאה . . לאו דאית לי'</b>: ע\"פ תקו\"ז ד\"ה פתח אליהו."],["1038","5","<b>וירא הוי' . . ויאמר הוי' . . והוי' אמר</b>: לך לך יב, ז. שם יב, א (ועוד). וירא יח, יז."],["1039","6","<b>ויקרא הוי' הוי' ופסיק טעמא בגווייהו</b>: תשא לד, ו. זח\"ג קלח, א. וראה גם תו\"א בשלח סא, ד. תצוה פג, ג. פד, א. לקו\"ת חוקת נז, ג. דרושים לר\"ה נא, א. וראה בארוכה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' רצ, ובסה\"מ תרל\"ט שם ע' קיב."],["1040","7","<b>הן הן המרכבה</b>: ב\"ר פמ\"ז, ו."],["1041","8","<b>אברהם אוהבי ופחד יצחק</b>: ישעי' מא, ח. ויצא לא, מב."]]],[2101920199,"שאמר<sup data-n=\"1042\">9</sup> לעולמו די בחי' אדני, כי הנה נודע מארז\"ל קיים<sup data-n=\"1043\">10</sup> אאע\"ה כל התורה כולה עד שלא ניתנה וכן ביעקב עם<sup data-n=\"1044\">11</sup> לבן גרתי ותרי\"ג מצות שמרתי והיינו רק ברוחנית שהרי לא יתכן שקימו מצות חליצה ויבום ופרה אדומה כו' ולכן לא השיגו רק בבחי' הוי' שבהשתלשלות שהוא בחי' רוחנית של המצות יש שתלוים ביו\"ד ויש בה' כו', משא\"כ בבחי' הוי' הא' נאמר נורא<sup data-n=\"1045\">12</sup> תהלות עושה פלא שהוא נורא תהלות ולא<sup data-n=\"1046\">13</sup> ידע ליה בר איהו משום דעושה פלא שגם בחי' חכמה הנק' פלא ואפי' גם מה שלמעלה מהחכמה כי פלא<sup data-n=\"1047\">14</sup> אותיו' אלף והיינו אאלפך<sup data-n=\"1048\">15</sup> חכמה שהוא ענין מקור החכמה, כידוע בדקדוק דאלף הוא ל' מדבר בעדו כו' נק' בשם עשיה בלבד אצלו ית'. ולכן לא יכלו האבות שעבודתם הי' באהוי\"ר להגיע* שמה,\n\n*)<i>להגיע שמה</i>: בס' תקע\"ב נרשם כאן בשולי העמוד הגהת כ\"ק אדמו\"ר הצ\"צ בגוכי\"ק:\nכי האהוי\"ר זהו ע\"ד תהלה שע\"י השבחים מעוררי' הגלוי כמ\"ש ע\"פ הללויה[ftnref_2144_א], וסד\"ה בכ\"ה בכסלו בענין בהלל[ftnref_2145_ב], אכן כיון שהוי' שלפני האצי' נק' נורא תהלות א\"כ א\"א להמשיך ע\"י בחי' זו וע\"ש שזהו ענין ובהודאה.\nוזהו ענין לתת להם את ארץ כנען דהיינו ענין ארץ שבה דוקא קיום המצות מעשיות שהמצות הם בחי' אור זרוע לצדיק זרעו לכם לצדקה. וזריעה זו היא בארץ שבה דוקא יש כח הצומח ע\"י נעוץ סופן בתחלתן כמ\"ש באג\"ה ד\"ה איהו וחיוהי[ftnref_2146_ג]. וגם כמ\"ש בד\"ה יביאו לבוש מ'[ftnref_2147_ד] שהעשייה שרשה נמשך מבחי' סוכ\"ע דוקא, וכאן בהביאור פי' ששרש המ' הנק' ארץ שרשה גבוה מבחי' חג\"ת שהם ג' קוין שרש בחי' אדם ושרשם חג\"ת דאריך, אבל הארץ מ' שרשה בבחי' עצם הכתר שהרי נק' כתר מ' ושם למעלה מבחי' קוין, וזה כעין מ\"ש בת\"א בהביאור ע\"פ זכור ושמור בדבור אחד[ftnref_2148_ה] בענין רמה קרני, דוד שנמשח בקרן הוא בבחי' רמה בחי' כי לא אדם הוא, וז\"ש באבות וגם הקימותי את בריתי לתת להם את ארץ שגם מה שהמשיכו משם הוי' דאצי' זהו ע\"י הארץ רק שניתנה להם עדיין רק הארץ עליונה, ע' בלק\"ת פ' שלח[ftnref_2149_ו] בענין המרגלים שרצו רק בארץ עליונה, וטעו בזה כי ע\"י העבודה ברוחניות אפילו עם הארץ עליונה ממשיכים משם הוי' דאצי', אבל להמשיך משם הוי' דלעילא זהו ע\"י מצות מעשיות דוקא, וכן בק\"ש נאמר וזאת המצוה[ftnref_2150_ז] אשר צוה ד' לעשות בארץ.",[["1042","9","<b>שאמר לעולמו די</b>: חגיגה יב, א. ובכ\"מ."],["1043","10","<b>קיים אאע\"ה כל התורה</b>: יומא פב, א. וראה גם תו\"א לך לך יא, ד. יתרו סח, א ואילך. לקו\"ת במדבר יב, ג. שלח לח, ב. שה\"ש ט, ב. ובכ\"מ."],["1044","11","<b>עם לבן גרתי ותרי\"ג מצות שמרתי</b>: וישלח לב, ה. פירש\"י עה\"פ שם."],["1045","12","<b>נורא תהלות עושה פלא</b>: בשלח טו, יא."],["1046","13","<b>ולא ידע ליה בר איהו</b>: ראה זח\"ג רפח, א-ב."],["1047","14","<b>פלא אותיו' אלף</b>: ראה תקו\"ז ת\"ע (קלה, א)."],["1048","15","<b>אאלפך חכמה</b>: איוב לג, לג. שבת קד, א.\n\n[ftn_2144_א]) יהל אור להצ\"צ ע' תקנח ואילך וע' תרצג. וראה סה\"מ תרל\"ט ס\"ע קיד, שם נת' יותר תוכן הגה\"ה זו.\n\n[ftn_2145_ב]) תו\"א וישב ל, א.\n\n[ftn_2146_ג]) ס\"כ (קל, ב ואילך).\n\n[ftn_2147_ד]) תו\"א צ, א ואילך.\n\n[ftn_2148_ה]) תו\"א עב, ג.\n\n[ftn_2149_ו]) לז, א-ב ואילך.\n\n[ftn_2150_ז]) ואתחנן ו, א. ובכ\"מ."]]],[2101920200,"וע\"ז קאי ושמי הוי' לא נודעתי להם הודעתי אין כתי' אלא נודעתי דהיינו מהותו ועצמותו ית', כ\"א למשה ולישראל נתגלה אח\"כ בקבלתם התורה שהיא בחי' מצות מעשיות וכח המעשה גדול יותר כי נעוץ<sup data-n=\"1049\">16</sup> תחלתן בסופן כו', והיינו ג\"כ פי' עושה פלא שהמשכת הפלא עליון הוא ע\"י עשיה דוקא, ולכן זהו תשובה על טענת משה למה הרעות לעם הזה אשר היו מצרים מעבידים אותם בפרך כי עי\"ז דוקא יגיעו למ\"ת שלא זכו האבות וז\"ש וארא כו'.\n<b>והענין</b><sup data-n=\"1050\">17</sup> כי ידוע דישראל<sup data-n=\"1051\">18</sup> שבאותו הדור היו גלגול דור הפלגה שהיו נשמות גבוהות, ותחת החטא שחטאו בבנין המגדל שאמרו הבה<sup data-n=\"1052\">19</sup> נלבנה לבנים כו' עשו ערי<sup data-n=\"1053\">20</sup> מסכנות לפרעה בלבנים כו'. כי ענין המגדל הוא כמ\"ש ונעשה<sup data-n=\"1054\">21</sup> לנו שם שע\"י שמות וקבלה מעשיות רצו להמשיך עליהם כל טוב בגשמיו', כי הנה לבנים הם אותיות כמ\"ש אימתי<sup data-n=\"1055\">22</sup> גדול ה' כשהוא בעיר אלקינו, שתי<sup data-n=\"1056\">23</sup> אבנים בונות שתי בתים כו' שהם בחי' צירופי אותיות העליוני', אלא שבסט' דקדושה הם מתפשטי' ומתלבשים בתוכיות העולמות ובפנימיותם כמ\"ש בקרבך<sup data-n=\"1057\">24</sup> קדוש, והם לא רצו בזה, כי אם היו השמות והאותיות העליונים",[["1049","16","<b>נעוץ תחלתן בסופן כו'</b>: ס' יצירה פ\"א מ\"ז."],["1050","17","<b>והענין כי ידוע דישראל שבאותו הדור</b>: עניני המאמר מכאן ואילך נמצאים ג\"כ בשינויים, בנוסף לכל הנסמן לעיל בתחילת המאמר, בסה\"מ תר\"מ ח\"א ע' נט ואילך, ע ואילך, עז ואילך (המשך זאת חנוכה המזבח תר\"מ פרקים יד-כב). ובסה\"מ תרנ\"ה ע' צה ואילך. וראה גם אוה\"ת נח (כרך ג') תרנד, א ואילך. תרסח, א-ב. סה\"מ תר\"ל ע' ד ואילך. תרמ\"ג ע' ג ואילך. תרפ\"ו ע' פז ואילך. סה\"מ קונטרסים ח\"א קלט, ב ואילך."],["1051","18","<b>דישראל שבאותו הדור היו גלגול דור הפלגה</b>: ראה פע\"ח שכ\"א (שער חגהמ\"צ) פ\"א. וראה מאמרי אדהאמ\"צ ויקרא ח\"א ע' עג. במדבר ח\"ב ע' תשסה. וש\"נ."],["1052","19","<b>הבה נלבנה לבנים</b>: נח יא, ג."],["1053","20","<b>ערי מסכנות לפרעה בלבנים כו'</b>: שמות א, יא ואילך."],["1054","21","<b>ונעשה לנו שם . . וקבלה מעשיות</b>: נח יא, ד. וראה בהמובא ע\"ז באוה\"ת וארא שם ע' ב'תקסח. סה\"מ תר\"מ ח\"א שם ס\"ע עא ואילך. [ובהנסמן שם באורך]. וראה גם תו\"א נח י, ב. אוה\"ת מטות ע' א'רפט. סה\"מ תרל\"ב ח\"ב ע' תקצו. [ובהנסמן לעיל בתחילת המאמר, ובפיסקא: והענין]."],["1055","22","<b>אימתי גדול ה'</b>: ראה זח\"ב רלה, א. זח\"ג ה, א. ז\"ח תשא מד, א. חוקת נא, ד. וראה תו\"א וארא נו, ב. מאמרי אדה\"ז עה\"ת ח\"א ע' רכז. סה\"מ תקס\"ב ח\"א ע' רה. לקו\"ת פ' ראה כט, ב. ובכ\"מ."],["1056","23","<b>שתי אבנים בונות שתי בתים</b>: ס' יצירה פ\"ד מי\"ב."],["1057","24","<b>בקרבך קדוש</b>: הושע יא, ט."]]],[2101920201,"מתלבשים בפנימיותם אזי ממילא שהי' בהם בחי' ביטול ויראת ה' הי' אוצרם, לכן נתייעצו לעשות מגדל כלומר שתהי' ההמשכה בבחי' מקיף עליהם ועי\"ז יקבלו כל טוב בגשמיות אבל הן עצמם בפנימיותם יהי' מרוחקים ממנה וילכו בשרירות לבם כו'.\n<b>והתיקון</b> הי' ע\"י שבמצרי' וימררו<sup data-n=\"1058\">25</sup> את חייהם בחומר ובלבנים כו' עד אשר ויזעקו ותעל שועתם כו' שהוא ענין מי בוכים<sup data-n=\"1059\">26</sup>, שמים<sup data-n=\"1060\">27</sup> תחתונים בוכים על עוצם ירידתם למטה בגשמיות וחפצם להתקרב ולעלות למעלה כמאמ' אנן בעינן למהוי קדם מלכא שזהו היפוך ממעשה דור הפלגה כו'.\n<b>והענין</b> כי הנה לע\"ל ג\"כ נאמר בבכי יבואו<sup data-n=\"1061\">28</sup> משום שצ\"ל גילוי טעמי תורה כמשפרש\"י<sup data-n=\"1062\">29</sup> ע\"פ ישקני מנשיקות פיהו שזהו עיקר ענין ביאת משיח וקיבול שכר הוא אח\"כ, ולהיות גילוי זה א\"א כ\"א ע\"י בכי' דוקא התעוררות רחמים הוא מדתו של יעקב שמבריח מהקצה אל הקצה עד היות ברחמיך<sup data-n=\"1063\">30</sup> הרבים רחם עלינו, כי אית רחמים שבגבול ומדה ונק' מדה\"ר אבל רחמיך הרבים הם שבבחי' א\"ס ממש, והיינו להיות כי הוא ית' המרומם לבדו מאז ויחיד חי העולמים מלך שחיות כל העולמות הוא רק מבחי' מל' דא\"ס אבל הוא ית' יחיד כו' ולכך ברחמיך הרבים רחם עלינו ואזי ותן בלבינו בינה להבין ולהשכיל הוא ענין קבלת התורה, וז\"ש בלילה<sup data-n=\"1064\">31</sup> שירה עמי, שיר בחי' טעמי תורה, כי ד' בחי' טנת\"א הטעמים הוא בחי' היותר עליונה שאינו מתגלה בדיבור כלל ונמשך ע\"י בחי' לילה דהיינו בעוה\"ז שדומה ללילה כי עולם חשוך הוא שנראה כאילו מתנהג הכל בטבעו זה רם וזה שפל מחמת שזה חכם כו'. וז\"ש לע\"ל ההרים<sup data-n=\"1065\">32</sup> והגבעות יפצחו לפניכם רנה.\n<b>והנה</b> כמ\"כ היה ענין גלות מצרים כדי להיות אח\"כ קבלת התורה ג\"כ ע\"י בכי' כו'. אך מה שהי' דוקא ע\"י יסורי הגוף הוא משום כי הנה הנפש אלקית שבאדם נמשכת מאדם העליון שעל הכסא אבל נפשותם הבהמית נמשכות מבחי' החיות שבמרכבה, וע\"י בכי' הנפש הבהמית והחיוני' מיסורי הגוף נתעורר ג\"כ",[["1058","25","<b>וימררו את חייהם . . ויזעקו ותעל שועתם</b>: שמות א, יד. ג, כג."],["1059","26","<b>מי בוכים</b>: ראה לקו\"ת במדבר ג, ב. ובהמ\"מ שם."],["1060","27","<b>שמים תחתונים בוכים . . אנן בעינן</b>: ראה תקו\"ז ת\"ה (יט, ב). וראה ס' מאמרי אדהאמ\"צ בראשית ע' קג. וש\"נ."],["1061","28","<b>בבכי יבואו</b>: ירמי' לא, ח."],["1062","29","<b>כמשפירש\"י ע\"פ ישקני מנשיקות פיהו</b>: שה\"ש א, ב. וראה סה\"מ תר\"מ שם ע' עז, ובמ\"מ שם."],["1063","30","<b>ברחמיך הרבים רחם עלינו</b>: נוסח ברכות ק\"ש."],["1064","31","<b>בלילה שירה עמי</b>: תהלים מב, ט. וראה גם תו\"א מקץ לא, ג ואילך. תו\"ח מקץ עח, ד ואילך."],["1065","32","<b>ההרים והגבעות יפצחו לפניכם רנה</b>: ישעי' נה, יב."]]],[2101920202,"למעלה להיות<sup data-n=\"1066\">33</sup> ארי נוהם ושור גועה כו'. והם הן המעוררים למעלה להיות גילוי רחמים רבים כו'.\n<b>וז\"ש</b> אח\"כ ואזכור<sup data-n=\"1067\">34</sup> את בריתי את אברהם כו', כי באמת להיות התעוררות רח\"ר העליוני' ע\"י התעוררו' רחמים שממדות שלמטה בבחי' גבול הוא רק מחמת הכריתת ברית כו', והיינו מחמת וגם אני שמעתי את נאקת בנ\"י אשר מצרים מעבידים אותם ביסורי הגוף ומחמת רח\"ר אלו מתעורר ואזי והבאתי<sup data-n=\"1068\">35</sup> אתכם אל הארץ אשר נשאתי* את ידי כו'. כי הנה א\"י נק' ארץ כנען מל' תגר כמו כנעניה<sup data-n=\"1069\">36</sup> נכבדי ארץ כו', כמו ענין המו\"מ בגשמיו' שהלוקח נותן מעט באיזו סחורה ואח\"כ לוקח עבורה הרבה וזהו הריוח, וכמ\"כ הוא ענין ארץ כנען, כי עיקר מעלת א\"י הוא מצד הקרבנות וכן פיאות וביכורי' תרומו' ומעשרות שהן הן המצות התלויות בה ונודע ענין הקרבנות שהוא בחי' העלאת הניצוצות שנמשכו מחיות שבמרכבה ונתלבשו בבהמות וחיות גשמיות שעי\"ז ממשיכי' הארה עליונה במאד וה\"ז כמו המו\"מ כנ\"ל.\n\n*)<i>נשאתי את ידי כו':</i>בשולי העמוד נרשם בגוכי\"ק כ\"ק אדמו\"ר הצ\"צ:\nנשאתי שלא ינקו ע' קדושת לוי ומ\"ש בד\"ה וזאת[ftnref_2151_א] המצוה כו' לשמור כו'.",[["1066","33","<b>להיות ארי נוהם ושור גועה כו'</b>: ראה גם לקו\"ת במדבר י, א ואילך. יא, ב."],["1067","34","<b>ואזכור את בריתי אברהם כו' . . וגם אני שמעתי</b>: ע\"פ וארא שם, ה. שמות ב, כד."],["1068","35","<b>והבאתי אתכם אל הארץ</b>: וארא שם, ח."],["1069","36","<b>כנעניה נכבדי ארץ</b>: ישעי' כג, ח. וראה גם תו\"א וישב כו, ג. מאמרי אדה\"ז עה\"ת ח\"א ע' קפד. ובכ\"מ.\n\n[ftn_2151_א]) ראה לקו\"ת ואתחנן ט, א ואילך."]]],[2101920203,"<h3>להבין מ\"ש בלקוטי תורה בענין טעם דמ\"ע שהזמן גרמא</h3>\n<b>להבין</b><sup data-n=\"1070\">1</sup> מ\"ש בלקוטי תורה<sup data-n=\"1071\">2</sup> בענין טעם דמ\"ע<sup data-n=\"1072\">3</sup> שהזמן גרמא נשים פטורות ושאין הזמן גרמא חייבות לפי ששורש נשמות הנשים הוא מעלמא דנוק' בחי' המל' שהוא בבחי' זמן מלך מלך<sup data-n=\"1073\">4</sup> וימלוך כו' ובחי' המל' מלבשת עד החזה דז\"א, שהוא עד בחי' הדעת דז\"א שכולל חו\"ג שמשם שורש ה\"ח דרמ\"ח מ\"ע וה\"ג דשס\"ה ל\"ת והדעת דנוק' כלול בדעת דדכורא ע\"כ מ\"ע שהז\"ג שהוא רק בבחי' המל' שמלבשת לחזה בלבד הרי שם נכללת ונטפלת בדעת דדכורא, ולכך פטורים לפי שיוצאים י\"ח במ\"ע שעושין בעליהן הזכרים אבל מ\"ע שאין הז\"ג ששרשם למעלה מן החזה שאין בחי' מל' מלבשת שם חייבות לעשות בעצמן ואין יוצאות בהן במה שעושין בעליהן הזכרים אחר שאינן נכללי' שם בבעליהם כו'.\n<b>אך</b> א\"כ יש להקשות קושי' גדולה וחזקה למה מ\"ע שאין הז\"ג נשים חייבות לעשות בעצמן והו\"ל לפוטרן לגמרי מאחר שמ\"ע הללו למעלה מהזמן שהוא למעלה משורש הנשים שהוא רק בבחי' הנוק' בחי' מל' כנ\"ל שאין בחי' מעשה שלהן מגיע לשם כלל, אלא בהכרח לומר דגם שמ\"ע שאהז\"ג הם למעלה מהזמן",[["1070","1","<b>להבין מ\"ש בלקוטי תורה</b>: מאמר זה הוא מפ' בא תקע\"ב. והובא גם בתו\"א קמ, ג [ובהוצאות קודמות של התו\"א הוא בדף קמב, א], וז\"ל: אולי מהאי טעמא נשים פטורות ממ\"ע שהזמן גרמא כי הזמן הוא בחי' אחרונה ועיקר הזמן למטה בעשי' וצריך בירור והם אין בהם כח לברר כו', במקום אחר נתבאר הטעם בענין אחר דבחי' נוק' הוא זמן ומקום והמצוה התלוי' בזמן היינו להמשיך מלמעלה דהזמן בזמן ובבחי' נוק' אין כח זה כו' כיון שעיקרה מבחי' זמן, ועי' בטעמי מצות התירוץ בענין אחר ונת' זה בפ' בא תקע\"ב. ע\"כ בתו\"א [וקאי על המאמר שלפנינו שהוא מפ' בא תקע\"ב].\nוראה תו\"א בהוספות קיא, ב (נדפס גם בסה\"מ תקס\"ז ע' עח): וכידוע בע\"ח הטעם דמ\"ע שהזמן גרמא נשים פטורות לפי ששורש הזמן הוא בבחי' נוקבא כו'. ועד\"ז הובא בס' מאמרי אדה\"ז עה\"ת ח\"א ע' קלח. סה\"מ תקס\"ח ח\"א ע' לד. ע' תל. ח\"ב ע' תרעג. מאמרי אדהאמ\"צ בראשית ע' תקכ. שמות ח\"א ע' קג. נ\"ך ע' רכו. תו\"ח שמות ח\"א רמב, ד. אמרי בינה שער הק\"ש פל\"ז. פמ\"ח. פירוש המלות לאדהאמ\"צ סז, ג. שערי תשובה לאדהאמ\"צ קה, ב. וראה הלשון בסה\"מ תקס\"ח ח\"א ע' תיג: דשורש בחי' הזמן הוא במל' כמ\"ש ה' מלך ה' מלך ה' ימלוך כו' וכמ\"ש בפע\"ח דמ\"ע שהז\"ג נשים פטורות כו'.\nוראה גם על הלקו\"ת להאריז\"ל בענין מ\"ע שהזמן גרמא באוה\"ת פ' בא ע' שמט, ושם שקו\"ט בזה ומביא ג\"כ מס' מערכת אלקות שער האדם בתחילת השער וז\"ל: שהרי היא משועבדת לבעלה בכל הזמנים ואולי מפני כו' כי ברוך כבוד ה' ממקומו בזמנים ואין צריכות המשכה כמו האנשים ולכן תשאר' היא משועבדת לבעלה אבל מ\"ע שלא הזמן גרמא הן חייבות כמו האנשים כי גבוה מעל גבוה שומר וגבוהים עליהם כי אין אדם מקדיש דבר שאינו ברשותו כי כולם פונים למקום אחד ע\"כ.\nועוד בארוכה על הלקו\"ת בראשית באוה\"ת פינחס ע' א'קצט. ביאוה\"ז להצ\"צ ח\"א ע' קמח. וראה סה\"מ תרכ\"ט ע' רמח. וע' שלג."],["1071","2","<b>בלקו\"ת בענין טעם דמ\"ע שהז\"ג</b>: ראה טעמי המצות (בלקו\"ת להאריז\"ל) פ' בראשית. ע\"ח שער קיצור אבי\"ע (ש\"נ) פ\"ד. שער מאמרי הרשב\"י על תקו\"ז תס\"ט (ת\"א תשכ\"א, דף ט' ע\"א). וראה גם ס' כנפי יונה ח\"א פע\"א."],["1072","3","<b>דמ\"ע שהזמן גרמא נשים פטורות</b>: קידושין כט, א (במשנה). ובכ\"מ."],["1073","4","<b>מלך מלך וימלוך כו'</b>: ראה זח\"א לד, א."]]],[2101920204,"מ\"מ הרי הם באים ומתלבשים בבחי' מעשה בזמן ומקום רק שאינם תלוים בזמן דוקא א\"כ גם במ\"ע הללו יצאו הנשים במצות שעושין הזכרים כמו במ\"ע שהז\"ג, ואם נא' שיש שורש לנשים גם בלמעלה מהזמן (לפי שכל הנשמות נולדו מיחוד זו\"נ בבחי' האצי' בין נשמות דדכורא ובין נשמות דנוק' כו') א\"כ יהיו יוצאי' גם בהם ע\"י הזכרים ולמה מ\"ע שבזמן נבדל ממ\"ע שלמעלה מן הזמן, ולפי\"ז הקושי' הוא ממ\"נ דאם אין שורש כלל לנשים בלמעלה מהזמן יהיו פטורות לגמרי במ\"ע שאהז\"ג ואם יש שורש לנשים בלמעלה מהזמן יהיו יוצאים גם בהם ע\"י הזכרים כמו שיוצאי' במ\"ע שהז\"ג וד\"ל.\n<b>אלא</b> צ\"ל דודאי יש שרש לנשים בלמעלה מהזמן (מטעם הנ\"ל ששורש א' לנשמות זכרים ונקבות כו') וע\"כ הם חייבות במ\"ע שאזה\"ג אך מה שאין יוצאי' בהם ע\"י בעליהן הזכרים כמו במ\"ע שהז\"ג היינו מפני שבמ\"ע שבזמן ששרשם בבחי' החזה שדבוק שם בחי' המוחי' דנוק' ונכללת בדעת דדכורא ע\"כ יוצאי' ע\"י בעליהן אבל במ\"ע שאין הזמן גרמא שאין הנוק' מלבשת שם היאך תצא ע\"י בעלה מאחר שאינה נכללת בו והיא חייבת בהן מפני שיש לה שורש שם כנ\"ל וד\"ל.\n<b>אך</b> עדיין י\"ל האיך אפשר שיש שורש לנשים בלמעלה מהזמן מאחר שכל עיקר הנוק' שמשם שורש נשמות הנשים אינה מלבשת רק עד החזה ולא למעלה מהחזה כנ\"ל והזמן שרשו רק בבחי' המל' שהוא למטה מן החזה ולא למעלה הימנו כלל, אמנם שורש הדברים הוא אעפ\"י שאין המל' מלבשת בבחי' הלבשה רק עד החזה מ\"מ שרשה הוא למעלה מעלה גם מבחי' המוחי' דז\"א שהרי ידוע דלפעמים נבנה בנין הנוק' בפרצוף בפ\"ע ועומדת פב\"פ ולא עד החזה בלבד ולעתיד<sup data-n=\"1074\">5</sup> יהיו שוין בקומתן ולפעמים<sup data-n=\"1075\">6</sup> עולה המל' עד פנימי' ע\"י כמו בנעילה דיוהכ\"פ, וא\"כ גם במ\"ע שאין הזמן גרמא שהוא למעלה מהזמן שבבחי' המל' שמלבשת בחזה חייבות הנשים מצד שורש בחי' הנוק' עצמה כמו שהוא במוחי' ומדות בפ\"ע ומכש\"כ כשאינה מקבלת מז\"א כלל כמו לעתיד או עכשיו בפרקים כנ\"ל, וע\"כ א\"א לומר שבמ\"ע שאזה\"ג יהי' הנשים יוצאות י\"ח בבעליהם אלא צריכים לעשות בעצמן דוקא, דמה שיוכלו לצאת ע\"י בעליהן א\"ז רק באותה מדרי' שהן נטפלות לבעליהן כמו במ\"ע שבזמן שהוא במקום שהיא נטפלת לחזה כו' אבל לא באותה מדרי' שהן בשרשן במל' כשהיא בבחי' מהות בפ\"ע כמו בבחי' פב\"פ ושוין בקומתן ולמעלה מזה כמו כאשר תתעלה המל' ונק' א\"ח<sup data-n=\"1076\">7</sup> עט\"ב כידוע",[["1074","5","<b>ולעתיד יהיו שוין בקומתן</b>: ראה ע\"ח שער מיעוט הירח (של\"ו) פ\"ו."],["1075","6","<b>ולפעמים עולה המל' עד פנימי' ע\"י כמו בנעילה דיוהכ\"פ</b>: ראה פע\"ח שער יוהכ\"פ (שכ\"ז) ספ\"א ופ\"ה. תו\"א בשלח סב, א. לקו\"ת מסעי צג, ד. שה\"ש כא, א. סידור עם דא\"ח רמט, ג. רנ, ד. מאמרי אדהאמ\"צ דברים ח\"ג ע' א'קה. שער האמונה לאדהאמ\"צ כד, ב (וע\"ש במ\"מ). אוה\"ת אחרי ע' פז וע' צ. ובכ\"מ."],["1076","7","<b>א\"ח עט\"ב כידוע</b>: משלי יב, ד. וראה גם שערי תשובה לאדהאמ\"צ כב, ג."]]],[2101920205,"וע\"כ במ\"ע שאזה\"ג חייבות לעשות בעצמן כמו הזכרים ממש, ואין יוצאי' י\"ח ע\"י בעליהן כלל וד\"ל. (ואפי' נשמות הגבוהות דנשים כמו האמהו' שרה רבקה רחל ולאה שלפני מ\"ת שקיימו כל המצות ברוחני' כמו האבות כידוע יש חילוק בזה בין במ\"ע שבזמן למ\"ע שלמעלה מהזמן רק אפשר שבהן יש הפרש משאר נשים לפי שאמרו ג'<sup data-n=\"1077\">8</sup> אבות הטעימן מעין עוה\"ב שהוא לאחר הבירור דב\"ן יהי' למעלה כמ\"ש א\"ח עט\"ב וע\"כ א' כל<sup data-n=\"1078\">9</sup> אשר תאמר אליך שרה שמע בקולה כו' כמ\"ש במ\"א).\n<b>והנה</b> באמת עדיין אין דבר זה מתיישב היטב על בוריו דהלא ידוע דעכשיו נא' והוא<sup data-n=\"1079\">10</sup> ימשל בך דבחי' מ\"ה דדכורא מושל על בחי' ב\"ן דנוק' לפי שכל עיקר המוחי' שלה מקבלת מחזה דז\"א, [שבתחלה הי' דו פרצופי' ואחר הנסירה מלבשת עד החזה כו'], וגם בהיותה בבחי' פב\"פ כמו במ\"ת ובזמן דוד ושלמה כו' מ\"מ נא' והוא ימשל בך כו' (כמו הלבנה שגם במילואה מקבלת הכל מאור השמש או כמו זכר ונקבה גשמיים דגם שהנקבה פרצוף בפ\"ע מ\"מ מקבלת מן הזכר והוא ימשל בה כו' שכלולה בדעת דדכורא וע\"כ מ\"ע שהז\"ג פטורות כנ\"ל), וגם זה ידוע דשורש רמ\"ח מ\"ע בין שהז\"ג ובין שאין הז\"ג שכללותם הוא רק בחי' ה\"ח שבדעת דז\"א, וא\"כ גם שאין הז\"ג יכולים לצאת הנשים ע\"י בעליהן מאחר שנכללות דעתן בדעת דז\"א כו', ואם מפני שלפרקים או לעתיד כתי' א\"ח עט\"ב ואינה בחי' מקבל כלל מז\"א הרי אז מ\"ע שהז\"ג ומ\"ע שאהז\"ג שוין שחייבות בשתיהן ולא נפטרו כלל בבעליהן כו' ואם נא' שבבחי' פב\"פ אין ה\"ח דמ\"ע נמשך למל' מהחזה אלא מבחי' ארחין דגלגלתא כו' מ\"מ יצאו י\"ח ע\"י בעליהן מאחר שנא' והוא ימשל בך כו' ומהו ההפרש בין שהז\"ג לשאין הז\"ג כו', ועוד דעכשיו בזמן הגלות בחי' המל' אינה רק בחי' נקודה תחת יסוד ולפעמים מלבשת עד החזה כנ\"ל כמו בשבת כו' והמצות נתנו לבנ\"י גם בהיותם בגלות וא\"כ למה במ\"ע שאזה\"ג לא יפטרו ע\"י בעליהן כמו במ\"ע שהז\"ג כו', וע\"כ הדרא קושי' לדוכתי' דגם שיש לנשים עכשיו שרש בלמעלה מהזמן כמו לעתיד דכתי' א\"ח עט\"ב כו' מ\"מ מצד שהמצות שרשן רק ה\"ח דז\"א, כמ\"ש זה<sup data-n=\"1080\">11</sup> זכרי כו', יכולי' הנשים לצאת י\"ח משום שנכללי' עכשיו עכ\"פ בדעת דז\"א כמ\"ש והוא ימשל בך כו' ולמה יהי' הפרש בין שהז\"ג לשאין הז\"ג כו' וד\"ל.\n<b>אך</b> הנה יש להקדי' לזה ענין א' הידוע בכללות כל הנשמות שיש בהן ה' מדרי' נר\"ן חי' יחידה, וגם מי שאינו רק בבחי' נפש דעשי' יש לו גם בחי' רוח ונשמה ח\"י רק שבחי' נפש בא בגילוי בעשי' ובחי' רוח נשאר בהעלם ביצי' ובחי' נשמה נשאר בהעלם בבריאה ובחי' חי' באצי' כידוע דה' מדרי' דנר\"ן ח\"י נפש",[["1077","8","<b>ג' אבות הטעימן מעין עוה\"ב</b>: ב\"ב טז, ב. וראה שער האמונה לאדהאמ\"צ נד, ב. וש\"נ."],["1078","9","<b>כל אשר תאמר אליך שרה . . כמ\"ש במ\"א</b>: וירא כא, יב. ראה לקו\"ת שה\"ש טו, ג. תו\"ח חיי\"ש קכו, א ואילך. ובכ\"מ."],["1079","10","<b>והוא ימשל בך</b>: בראשית ג, טז."],["1080","11","<b>זה זכרי</b>: שמות ג, טו."]]],[2101920206,"בעשי' ורוח ביצי' ונשמה בבריאה ובחי' חי' בחכ' שבאצי' ובחי' יחידה בבחי' כתר כו', וזהו דרך כלל בכל מציאות נפש או רוח ונשמה דנר\"ן הם בבחי' בי\"ע וחי' שלהם בבחי' מזלא כמו שאמרו גבי חברי דניאל אע\"ג<sup data-n=\"1081\">12</sup> דאיהו לא חזי מזלייהו חזי דהיינו המראה שראה דניאל כפי שרש נשמתו ביצי' או בעשי', והנה אליו בא בגילוי המראה גם בבחי' נר\"נ שבו, אבל לחביריו לא בא אור הגילוי זה בבחי' נר\"נ שלהם וז\"ש דאינהו לא חזי אבל מזלייהו בבחי' יחידה שלהם ראו וחזו, וזהו מזלייהו חזי ע\"כ חרדה נפלה עליהם עכ\"פ אע\"ג דלא חזי, מצד בחי' המקיף הנק' מזלא שמאיר גם בתוכן לפעול החרדה כו'.\n<b>וכך</b> יובן בכל מי שעושה מצוה למטה גם שאינו רק מבחי' נפש דעשי' הרי גם בחי' רוח שלו שביצי' ובחי' נשמה שלו שבבריאה עד בחי' ח\"י שנק' מזלא שבאצי' ג\"כ עוסקים במצוה זו, (וכמ\"ש<sup data-n=\"1082\">13</sup> בכוונות דט\"ז ע\"ב) דכמו שהאדם עוסק למטה כך דיוקן אדם העליון למעלה כו' ע\"ש ופי' דיוקן האדם הזה כמו שהוא למעלה הוא בחי' מזלא שלו שהוא בחי' שורש נשמת האדם למעלה מעלה כו', וא\"כ הרי יובן ג\"כ בענין מצות מעשיות דנשים ששרשם בבחי' המל' שמלבשת עד החזה כו' שאין זה רק בבחי' נר\"נ דוקא אבל בחי' ח\"י שנק' בחי' מזלא ה\"ה למעלה הרבה מבחי' המדות שבז\"א כידוע דשורש המצוה העצמי' דבחי' המל' הוא בפנימי' אור אבא דאבא יסד ברתא עד\"מ מאותיות השכל שמהם נמשך הדיבור במבטא, וע\"כ<sup data-n=\"1083\">14</sup> התינוק אינו יכול לצרף אותיות הדיבור כידוע מפני שאין בו כח החכ' לצרף כו' וגם אותיות שבשכל שרשן מעצמיות הנפש שהוא בבחי' חי'<sup data-n=\"1084\">15</sup>, וכמ\"ש במ\"א מענין ויהי<sup data-n=\"1085\">16</sup> האדם לנפש חי' ות\"א לרוח ממללא כו', וכך למעלה יובן בכל ענין עליות המל' עד פנימי' החכ' ופנימי' הכתר כנ\"ל הכל הוא בבחי' עצם כח הדיבור כאשר עולה לשרשו שמשם לוקח מקור חוצבו כו' עד\"מ כמו הדיבור שבאדם שעולה למעלה בעצמות נפשו בבחי' חי' יחידה שבו כנ\"ל אבל בחי' הדבור הבא במבטא יוצא הוא מהבל הלב שנק' חזה כנראה בחוש שהתפשטות או צמצום המבטא תלוי בהבל החזה אם הוא בהתפשטו' כמו בעת השמחה או בכיוווץ כמו בעת הצער וכה\"ג. וזהו נקבה<sup data-n=\"1086\">17</sup> ל' נקב ה' דהבל הלב שמשם יוצא הקול כו' ומשם נמשך ג\"כ בחי' המוחי' והמדות שבדיבור אבל בחי' עצם כח הדיבור הוא בבחי' פנימיות דח\"י שבנפש כנ\"ל, וכך יובן למעלה בבחי' המל' שנק' דיבור שגם שאמר דמלבשת עד החזה כו' היינו רק בבחי' הדיבור עצמו הבא בגילוי כמו ויאמר<sup data-n=\"1087\">18</sup> אלקים יהי אור כו' וכה\"ג אבל שורש עצם הדיבור העליון הוא בבחי' פנימי' חכ' וכתר כו' וד\"ל.",[["1081","12","<b>אע\"ג דאיהו לא חזי מזלייהו חזי . . חרדה נפלה עליהם</b>: מגילה ג, א. דניאל י, ז."],["1082","13","<b>וכמ\"ש בכוונות דט\"ז ע\"ב</b>: ס' הכוונות, דפוס ווינצי' ש\"פ. וכן הובא גם בתניא קו\"א (קנג, סע\"א)."],["1083","14","<b>וע\"כ התינוק אינו יכול לצרף אותיות הדיבור כידוע</b>: תניא אגה\"ק ס\"ה (קז, ב). לקו\"ת שלח לז, א. ובכ\"מ."],["1084","15","<b>חי'</b>: בכת\"י ב: יחידה."],["1085","16","<b>ויהי האדם לנפש חי'</b>: בראשית ב, ז."],["1086","17","<b>נקבה ל' נקב ה'</b>: ראה לקו\"ת קדושים כט, ד. וש\"נ."],["1087","18","<b>ויאמר אלקים יהי אור</b>: בראשית א, ג."]]],[2101920207,"<b>ובזה</b> יובן דכאשר בחי' נר\"ן דנשים עוסקין במ\"ע שהז\"ג שהוא רק בחי' המל' המלבשת עד החזה שנר\"ן שלה רק מהחזה כו', גם ששרשן בחי' יחידה למעלה, מ\"מ פטורות ע\"י בעליהן מפני שאין בחי' דיוקן שלהם עוסק במ\"ע זו מאחר שאין שורש מ\"ע זאת רק בזמן דבחי' המל' שמקבלת מהחזה כו', אבל מ\"ע שאהז\"ג גם שבחי' גילוי שלה בבחי' ה\"ח דדעת דז\"א בלב כנ\"ל מ\"מ שרשה של בחי' מל' ה\"ה למעלה בבחי' פנימי' חכ' וכתר כנ\"ל וא\"כ כמו שעוסקים למטה בנר\"ן שבה כך הוא בבחי' מזלא דילה בפנימי' הכתר ששם אין בעלה מושל עליה, וכמו לע\"ל דכתי' א\"ח ע\"ב כנ\"ל, ע\"כ חייבות לעשות בעצמן דוקא מצד בחי' שרש עסק מ\"ע שאהז\"ג בבחי' דיוקן שלהם הנק' מזלא משא\"כ במ\"ע שהז\"ג וד\"ל."],[2101920208,"<h3>הנה להבין ענין הנ\"ל בתוס' ביאור</h3>\n<b>ביאור על הנ\"ל</b>\n<b>הנה</b><sup data-n=\"1088\">1</sup> להבין ענין הנ\"ל בתוס' ביאור יש להקדים שרש ענין המצות מעשיות למה ענין שלהם גדול במעלה כו' כמאמר היום<sup data-n=\"1089\">2</sup> לעשותם דוקא וכידוע, וראי' לזה הוא מה שמצינו במשרע\"ה שהתנפל<sup data-n=\"1090\">3</sup> לפני ה' ובקש לכנוס לא\"י כדי לקיים מ\"ע התלוים בה כמו תרומות ומעשרות וגם שהם בדברי' גשמי' כמו תבואות הארץ כו', וגם נתן כל נפשו על דבר זה כידוע שאמרו לו שכאשר יכנס לא\"י יסתלק נבואתו ויהי' כהדיוט גמור מ\"מ קיבל והוסכם בכך רק שיקיים מ\"ע התלוי' בארץ, וזה פלא גדול דהלא שרש נבואתו הי' גילוי אור א\"ס בח\"ע בחי' אור אבא כו' וכידוע, וכאשר יהי' כהדיוט גמור בלי גילוי אור אלקי רק בבחי' עשי' כנפש דהע\"ה כו' ה\"ז מאיגרא רמה כו' ואיך הוסכם לכך להחליף דבר זה במה שיקיים המצות שבארץ כו', אלא בהכרח לומר שנפלאה בעיניו מעלת ומדרי' קיום המצות בגשמיות יותר ממדרי' השגת נבואה פא\"פ כו' בבחי' גילוי אור א\"ס בח\"ע כו', והוא לפי ששורש קיום המצות בפו\"מ בעשי' גשמי' דוקא יותר עליון גם מבחי' גילוי אור א\"ס בחכ', וזהו פלא לכאורה ואם מפני שנעוץ<sup data-n=\"1091\">4</sup> תחלתן בסופן שהוא בחי' סוף מעשה דוקא כידוע, אבל איך יש יתרון מעלה בסופן מבתחילתן מאחר שאין בסופן רק מבחי' תחילתן כו'.\n<b>אך</b> הנה שרש מצות מעשיות הוא בחי' המשכת סוכ\"ע בלבד כידוע שהרי שרש המצות הוא דוקא בחי' פנימי' רצון העליון הנ\"ל רצון הפשוט כנ\"ל שהוא",[["1088","1","<b>הנה להבין ענין הנ\"ל בתוס' ביאור</b>: ראה גם ד\"ה ענין היום לעשותן, בסה\"מ הנחות הר\"פ ע' קלה. וראה להלן ברשימת הכת\"י על מאמר זה."],["1089","2","<b>היום לעשותם דוקא</b>: ואתחנן ז, יא. עירובין כא, ב."],["1090","3","<b>שהתנפל לפני ה' . . כדי לקיים מ\"ע התלוים בה</b>: ואתחנן ג, כג ואילך. סוטה כא, א."],["1091","4","<b>שנעוץ תחלתן בסופן</b>: ס' יצירה פ\"א מ\"ז."]]],[2101920209,"בחי' סובב כנ\"ל אמנם בחי' המשכה זאת הוא דוקא בבחי' ממכ\"ע שזהו שורש ענין המצות מעשיות שבא בבחי' עשי' ממש כמ\"ש היום לעשותם דוקא כנ\"ל.\n<b>ויש</b> להקדים תחלה בתוס' ביאור שורש ענין סובב וממלא וכל פרטי עניניו שבהם דהנה ידוע בביאור ענין בחי' ממכ\"ע שהוא בחי' ירידת האור האלקי הבא בבחי' צמצום והסתר מעילה לעלול בהשתל' רבות ועי\"ז נתהוו ריבוי הצמצומי' כ\"כ בצמצום אחר צמצום בג' עולמות בי\"ע עד שנתמעט האור בתכלית להיות רק התהוות צמצום חיות הנבראי' היותר אחרונים שהן כמו גידול דצ\"ח ממזלות כמו אין<sup data-n=\"1092\">5</sup> לך עשב מלמטה שאין כו'. ושורש הדברים הוא לפי שגם בראשית ירידת והמשכת השפע לבא בבחי' ממכ\"ע הנה הוא בא בבחי' השתלשלות עו\"ע שבהכרח שמתמעט האור ומתצמצם ומתעלם בעילה טרם שנתהוה ממנו העלול ועד\"ז הולך ומתמעט האור בהשתלשלות מעילה לעלול בריבוי ירידות והמשכות מעילה לעלול עד בחי' מיעוט וצמצום היותר אחרון שבסוף העשי' כמו וממגד<sup data-n=\"1093\">6</sup> תבואת שמש כו', ולהבין ביאור ענין המיעוט והצמצום שבעילה כשמשפיע אל העלול הנה אנו רואים התהוות המדות מהשכל שנק' עו\"ע כמו מדת החסד שמתהוה ונולד מן השכל ונק' השכל עילה והחסד עלול, והגם שאנו רואים שהחסד הוא מהות אחר נבדל לגמרי ממהות ומציאות השכל עד שנחשב התפעלות החסד בלב בערך גשמי' לגבי מהות אור השכל שבמוח הרוחני' כו' הנה מ\"מ הרי אנו רואי' שיש ערך והשתוות לחסד שבלב עם השכל שבמוח שהרי ידוע שכל מי ששכלו גדול גם מדת חסדו גדול יותר וכל ששכלו קטן גם מדת חסדו קטן וכמ\"ש לפי<sup data-n=\"1094\">7</sup> שכלו יהולל איש כו' שהרי התינוק יש בו אכזריות יותר והגדול יש בו בחי' רחמי' וחסדי' יותר, והיותר גדול בחכ' או בדעת הוא חסדן בטבע יותר (ולא מצד טבע הלב אלא מצד טבע המוח לפי שכלי מוחו רחבים לפי רוחב שכלו כו', ע\"כ טבעו נוטה כלפי חסד ביותר והמוח שליט על הלב להטותו כפי טבע המוח גם שטבע הלב אכזרים היפוך המוח, וזהו ההפרש ניכר באדם מקטנותו לגדלותו וכן מקטן הדעת לגדול הדעת כו') וכמ\"ש<sup data-n=\"1095\">8</sup> במ\"א בענין אבינו אב הרחמן כו' ואור אבא מקור החסדי' כו' וכמו שהאב רחמן כו', ולפי הנראה בזה הרי יש בהכרח מבחי' החכ' ממש בחסד עד שלפי גודל השכל כך גודל החסד כו' וא\"כ למה בהולד החסד מן השכל הוא בא בשינוי המהות כנ\"ל אלא בהכרח לומר שכל עילה מתצמצמת בעצמותה טרם שיתהוה העלול גם שהעלול בא מבחי' עצם העילה, אבל להיות מהות בפ\"ע הוא בא בשינוי המהות, וכאשר עדיין העלול כלול בהעילה ה\"ה במהות העילה אך ביציאתו להיות דבר בפ\"ע אזי מתעלם העילה ואין בהעלול רק בחי' היותר אחרונה שבעילה לאחר שנתצמצם ונתעלם בעצמו אבל מ\"מ העלול הוא מעין העילה ויש מבחי' עצם העילה בהעלול רק שהוא שם בבחי' ההעלם",[["1092","5","<b>אין לך עשב מלמטה</b>: ב\"ר פ\"י, ו."],["1093","6","<b>וממגד תבואות שמש</b>: ברכה לג, יד."],["1094","7","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["1095","8","<b>וכמ\"ש במ\"א בענין אבינו אב הרחמן</b>: ע\"פ נוסח ברכות ק\"ש. וראה סידור עם דא\"ח י, א. תו\"א שמות קח, ג. תו\"ח שמות ח\"ב שסא, א. וראה גם סה\"מ תרכ\"ט ע' פא (ובהמ\"מ שם ס\"ע פ)."]]],[2101920210,"והצמצום כו' וכמו מדת החסד כאשר הוא כלול בעילתו שהוא השכל אז הוא במהות השכל והוא ענין גידול החסד עם גידול השכל כאחד מצד אחיזתו בשכל דוקא כנ\"ל אבל בהוולד החסד מהשכל הוא בא בשינוי מהות כנ\"ל, ומ\"מ בהכרח שגם בהחסד שבלב יש בו מבחי' השכל עצמו רק שהוא בו בבחי' העלם והצמצום כי אין חסד העלול הזה רק מבחי' היותר אחרונה שבשכל לאחר שנתצמצם לעצמו כו' וד\"ל. וכמו\"כ מבחי' המדות שבלב שנמשך באותיות המח' ג\"כ בא ונמשך בשינוי המהות דהיינו כמו ממהות חסד שבלב למהות מח' של חסד זה במוח שאינו רק בחי' אותיות המח' בלבד ואין לו ערך לגבי אור החסד בעצמו שבלב מ\"מ יש במח' זו מבחי' עצם החסד שבלב כי ממנו נלקחה המח' זו שהרי מה שלבו חפץ מיד מהרהר במח' ונק' הרהורי ליבא כידוע רק החסד שבלב המלובש במח' זו הוא בבחי' הצמצום וההעלם כי אינו רק מבחי' אחרונה שבו כנ\"ל בחכ' וחסד כו', וכך הוא בהשתלשלות מן המח' לדבור שאין מהות המח' עצמה בדבור רק בחי' אחרונה שבו ואעפי\"כ יש בדיבור מן המח' שהרי אי אפשר לדבר בלא מח' וכמו\"כ מדבור למעשה כו' וד\"ל.\n<b>והדוגמא</b> מכ\"ז יובן למעלה בבחי' ממכ\"ע מריש כל דרגין שהוא בחי' ראשית הגילוי מאוא\"ס להיות מקור להשתלשלות שהוא מתגלה בבחי' החכ' כמ\"ש הוי' בחכ' כו' הנה זה האור בא בבחי' צמצום והסתר גדול וכמ\"ש והחכ' מאין תמצא כו' מאין ליש ע\"י בחי' צמצום גדול שנתצמצם להיות נק' חכים כו' כידוע דמצד עצמו לאו<sup data-n=\"1096\">9</sup> מכל אינון מדות כלל וכמו\"כ מתצמצם עוד האור בצמצום אחר צמצום מחכ' דאצי' למדות דאצי' ע\"ד הנ\"ל בבחי' צמצום המשכת החסד מהשכל כו', וכן מתצמצם עוד ממדות דאצי' לבחי' מחדו\"מ העליונים שהוא עולם הבריאה ועולם היצירה כו' כידוע דג' עולמות בי\"ע נק' בחי' מח' דו\"מ, ויש באצי' ג\"כ בי\"ע שהן בחי' מדו\"מ שבאצי' ומבחי' עשי' שבאצי' נעשה מקור לבי\"ע כו' והוא בחי'<sup data-n=\"1097\">10</sup> מל' דאצי' שנעשה ע\"י לבריאה כידוע וגם זאת ע\"י בחי' מסך מבדיל בין אצי' לבריאה הנק' פרסא כמ\"ש ויעש<sup data-n=\"1098\">11</sup> את הרקיע להבדיל וכמו\"כ מבריאה ליצי' יש בחי' פרסא המפסיק כו' ומיצי' לעשי' כו' עד שגם בסוף העשי' יש בחי' הרקיע המבדיל בין מים העליונים שמעל השמים כו' וע\"כ נתצמצם האור והשפע כ\"כ בריבוי צמצומים זא\"ז במיעוט אחר מיעוט והעלם אחר העלם עד שנמשך השפע בבחי' צמצום ומיעוט היותר אחרון, והוא כמו שפע המזלות בכל צמחי האדמה כמו ממגד תבואות שמש וממגד גרש ירחים כו' עד שאמרו אין לך עשב מלמטה שאין לו מזל מלמעלה כו' ואומר לו גדל כו' ואעפ\"י שהמזל הוא רוחני והעשב הוא גשמי מ\"מ המזל הוא מכה ומגדלו מן הרוחני' אל הגשמי' לפי שבאה שפע זו בבחי' צמצום דעו\"ע הנ\"ל שהעילה מתצמצם ונמשך ובא בהעלול בשינוי המהות כו' כנ\"ל בענין התהוות החסד מן החכ' כו' וכך בענין ממגד",[["1096","9","<b>לאו מכל אינון מדות כלל</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."],["1097","10","<b>בחי' מל' דאצי' שנעשה ע\"י לבריאה כידוע</b>: ראה ע\"ח שער העקודים (ש\"ו) פ\"ב."],["1098","11","<b>ויעש את הרקיע להבדיל</b>: ע\"פ בראשית א, ז."]]],[2101920211,"תבואת שמש שיש כמה צמחים שהשמש מגדלם מפני שצריכי' לחום השמש ויש הרבה צמחי' שצריכים לקור הלבנה כמו מיני ירקות כו' וכהאי גוונא וכ\"ז משינוי המהות מרוחני' לגשמיות ואעפי\"כ אחוז וקשור הגשם ברוחני' ע\"ד הנ\"ל בהשתל' שכל ומדות כו', וכמו\"כ בבחי' התהוות נפש החי דבהמות וחיות שנמשך ממקור חוצבו כח הרוחני בתכלית הבדלת ערך מהגשמת נפש החי והוא כידוע דמבחי' פני ארי' שבמרכבה נמשך בריבוי השתלשלות עו\"ע מקור כל נפשות החיות ומבחי' פני שור שבמרכבה נשמך מקור לנפש הבהמית והרי ידוע שבחי' פני ארי' אל הימין ופני שור כו' נק' חיות הקדש שהם בבחי' מרכבה עליונה הנושאו' את הכסא כו', והם בחי' מיכאל וגבריאל כו' מיכאל בסט' דחסד בבחי' פני ארי' אל הימין כו', וגבריאל בסט' דגבורה בבחי' פני שור כו', ואיך נא' שמבחי' גבריאל גבורה דקדושה עליונה נמשך ממנה למטה נפש שור גשמי כו' שבודאי רחוק הערך בתכלית הריחוק כו', אך שמ\"מ בריבוי השתלשלות בצמצום אחר צמצום ע\"ד הנ\"ל בענין השתל' עו\"ע יוכל להתהוות גם נפש השור הגשמי מבחי' פני שור שבמרכבה כמו בענין התהוות גידול העשב ממזל הרוחני כו' וד\"ל.\n<b>ונמצא</b> מובן מכ\"ז שבבחי' ממכ\"ע בחי' ההשתל' בא בהדרגת עו\"ע בצמצום אחר צמצום כו' מבחי' ראשית החכ' שבאצי' עד סוף כל הצמצומי' שבעשי' עד צומח ודומם הגשמי רק שבאצי' גם בבחי' הצמצום דאור א\"ס בחכ' ומדות ומודו\"מ כו' הלא אמרו דאיהו<sup data-n=\"1099\">12</sup> וחיוהי וגרמוהי חד כו' מצד בחי' הארת הקו\"ח כו' כידוע, אבל מאצי' לבי\"ע כבר נפסק הארת הקו כו' ע\"י בחי' מסך הנק' פרסא כו' ע\"כ שם בא האור האלקי בתכלית הצמצום להחיות רוח שפלים בע\"ג כו' כידוע וגם שם האור מתמעט במיעוט אחר מיעוט כו' כנ\"ל דיש פרסא שמפסיק בין בריאה ליצי' כו', ובחי' מל' דבריאה בוקע המסך ונעשה בחי' ע\"י ליצי' ועד\"ז מיצי' לעשי' ומפני זה הרי יש בחי' מעלה ומטה בכללות השתלשלות דבבחי' חכ' דאצי' שם בחי' גילוי האור ביותר ומחכ' דאצי' ולמטה מטה נתמעט גילוי האור במיעוט הגילוי מעט מעט כו' עד בחי' צמצום היותר אחרון כנ\"ל וד\"ל. וכל זה דוקא בבחי' ממלא כל עלמין שהוא מבחי' חכמה דאצי' שנק' ראשית הגילוי למטה מטה כנ\"ל אבל בחי' סוכ\"ע הוא הנק' בע\"ח בחי' מקיף הכללי ומקיף לד' עולמות אבי\"ע בשוה ממש כו' ואין שם בחי' מעלה ומטה כלל וכמ\"ש אני<sup data-n=\"1100\">13</sup> ראשון ואני אחרון שו\"א אני מלא בשוה כו' כמשל הידוע בעיגול המקיף מכל צד שאין בו בחי' מעלה ומטה כו'.\n<b>ואמנם</b> להבין ביאור הדברים, וגם להבין אם הוא בחי' סובב ומקיף בלבד הרי אינו בא בבחי' גילוי אור ושפע בד' עולמות למה נק' בש' אור מקיף הרי פי' אור הוא המאיר למטה שהוא בחי' אור ושפע וחיות כו', אך הענין הוא דבאמת גם שנק' בחי' מקיף וסובב מ\"מ הוא נק' אור המאיר ומחי' לכל העולמות דאבי\"ע",[["1099","12","<b>דאיהו וחיוהי וגרמוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["1100","13","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."]]],[2101920212,"רק שהוא מאיר ומחי' לכל העולמות בהשוואה א', לא כמו בחי' האור וחיות דבחי' ממלא שבא בבחי' חילוק מדרי' מעלה ומטה כנ\"ל.\n<b>ולהבין</b> זה דהנה לכאורה אין מקום לבחי' התפשטות החיות דבחי' סובב מאחר שכבר נמשך האור והחיות דבחי' ממלא כנ\"ל אך הענין הוא דגם לאחר שכבר נמשך האור בבחי' ממלא כנ\"ל הנה מאיר ומתפשט מבחי' סובב דוקא בכל פרט ופרט דהשתלשלות עו\"ע מריש כל דרגין דבחי' ממלא בחכ' כנ\"ל עד סוף כ\"ד למטה מטה דהנה גם שכבר נשתלשל כל עלול מעילתו בבחי' הצמצום מ\"מ עיקר קיום עצם מציאותו הוא בא מבחי' המקיף הנק' סובב שהוא הנק' בחי' אין האמיתי בכלל כמו גם ראשית של בחי' גילוי דבחי' ממלא שהוא בחכ' כנ\"ל הרי נא' והחכ'<sup data-n=\"1101\">14</sup> מאין תמצא ופי' תמצא לשון מציאה שהיא נמצאת במציאות דבר מ\"ה ונק' בשם חכמה עכ\"פ, ומאחר שא' שהחכ' תימצא מאין בהכרח לומר שנמצאת בבחי' יש גמור דהיינו שנמצאת מאין ליש ממש, ופי' אין ידוע שהוא בבחי' אין האלקי ממש שהוא מושלל בתכלית מכל בחי' יש ודבר מה במציאות כו', וא\"כ דבר זה פלא גדול מאד איך יתהוה מציאות יש גמור כמו החכ' מבחי' אין האלקי המוחלט כו' שבודאי א\"א שיומשך זה בדרך השתלשלות עו\"ע כנ\"ל מאחר שבבחי' עו\"ע יש בעלול מבחי' יחוס וערך העילה עכ\"פ רק שהוא מבחי' אחרונה שבו אחר צמצום עצמותו כמ\"ש למעלה באריכות, אלא בהכרח לומר שמאיר בבחי' התהוות החכ' ליש מבחי' אין האמיתי דוקא ואם לאו לא היתה החכ' נמצאת בבחי' יש וז\"ש תמצא בבחי' מציאות יש שזהו דוקא נעשה מבחי' אין דבחי' סובב הכללי (ולא מצד כח אור עליון השופע לחכ' כמו מבחי' הכתר שא\"כ לא הי' אור החכ' בבחי' יש אלא בבחי' הרוחני' דאור הכתר כו') וכמו\"כ גם מחכ' לבינה שהוא ג\"כ מאין ליש כידוע, שהחכ' הוא בחי' נקודא, והבינה הוא בחי' התפשטות ליש בהשגה כו' מ\"מ מה שהבינה נמצאת בבחי' יש ממש בעיקר מציאותה זהו אינה מצד כח אור החכ' השופע אליה אלא מלמעלה מעלה דהיינו מבחי' אין האמיתי דבחי' סובב הכללי ואם לאו לא היתה בבחי' יש גמור, וכן מבינה למדות אעפ\"י שהוא בחי' יש מיש כידוע שהחסד הי' כלול תחלה בשכל בהתפעלות החסד בשכל ואח\"כ יוצא לידי גילוי בדרך עו\"ע להיות התפעלות אהבה כו' וע\"כ ע\"פ שכלו דוקא יהולל איש שהתינוק ששכלו קטן מדותיו בדברים קטנים כו' וכן בגדולים עצמן הרי יש הפרש בין מי ששכלו מגושם שמוליד אהבה גשמי' כתאוות חומרי' למזון ומאכל, וכה\"ג ומי ששכלו דק ברוחני' יותר כמו שכל וחכ' האלקית בהתבוננות גדולת ה' יוליד אהבה אלקית כו'.\n<b>אך</b> הנה אעפי\"כ מה שהעלול של המדות נמצאו בבחי' יש ודבר מ\"ה במציאות אין זה מכח העילה שהוא השכל אלא מלמעלה מעלה מהחכ' ובינה, והוא מבחי' אין האמיתי כנ\"ל ואם לאו לא הי' בא תולדת המדות בשינוי המהות ובהגשמה כ\"כ בריחוק הערך ממהות השכל המולידו, וזהו רבותא גדולה יותר",[["1101","14","<b>והחכ' מאין תמצא</b>: איוב כח, יב."]]],[2101920213,"דגם בבחי' עו\"ע שנק' יש מיש ג\"כ אין התהוות הנשמה ושינוי המהות דעלול מערך המהות דעילה בא מצד כח העילה שלו אלא דוקא מבחי' סובב כו', וככה הוא מריש כל דרגין שבהשתלשלות מחכ' ולמטה עד סוף כל דרגין בעו\"ע היותר אחרון שבסוף עולם העשי' כו' כמו אין לך עשב שאין לו מזל כו' דהיינו כמו שהמזל עצמו אעפ\"י שהוא רוחני מ\"מ גשמי יחשב לגבי העילה שלו ואין זה רק מבחי' אין האמיתי כנ\"ל בחו\"ב ומדות כו' כך הוא ענין הגדלת העשב מהמזל הרוחני דבודאי א\"א לומר שהרוחני יוליד ויגדל את הגשמי מאחר שהרוחני מושלל בערך מכל תוארי הגשם וא\"כ איך המזל מכה ומגדלו, ואם נאמר שהמזל מכה לכח הצומח שבארץ ואומר לו גדל, גם זה יפלא ע\"ד הטבע איך כח הצומח הרוחני יצמיח עשב גשמי הלא כח הצומח כח היולי רוחני הוא דהיינו מה שיש בכחו להצמיח כמה פעמים עד אין שיעור ואין לו הפסק וכליון כגשם העשב שקוצרין ושורפין אותם כו', אלא בודאי מוכרח לומר שגם שצמיחת העשב באה מרוחני' כח הצומח והמזל הרוחני א\"ז רק צמיחתו וריבויו אבל לא גופו ומהותו מתהוה מן הרוחני' דהיינו שגוף גשם העשב הצומח הנתפס במישוש לא בא ונמשך מן הרוחני כלל אלא מציאות והגשמה שלו באה מלמעלה מעלה מבחי' אין ממש שהוא סובב הכללי ורק בחי' רוחני' שלו דהיינו חיות אורו בגידולו הוא שנמשך מהרוחני' דכח הצומח שבארץ אבל לא גשמיות שלו שזהו דבר הנמנע שהגשם עצמו יתהוה מן הרוחני כו' וד\"ל.\n<b>וכמו\"כ</b> יובן בחלק החי דבהמות וחיות ועופות דהנה ידוע דשורש כל נפשות הבהמות הוא נמשך מבחי' פני שור שמהשמאל שבמרכבה עליונה ושורש התהוות כל נפשות החיות נמשך מבחי' פני ארי' אל הימין כו' וזה ידוע דבחי' פני ארי' ופני שור כו' הן בחי' מלאכים רוחני' במעלה ומדרי' אור האלקי הרוחני' כמו מיכאל וגבריאל כו' שהרי נק' שרפים וחיות הקדש כו' ובחי' פני ארי' אל הימין הוא בחי' מיכאל ובחי' פני שור מהשמאל הוא בחי' גבריאל כו' וא\"כ איך אפשר שגם בהשתל' רבות ימצא למטה מציאות נפש השור גשמי מבחי' פני שור העליון הרוחני ביותר כמו שא\"א להעלות על הדעת שמבחי' גבריאל יסתעף למטה מציאות שור גשמי וכן מציאות ארי' גשמי מפני ארי' העליון שהוא בחי' מיכאל, גם אם אפשר שיומשך מהם בהשתלשלות רבות במיעוט אחר מיעוט עד שיתהווה ע\"י ריבוי הצמצומים מציאות דבר קטן הערך ביותר, היינו רק שבא שפע האור ע\"י ריבוי הצמצומי' להעלים ולהסתיר בהסתר אחר הסתר כו' מבחי' הגדלות לבחי' הקטנות בלבד כמו מבחי' יראה ופחד עליון הרוחני האלקי שבבחי' גבריאל או פני שור שבמרכבה כו' ע\"י ריבוי הצמצומי' וההעלמות יוכל להיות בחי' קטנות הערך ביותר והוא כמו להיות בחי' מציאות יראה ופחד גשמי' וכן מבחי' אור האהבה האלקי שבמיכאל או פני ארי' כו' ע\"י ריבוי הצמצומי' מתהווה למטה בחי' אהבה גשמי' כו' אבל לא שמפני הצמצוצמים יתהוה מציאות דבר גשמי' כשור וארי' גשמי' בחומר גופני [ולמה אמרו במיכאל<sup data-n=\"1102\">15</sup> וגבריאל שהם שר",[["1102","15","<b>במיכאל וגבריאל שהם שר של אש ושר של מים</b>: במדב\"ר פי\"ב, ח."]]],[2101920214,"של אש ושר של מים גשמי' כו'], אלא מוכרח לומר שבחי' הצמצום אינו מועיל רק להביא הדבר מבחי' הגדלות לבחי' הקטנות בקטנות אחר קטנות, אבל מה שמתהוה בבחי' הגשמה גמורה כמו נפש השור הגשמי א\"ז מכח העילה שהוא בחי' הרוחני' דפני שור כלל אלא מבחי' אין האמיתי כו' וד\"ל.\n<b>ונמצא</b> מובן עכ\"פ שבכללות כל ההשתלשלות דעו\"ע דבחי' ממלא כו' מריש כ\"ד דהיינו מבחי' האין שמאין תמצא עד למטה מטה בסוכ\"ד עד בחי' צומח וחי הגשמי', עיקר התהוות הגשמת העלול בשינוי המהות מעילתו בכל מקום לפי מה שהוא אין זה בא רק מבחי' האין האמיתי דבחי' סובב הכללי דוקא ולא מצד כח השתל' דממלא כו' כמובן מכל הנ\"ל.\n<b>ועוד</b> זאת מובן מכל הנ\"ל דבחי' אין דסובב הכללי מאיר הוא למטה מטה בסוכ\"ד יותר בגילוי מבמדריגות העליונות יותר בהשתל' דבחי' ממלא, כי כל מה שהדבר צריך לבא יותר בהגשמה ובשינוי המהות שם צ\"ל הארה גדולה ויתירה יותר מבחי' אין האמיתי דוקא, וכל שאין הדבר בא בריחוק הערך כ\"כ בירידת הגשמת המדרי' אלא הוא בבחי' הרוחני' עדיין א\"צ לבא בו כ\"כ בגילוי אור דאין לעשותו לבחי' יש מאחר שאינו בא בבחי' יש גמור כ\"כ. ודוגמא לדבר הנה בחכ' ומדות דגם שהתהוות המדות הוא בא בבחי' הגשמה ויש לגבי החכ' אשר ודאי שינוי מהות זה בא מבחי' אין האמיתי דוקא כנ\"ל. מ\"מ מאחר שהמדות עדיין רוחניים וקרובים בענין הרוחני' אל הרוחני' דחכ' רק שהן למטה במדרי' הימנה בבחי' הרוחני' כו' אינו מאיר בזה מבחי' סובב רק הארה בעלמא לעשות לבחי' יש דמדות לגבי החכ' בלבד, אבל כשיורד האור יותר למטה מטה עד שבא הדבר בהגשמה יותר כמו ממדות להתהוות גשמי' דפני שור כו' וכן מפני שור להיות התהוות נפש השור הגשמי הנ\"ל או מכח הצומח עשב גשמי כנ\"ל, שם צ\"ל הארה גדולה יותר מבחי' סובב, שכל שצריך לעשות יש גמור יותר שם צ\"ל הארה העליונה יותר מבחי' סובב כו', ונמצא דבירידת סוף כל המדרי' התחתונות עד דצח\"מ דעשי' שם מאיר מבחי' ומדרי' העליונה שבסובב הכללי ממה שמאיר מבחי' סובב בראשית השתלשלות דממלא כמו מחכ' לבינה ומבינה למדות ששם אין האור דסובב מאיר רק בהעלם וצמצום וכל שהאור דממלא הולך ומתצמצם יותר יותר יומשך שם מבחי' סובב עד שבדצ\"ח הגשמי' יש גילוי אור דסובב יותר מראשית הגילוי דיש דחכ' שבבחי' ממלא אעפ\"י שהחכ' מאין תמצא ג\"כ בבחי' יש גמור כנ\"ל מ\"מ אינו דומה בחי' יש גמור דדצ\"ח עם היש דחכ' כו'.\n<b>(אך</b> מ\"מ הרי אומר בע\"ח<sup data-n=\"1103\">16</sup> דאור מקיף וסובב הכללי הוא מקיף לד' עולמות בשוה וא\"כ אין זה בשוה דבחכ' ראשית הגילוי דממלא מאיר בצמצום ובסוף",[["1103","16","<b>בע\"ח דאור מקיף וסובב הכללי הוא מקיף לד' עולמות בשוה</b>: ראה גם (בשם הע\"ח) בשער היחוד לאדהאמ\"צ קכא, סע\"א. שערי אורה נה, א. עט, ב. פב, ב. ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תמ וע' תצה. דרך מצותיך סא, א. [וראה במ\"מ בסו\"ס מאמרי אדאהמ\"צ במדבר ח\"א ע' שג, דלשון ע\"ח כולל לפעמים את כל כתהאריז\"ל]. וראה גם תניא אגה\"ק ס\"כ (קלא, ב)."]]],[2101920215,"העשי' מאיר יותר כו'. אמנם הענין הוא דגם בזה הדבר מצד בחי' התהוות יש מאין אין הפרש בין יש גמור דדצ\"ח דעשי' ליש דח\"ע שניהם שוים בבחי' היש ע\"כ מאיר על כולם בשוה וזהו דוקא לענין הארת המקיף עליהם מלמעלה בבחי' סובב ממש כו', אבל מ\"ש את<sup data-n=\"1104\">17</sup> השמים ואת הארץ אני מלא בשוה הרי מאיר בחי' סובב למטה כמו למעלה אדרבה למטה הוא יותר בגילוי מלמעלה וא\"ז בשוה מטעם הנ\"ל. אמנם אין זה רק מצד בחי' ממלא שם בחי' היש דגשמיות נק' יש גמור יותר מבחי' יש דחכ' כו' אבל מצד בחי' סובב עצמו שאין שם בחי' מעלה ומטה ורוחני' וגשמיות שוין ממש כמ\"ש קמי' כחשיכא כאורה כידוע ממשל העיגול כו' א\"כ הרי גם בענין בחי' היש אין הפרש בין בחי' רוחני' היש דחכ' לגשמיות היש דדצ\"ח כו' על שניהם מאיר בשוה דוקא, וזהו שא' בע\"ח דאור מקיף הכללי מקיף לד' עולמות בשוה ממש, אבל מה שמקיף זה עצמו מאיר ונמשך בבחי' ממלא לעשות לכל עלול בחי' יש כנ\"ל, בזה יש הפרש מצד בחי' ירידות המדרי' דבחי' ממלא שבבחי' יש גמור דדצ\"ח מאיר מבחי' סובב יותר ואין זה בשוה מטעם הנ\"ל וד\"ל).\n<b>ואחר</b> כל הנ\"ל בביאור בחי' סובב וממלא כו' יש להבין בשורש ענין המצות מעשיות אשר בקש משה ליכנס לא\"י גם להיות הדיוט כנ\"ל, והוא לפי שהמצות מעשיות מתלבשות בעשי' דדצ\"ח ובחי' התהוות הגשמי' ליש גמור שרשו מבחי' סובב בחי' אין האמיתי כנ\"ל באריכות ע\"כ בעשות האדם איזה מצוה המלובשת בדבר גשמי שבו שורה בחי' פנימי' רצוה\"ע מבחי' פנימי' הכתר ה\"ז בחי' גילוי סובב בממלא ממש, כי הגם שבכל בחי' התהוות גשמי' יש הארת אין כנ\"ל, אבל הוא בהעלם ולא בהתגלות ממש אך ע\"י המעשה של המצוה להיותה בחי' פנימי' רצוה\"ע ונעוץ תחב\"ס דוקא כי בסוף מעשה בה נגלה בחי' אין דסובב בגילוי גמור למטה (רק שמלובש האור במצוה זו וטמון בה כמו<sup data-n=\"1105\">18</sup> שמניחין אבן טוב וגונזין אותו בתיבה הנק' מתן בסתר ולע\"ל יתגלה האור הזה למטה ממש כמו שהוא למעלה כמשי\"ת), וזהו למעלה גם ממדרי' שורש משה שהוא רק בפנימי' החכ' כו' ע\"כ בקש משה לקיים המצות בא\"י אף שיהי' כהדיוט רק בבחי' נפש דעשי' כו' שהוא רק בחי' המעשה בלבד ודוקא בא\"י שמצות התלוי' בארץ כמו תרומות ומעשרות הרי בזה נגלה בחי' אין דסובב בחלק הצומח הגשמי שבארץ וכן במצות הקרבנות במזבח שהוא בחי' החי הרי מקריבי' החלב והדם שהוא בחי' ההגשמה של החיות הרוחני' דנה\"ב שבזה יתרון מעלה משורש ומקור הנה\"ב שהוא בחי' פני שור כו' מטעם הנ\"ל דבחי' סובב בממלא דדצ\"ח הגשמי' שם יש גילוי אור דסובב יותר מבראשית ההשתל' כו' וד\"ל.",[["1104","17","<b>את השמים ואת הארץ אני מלא</b>: ירמי' כג, כד."],["1105","18","<b>כמו שמניחין אבן טוב . . בתיבה הנק' מתן בסתר</b>: ראה סה\"מ תקס\"ב ח\"א ע' שפג. סידור עם דא\"ח קסו, ב. מאמרי אדהאמ\"צ שמות ח\"א ע' ס. ויקרא ח\"א ע' נה. נ\"ך ע' מ. ובמ\"מ שם."]]],[2101920216,"<b>ובזה</b> יובן מ\"ש בכל הקרבנות ריח<sup data-n=\"1106\">19</sup> ניחוח לה' שהוא בחי' המשכת תוס' אור התענוג בשם הוי' בחי' סובב בכלל כו', ולכאורה הרי הקרבת דם הקרבן דדם הוא הנפש הבהמה אינה עולה רק לשרשו בבחי' פני שור שמקבל רק מבחי' ממלא בלבד כו', אך הענין הוא דע\"י הקרבת הדם הוא הנפש דבהמה אעפ\"י דמה שבא בשינוי המהות הוא מבחי' אין כנ\"ל, אבל אינו מאיר בו רק בהעלם כמו בשאר דברים הגשמי' אך ע\"י הקרבת הדם<sup data-n=\"1107\">20</sup> נמשך אח\"כ מבחי' התענוג העליון להיות לריח ניחוח להוי' בחי' סובב בתוס' אור דוקא לפי שבחי' החלב הוא בחי' התענוג כמו חלב<sup data-n=\"1108\">21</sup> ודשן תשבע נפשי כו' וע\"כ גידול גשמי' של האברים הוא ע\"י חלב דוקא והוא יותר גשמי מן הדם<sup data-n=\"1109\">22</sup> הוא הנפש שהוא בחי' רוחני יותר כו', וע\"כ בהקטרת החלב דוקא נא' ריח ניחוח להוי' בבחי' תוס' אור התענוג בבחי' סובב כמ\"ש כל<sup data-n=\"1110\">23</sup> חלב לה' כו' מטעם הנ\"ל דכל שבא בהגשמה למטה יותר יותר יש בו מהארת אין כו' ודוקא ע\"י מעשה המצוה כמו מצות הקרבת הקרבן מטעם שיש בו בחי' פנימי' רצון העליון מטעם הנ\"ל וד\"ל.\n<b>והנה</b> אעפ\"י שמבואר למעלה דבכל בחי' עילה ועלול יש בחי' גילוי אין דסובב עד מדריגה היותר תחתונה כו' אין זה רק בהעלם וצמצום גדול, וגם במצות מעשיות המלובשי' בדברי' גשמי' אין הגילוי רק בבחי' הלבשה כמו דבר מה הנטמן בתיבה סגורה וחתומה (הנק' מתן בסתר) לכך כל המשכת אורות עליוני' שע\"י מ\"ע בדברי' גשמי' דנוגה ה\"ז בבחי' הסתר בהם כמ\"ש אתה<sup data-n=\"1111\">24</sup> אל מסתתר כו' אבל לע\"ל כתי' ונגלה<sup data-n=\"1112\">25</sup> כבוד הוי' כי עין<sup data-n=\"1113\">26</sup> בעין יראו כו' ולא<sup data-n=\"1114\">27</sup> יכנף עוד מוריך כו' דהיינו שלא יתלבש ויסתיר אור דסובב בממלא כעכשיו אלא יתגלה כמו שהוא ממש למעלה ולמטה שוין ממש (והיינו כמו שמבואר למעלה שזהו מצד בחי' סובב עצמו כמו שהוא טרם שמלובש ומאיר בממלא כו' אבל מצד בחי' סובב שבממלא יש בחי' מעלה ומטה בב' אופנים שונים והפכים דבבחי' הרוחני' הרי האור הולך ומתצמצם בעו\"ע ומצד בחי' הגשמי' למטה יש יותר גילוי האין כו' וד\"ל). וזהו שארז\"ל היום לעשותם ולמחר<sup data-n=\"1115\">28</sup> לקבל שכרם דהיינו לימוהמ\"ש שיקבלו שכרם ממעשה המצות דוקא שיתגלה בחי' סובב למטה כמו למעלה ממש, והיינו שא' צדיקים<sup data-n=\"1116\">29</sup> יושבים ועטרותיהם בראשיהם כו' בחי' עטרה זאת היינו בחי' גילוי דסובב הכללי על כאו\"א ממעשה המצות שעשה בעוה\"ז והמשיך מבחי' סובב בדברי' גשמי' דוקא כנ\"ל, וידוע דיש הפרש בין ימוהמ\"ש לעוה\"ב, דבימות המשיח יהי' עדיין גופי' חומרי' כמו עכשיו משא\"כ אחר תחיה\"מ שאין בו אכילה ושתי' כו' ואז יקומו כל נשמות הצדיקים בגופי' שלהם בתכלית",[["1106","19","<b>ריח ניחוח לה'</b>: ויקרא א, יג. ועוד."],["1107","20","<b>הדם</b>: בכת\"י ב: החלב."],["1108","21","<b>חלב ודשן תשבע נפשי</b>: תהלים סג, ו."],["1109","22","<b>הדם הוא הנפש</b>: פ' ראה יב, כג."],["1110","23","<b>כל חלב לה'</b>: ויקרא ג, טז."],["1111","24","<b>אתה אל מסתתר</b>: ישעי' מה, טו."],["1112","25","<b>ונגלה כבוד הוי'</b>: שם מ, ה."],["1113","26","<b>עין בעין יראו</b>: שם נב, ח."],["1114","27","<b>ולא יכנף עוד מוריך</b>: שם ל, כ."],["1115","28","<b>ולמחר לקבל שכרם</b>: עירובין כא, ב."],["1116","29","<b>צדיקים יושבים ועטרותיהם בראשיהם</b>: ברכות יז, א."]]],[2101920217,"הזדככות החומר כמ\"ש ועצמותיך<sup data-n=\"1117\">30</sup> יחליץ כו' מבחי' טלא<sup data-n=\"1118\">31</sup> דבדולחא כמ\"ש כי<sup data-n=\"1119\">32</sup> טל אורות כו' ואז האבות וגם האמהות וכל הנשים יקבלו כל חיות גופם ונפשם מזיווא<sup data-n=\"1120\">33</sup> עילאה כו' וד\"ל.\n<b>ובכ\"ז</b> יתורץ הקושי' הנ\"ל בענין מ\"ע שהז\"ג שנשים פטורות ושאהז\"ג חייבות דממ\"נ כו' כמ\"ש למעלה באריכות, להיות מבואר למעלה בענין המצות לע\"ל שהוא בחי' גילוי דסובב כמו שהוא למעלה בלי התלבשות בבחי' ממלא כו' וזהו ועטרותיהם בראשיהם שע\"י המצות שעשו בעוה\"ז נעשו להם עטרות בראשיהם מבחי' גילוי אור דסובב כמו שהוא למעלה דוקא ובזה שוין הנשים עם האנשים זכרים עם נקבות דבבחי' עטרה זו אין בה הפרש בין זכר לנקבה כלל משום דבבחי' סובב עצמו כמו שהוא ה\"ה למעלה לגמרי מבחי' התחלקות ומבחי' מעלה ומטה עד שא' כחשכה<sup data-n=\"1121\">34</sup> כאורה כו' ומקור האצי' עם סוף העשי' שוין כנ\"ל דבחי' יש דחכ' דראשית הגילוי עם סוף העשי' בחי' יש גמור שוין ממש כו', וא\"כ א\"א לומר כלל בחי' הפרש שבין זכר לנקבה כידוע דזכר ונקבה הוא בחי' משפיע ומקבל עו\"ע והוא בחי' מ\"ה וב\"ן, ומ\"ש והוא<sup data-n=\"1122\">35</sup> ימשול בך שהנוק' נכללת בדכורא או א\"ח עט\"ב כו' כ\"ז לא שייך רק בבחי' הארת סובב בממלא בלבד שבא האור לכלל בחי' שפע עכ\"פ אז שייך בזה ענין זכר ונקבה משפיע ומקבל כו' ועליית המקבל למעלה מן המשפיע כמו לע\"ל דכתי' א\"ח כו', אבל מצד בחי' עצמות דסובב כמו שהוא ממש הרי עדיין לא בא לכלל בחי' שפע כלל ואין לומר שם התחלקות מדרי' דמשפיע ומקבל כלל כי הוא בעצמו עדיין בבחי' אחדות פשוטה ממש וע\"כ זכרים ונקבות שוין בענין עטרותיהם בראשיהם לפי שאז יהי' בחי' התגלות דסובב כמו שהוא ע\"כ לא שייך לומר שהנקבות יוצאות י\"ח במ\"ע דבעליהן מפני שנכללת בהם מאחר שאין שם התחלקות כלל וכלל בין זכרים לנקבות כו', ודוגמא לדבר כמו האמהות שקיימו ג\"כ המצות כמו האבות, הרי לא יהי' הפרש כלל בין עטרות שע\"ג האבות לעטרות שע\"ג האמהות לע\"ל באלף הז' שיהי' התגלות הסובב כמו שהוא וד\"ל.\n<b>וזהו</b> עצמו ההפרש עכשיו בין מ\"ע שהז\"ג למ\"ע שאהז\"ג, דמ\"ע שהז\"ג שרשם בבחי' הארת סובב בממלא בחי' משפיע ומקבל שהמקבל נכלל במשפיע כו' כידוע, וע\"כ מ\"ע שהז\"ג נשים פטורות מפני שנכללות בבעליהן כמ\"ש והוא ימשל בך, אבל שורש מ\"ע שאהז\"ג הוא בבחי' סובב מצד עצמו כמו שהוא שאין שם התחלקות כלל בין זכרים לנקבות ע\"כ אינם יוצאי' כלל ע\"י בעליהן כי במ\"ע",[["1117","30","<b>ועצמותיך יחליץ</b>: ישעי' נח, יא."],["1118","31","<b>טלא דבדולחא</b>: ראה זח\"א רכה, ב. זח\"ג מט, א. ועוד."],["1119","32","<b>כי טל אורות</b>: ישעי' כו, יט."],["1120","33","<b>מזיווא עילאה</b>: ראה זח\"ב רד, ב. רי, א. רכט, ב. זח\"ג כה, א. וראה גם סידור שחרית מא, ב. מאמרי אדהאמ\"צ נ\"ך ע' תסה."],["1121","34","<b>כחשכה כאורה</b>: תהלים קלט, יב."],["1122","35","<b>והוא ימשול בך</b>: בראשית ג, טז."]]],[2101920218,"שאהז\"ג זו\"נ שוין ממש מטעם הנ\"ל לע\"ל בענין ועטרותיהם בראשיהם, רק אז יהי' בחי' סובב כמו שהוא בגילוי ועכשיו הוא בהעלם כמתן בסתר כו' וד\"ל.\n<b>ומעתה</b> לא יקשה ממ\"נ כו', דבודאי יש שרש לנשים בלמעלה מהזמן אמנם בזה השרש הן שוין עם האנשים ממש וע\"כ חייבות במ\"ע שאזה\"ג כמו האנשים ממש, ולא תוכל האשה לצאת ע\"י בעלה כי שם לא נק' אשה בחי' מקבל ולא אישה נק' בעלה והיא אינה אשתו כו' אלא כמו ב' זכרים שאין א' פוטר חבירו כו' וד\"ל.\n<b>ועתה</b> יש לתרץ הקושי' הב' והג' דלעיל עמ\"ש בלק\"ת בטעם מ\"ע שהז\"ג שהוא בבחי' מל' שמלבשת רק להחזה דז\"א ושאהז\"ג שרשה למעלה מהחזה כו' הלא מצד המצות הרי ה\"ח דמ\"ע הן בבחי' הדעת דז\"א ומהו ההפרש בין שהז\"ג לשאהז\"ג כו' ע\"ש. הנה תחלה יש להקדים ביאור ענין הנ\"ל מה שהמל' מלבשת עד החזה כו' דהנה פי' הלבשה זו הוא בבחי' החיצוני' דהיינו שרק חיצוני' דחיצוניות המדות מתלבשים בדיבור, וכמו שאנו רואים בחוש שא\"א להביא בדיבור בחי' פנימי' המדות שהרי האהבה כמו שהיא בעצם ממש א\"א שיבא בדיבור, וכמו\"כ השכל כמו שהוא בבחי' תמציתו אינו יכול לגלותו כלל בדבור, וכן הרצון כמו שהוא במהותו ממש א\"א לגלותו בדיבור, וכן הטעם והתענוג כמו שהוא ממש בעצם א\"א שיבוא בדיבור כמו תענוג שיש לו בדבר מה אם בשכל או בענין תאוה גשמי' אי אפשר לו להסביר כלל וכלל בדיבור איך שהתענוג הוא בעצם אצלו ממש גם כי ירבה דברים בזה, ואפי' טעם גשמי שטועם במאכל או פרי א\"א לו להסביר בדיבור כלל איך שהטעם אצלו במתיקות גם שיפרש לו הדבר היטב ענין המתיקות אעפי\"כ גופה של מהות המתיקות שנמתק לחכו איך יבין אותה לזולתה עד שבהכרח לאמר לו לא תוכל להבין אותי מן הדבור עד שתטעום בעצמך אזי תעמוד על מהותך כו', וכן בטעם החמיצות גם שיפרש ויבינו לזולתו א\"א שיעמוד זולתו על מהות טעם החמיצות כ\"א כאשר יטעום אותה בעצמו, ומכ\"ש פרטי אופנים הטעמים במתיקות וחמיצות בכל פרטי הרכבותיו כמו מיני מעדנים שונים שזה א\"א לגלות כלל בדיבור, וגם שיוכל להזכיר בדיבור כל פרטי מיני מעדנים וטעמים שונים כמו זה הפרי מורכב בטעם החמיצות כך וכך ומתיקות כך וכך וכן לכל פרי ומאכל כו', אין זה רק קריאת שם בלבד שקורא בדיבור זה חמוץ וזה מתוק בכלל או בפרט במורכבים שבהם בחמיצות או מתיקות ועריבות או חריפות ומרירות ומליחות כו' אבל גם להביאם במושכל והבנה א\"א לו להסביר לזולתו עד שהשכל ישיג שהוא חמוץ כו' אלא רק בקריאות שם בלבד, וזהו רק בחי' אותיות הדבור שקורא שמות בלבד ובקריאה חיצוני' שאין זה נוגע כלל למהות הדברים שקוראים כי לא יוכל להשיג גם בשכל והבנה למהות הדברי' שקוראי' בשמו עד שלא נודע רק השם, וכמו ויקרא<sup data-n=\"1123\">36</sup> האדם שמות לכל הבהמה כו' זה יקרא ארי' וזה שור, שאין השמות הללו מודיעי' למהות הארי' והשור כלל כו' וד\"ל.",[["1123","36","<b>ויקרא האדם שמות</b>: שם ב, כ."]]],[2101920219,"<b>וכך</b> יובן בכלל בחי' קריאות אותיות הדבור גם שהוא מגלה מדות ושכל ורצון ותענוג כו' א\"א שיתגלה מבחי' מהותן כלל בדיבור גם לא במושכל כו' רק בחי' קריאות שמות כי האהבה בדיבור לא יובן לזולתו מהותה כלל רק קריאת שמה שנק' אה' באמרו יש לי אהבה, אבל לא מהותה כלל (וגם כשאור אהבתו יוצא בדיבור כמו ממעמקים<sup data-n=\"1124\">37</sup> קראתיך כו' עד שנכנסי' ללב כו' אין זה רק בקיעה בעלמא כמ\"ש במ\"א וד\"ל), וזהו\"ע מ\"ש דהמל' מלבשת עד החזה כו' שהוא בחי' הדבור העליון שמלביש לחיצוני' המדות דז\"א בלבד ולא לבחי' פנימי' מהותן כלל, וכך הוא במוחי' ותענוג ורצון עליון שאין בחי' פנימי' מהותן נודע בדבור רק בחי' קריאת שמות בלבד כנ\"ל וד\"ל.\n<b>ומעתה</b> יתורץ הקושי' הנ\"ל בענין מ\"ע שהז\"ג כו' דהנה ידוע שהמצות הוא בחי' פנימי' הרצוה\"ע ובחי' פנימי' רצון העליון לא נודע כלל בדיבור שהוא המל' רק בבחי' קריאת שמות כנ\"ל והוא במה שהמל' מלבשת לחזה בחי' חיצוני' המדות כו', אמנם יש הפרש בזה בין מ\"ע שהז\"ג לשאין הזמן גרמא, שמ\"ע שאהז\"ג הוא בבחי' פנימי' המדות דז\"א שלמעלה מהזמן דמל' וממילא הרי הוא בבחי' פנימי' החכ' ופנימי' הרצון עד בחי' סובב הכללי מצד עצמות שאין שם הפרש בין זו\"נ ע\"כ אין יוצאת בבעליהן, והגם שמ\"ע שרשן רק ה\"ח דדעת דז\"א מ\"מ שרשן הראשון הוא בבחי' פנימי' רצוה\"ע בחי' ארחין<sup data-n=\"1125\">38</sup> דגלגלתא כו' משא\"כ מ\"ע שהז\"ג שנמשך רצוה\"ע בזמן דמל' דוקא שהוא בחי' הדיבור שמלבשת רק להחזה כו' שם בחי' הנוק' טפל לזכר ויוצאות י\"ח בבעליהן אעפ\"י שהמצוה מצ\"ע היא בבחי' פנימי' הרצון ששם אין הפרש בין זכר לנקבה כו' וד\"ל.\n<b>אך</b> זהו עכשיו דוקא שיש הפרש בין למעלה מהזמן ובין זמן ע\"כ ממילא יש הפרש בין שהז\"ג לשאין הז\"ג בנשים אבל לע\"ל שיהי' בחי' סובב עצמו למטה כמו למעלה ממש אז אין אין הפרש בין זמן לגבי למעלה מהזמן (וראי' ממה שגם הזמן יהי' נצחי כמ\"ש<sup data-n=\"1126\">39</sup> בענין ועד בחילופי אתוון כו') וא\"כ גם מ\"ע שהזמן גרמא נשים חייבות אז כמו שאהז\"ג. אך ענין עטרותיהן בראשיהן לע\"ל שאינם רק ע\"י המצות מעשיות שעשו בעוה\"ז הרי לא יהי' כלל עטרות לנשים ממ\"ע שהז\"ג שהי' פטורות בעוה\"ז משום שהיו נכללות עכשיו בבעליהן, ואפשר שגם מהם יהי' להם עטרות משום שאז שוין הנשים עם האנשים ואין נכללות בעטרה א' עם בעליהן וכמו האמהות יהי' להם עטרות גם ממ\"ע שהז\"ג כמו האבות ממש מאחר שאז הוא למעלה מבחי' זמן, וזמן ולמעלה מהזמן שוין ממש וד\"ל.",[["1124","37","<b>ממעמקים קראתיך</b>: תהלים קל, א."],["1125","38","<b>ארחין דגלגלתא</b>: ראה זח\"ג קכט, א. קלו, א."],["1126","39","<b>כמ\"ש בענין ועד בחילופי אתוון</b>: ראה ס' מאמרי אדהאמ\"צ דברים ח\"א ע' רכד ואילך. וש\"נ."]]],[2101920220,"<h3>להבין מפני מה נאמר ביצירת חיות</h3>\n<b>אור ליום ו' עש\"ק</b>\n<b>להבין</b><sup data-n=\"1127\">1</sup> מפני מה נאמר ביצירת חיות ובהמות כו' תוצא<sup data-n=\"1128\">2</sup> הארץ נפש חיה כו' ומזה המאמר נתבאר כולם<sup data-n=\"1129\">3</sup> בצביונם ובקומתם כו' הגוף שלהם עם החיות שלהם, משא\"כ ביצירת אדם נאמר וייצר<sup data-n=\"1130\">4</sup> הוי' אלקים את האדם עפר מן האדמה ויפח באפיו כו' וכמבואר<sup data-n=\"1131\">5</sup> במ\"ב שלקח העפר ממקום כפרתו ממזבח כו' שעה ראשונה<sup data-n=\"1132\">6</sup> הוצבר עפרו כו' שני' נעשה גולם כו', שהרי הגוף של האדם נמוך במדרגה מגופים שלהם שהגופים שלהם הוא ממאמר תוצא כו' וגופו של האדם הוא מבחי' העפר, אך נשמתו הוא למעלה מעלה וכמ\"ש ויפח כו', וע\"כ נאמר אחור<sup data-n=\"1133\">7</sup> וקדם צרתני אחור למע\"ב מצד הגוף וקדם למע\"ב מצד הנשמה כנ\"ל, והטעם לזה הוא שד'<sup data-n=\"1134\">8</sup> יסודות ארמ\"ע הם כנגד ד' אותיות הוי' ב\"ה ה\"א תתאה דומם כו' יו\"ד כנגד מדבר כו'.\n<b>והנה</b> יצירת החיות ובהמות ממאמר תוצא כו' הי' בבת אחת הגוף שלהם שהוא בחי' צומח מאות וי\"ו משם הוי' שהוא כנגד צומח שיש בה בחי' קטנות וגדלות וכמו שיש באילנות גדולים וקטנים כמ\"כ יש בחיות ג\"כ גופים גדולים וקטנים כידוע והם מבחי' צומח כנ\"ל, והחיות שלהם נק' בחי' חי' כנגד אות ה\"א עילאה משם הוי', משא\"כ גוף האדם שנברא מעפר האדמה שהם דומם כנגד אות ה' תתאה ע\"ז נתלבש בו נשמה מבחי' מדבר אות יו\"ד וגם למעלה מעלה מבחי' קוצש\"י כו' ונק' מדבר מלשון ידבר<sup data-n=\"1135\">9</sup> שהאדם מלך על כולם.\n<b>והנה</b> תכלית בריאת העולמות היא ירידה צורך עלי' וע\"י האדם הם מתעלים ומתייחדין למקורן ושרשן כו' ע\"י מה שהאדם אוכל מלובש כו', והנה עד\"מ<sup data-n=\"1136\">10</sup> כשצריך להגביה איזה בנין מהצורך להניח עץ ארוך מלמטה דוקא תחת",[["1127","1","<b>להבין מפני מה</b>: נדפס בשינויים בתו\"א ג, ד. ובס' מאמרי אדה\"ז עה\"ת ח\"א ע' טו. ובארוכה בתו\"ח בראשית יח, ד. ועם הגהות באוה\"ת בראשית כרך ו' תתרנא, א. וראה גם ס' עבודת הלוי בראשית ב, א. וראה עוד בהמ\"מ בסו\"ס תו\"א שם."],["1128","2","<b>תוצא הארץ נפש חיה</b>: בראשית א, כד."],["1129","3","<b>כולם בצביונם ובקומתם</b>: ראה ר\"ה יא, א. חולין ס, ב."],["1130","4","<b>וייצר הוי' אלקים את האדם</b>: בראשית ב, ז."],["1131","5","<b>וכמבואר במ\"ב שלקח העפר ממקום כפרתו</b>: [כ\"ה בכת\"י המעתיק. וניכר שצ\"ל: במ\"ר במדרש רבה]. ראה ב\"ר פי\"ד , ח. ירושלמי נזיר פ\"ז ה\"ב. פירש\"י בראשית ב, ז. רמב\"ם הל' ביהב\"ח פ\"ב ה\"ב."],["1132","6","<b>שעה ראשונה הוצבר עפרו</b>: ראה סנהדרין לח, ב."],["1133","7","<b>אחור וקדם צרתני אחור למע\"ב</b>: תהלים קלט, ה. ראה ב\"ר פ\"ח, א. תנחומא (באבער) תזריע ב. ובכ\"מ. וראה דרך חיים לאדהאמ\"צ פט, ג."],["1134","8","<b>שד' יסודות ארמ\"ע הם כנגד ד' אותיות</b>: ראה ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א. לקו\"ת להאריז\"ל בראשית ט, א. ובכ\"מ."],["1135","9","<b>ידבר</b>: תהלים מז, ד."],["1136","10","<b>עד\"מ כשצריך להגביה איזה בנין</b>: ראה גם (בנוסף למקומות שנסמנו לעיל בתחילת המאמר): לקו\"ת חוקת סה, ג. אוה\"ת ענינים ע' שכו (בשם הה\"מ). ובכ\"מ."]]],[2101920221,"הבנין ואזי נגבה ממילא כל הבנין משא\"כ כשהי' נותנים באמצע הבנין לא הי' נגבה כ\"א החלק למטה וזה החלק הי' נשאר במקומו הראשון, וככה ממש יובן בנמשל העליון שרצונו ית' שע\"י האדם יהי' עליי' לכל הברואים ע\"כ נלקח גופו מבחי' הדומם דוקא מדרגה התחתונה מכל הברואים כו' ונק'<sup data-n=\"1137\">11</sup> יציר כפיו של הקב\"ה נברא מהעפר כו' ונעשה גולם ולא הי' בחי' קטנות וגדלות כלל כמו בבחי' צומח כו' רק עתה יש בגופו של האדם בחי' צומח כ\"כ קטנות וגדלות משא\"כ אדה\"ר שנברא מן העפר כו' בקומתו כו' מסוף העולם כו'<sup data-n=\"1138\">12</sup> וגם נזרקה בו נשמה ממדרגה עליונה מבחי' עצמותו וכמ\"ש ויפח<sup data-n=\"1139\">*12</sup> באפיו כו' בחי' כי נעוץ<sup data-n=\"1140\">13</sup> תחלתן בסופן, ולכן נאמר בבריאות האדם דוקא וייצר ה' אלקים בב' שמות כי להיות התחברות גופו עם נפשו שהם רחוקים מאד בערך זה מזה יותר מריחוק הגוף מהנפש של בע\"ח שהם צומח וחי שסמוכים זה לזה ומתחברים יחד משא\"כ הדומם עם המדבר שרחוקים מאוד לזאת להיות התחברותם יחד הוא ע\"י ב' שמות הנ\"ל.\n<b>ויובן</b> כ\"ז גם עפ\"י הקבלה דכתיב בחכמה<sup data-n=\"1141\">14</sup> יסד ארץ כונן שמים בתבונה, וענין שמים וארץ הם רוחניות וגשמיות ולמעלה היינו בחי' המדות שהם ז\"א דאצי' נק' שמים והם בחי' צומח כנודע שהמדות יש בהם גידול כו' ומל' נק' ארץ שהוא בחי' דומם ושמים הוא כונן בתבונה דוקא שהוא בחי' בינה והיינו ה' עילאה דשם הוי' שהא מקור לאות ו' והם צומח וחי, ולכן הבע\"ח גופם בחי' צומח אבל הארץ שהיא הדומם היא ייסד בחכמה דוקא בחי' מדבר ולכן גוף האדם הי' דומם כדכתיב גלמי<sup data-n=\"1142\">15</sup> ראו עיניך כו'.",[["1137","11","<b>ונק' יציר כפיו של הקב\"ה</b>: ראה ב\"ר פכ\"ד, ה. ובכ\"מ."],["1138","12","<b>מסוף העולם כו'</b>: חגיגה יב, א."],["1139","*12","<b>ויפח באפיו</b>: בראשית ב, ז."],["1140","13","<b>נעוץ תחלתן בסופן</b>: ס' יצירה פ\"א מ\"ז."],["1141","14","<b>בחכמה יסד ארץ</b>: משלי ג, יט."],["1142","15","<b>גלמי ראו עיניך</b>: תהלים קלט, טז."]]],[2101920222,"<h3>ענין יתרו</h3>\n<b>מוש\"ק פ' יתרו</b>\n<b>ענין</b><sup data-n=\"1143\">1</sup> יתרו<sup data-n=\"1144\">2</sup> שיתר פרשה א' בתורה ואתה תחזה כו' ושפטו את העם, הענין כי הנה כהן<sup data-n=\"1145\">3</sup> מדין הוא הי' מבחי' חכמה דקליפה שנקרא בשם מדין וכמ\"ש<sup data-n=\"1146\">4</sup> בזהר רזא דתרין ווין כהן מדין הוא חו\"ב דקליפה וכהן<sup data-n=\"1147\">5</sup> און יסוד דקליפה, כי זלע\"ז<sup data-n=\"1148\">6</sup> עשה האלקים, ופי' לעומת זה היינו לנגד ממש כי הם ההיפוך במהותם ממהו' הקדושה מלבד שהם טמאים, והיינו כי חו\"ב<sup data-n=\"1149\">7</sup> דקדושה הם תרין ריעין ולעומת זה בקליפה חו\"ב נק'<sup data-n=\"1150\">8</sup> מדין מל' ריב ומדון כלומ' פירוד כו' וכן כהן און כי<sup data-n=\"1151\">9</sup> יסוד דקדושה נק' ששון שהוא תכלי' השמחה ע\"ש גמר השפע ולעומת זה יסוד דקליפה נק' און מל' צער כמו מצאתי<sup data-n=\"1152\">10</sup> און לי כו', וכנודע ג\"כ ממ\"ש בזהר<sup data-n=\"1153\">11</sup> שיתרו היה מג' יועצי פרעה איוב<sup data-n=\"1154\">12</sup> ששתק כו', בלעם בחי' דעת כמ\"ש ויודע<sup data-n=\"1155\">13</sup> דעת עליון ויתרו בחי' חכמה, וכשאמר יתרו עתה<sup data-n=\"1156\">14</sup> ידעתי כי גדול ה' כו' הוא ענין בירור והתכללו' חכמה דקליפה בחכמה דקדושה, וזה הי' הסיבה למ\"ת שהוא רק ענין המשכת החכמה למטה, כי למעלה כבר היתה התורה גנוזה שהיא חכמה עילא', אלא שלהיות נמשכת למטה להתלבש בענינים גשמיים שזהו פי' וענין מ\"ת וכמו ענין פ' משפטים שהוסיף יתרו שהדין מחכמה עילאה נשפל בדינים שהוא המשפט בין איש לרעהו ובהכרח שא' מהם משקר כי אלולי הי' שניהם מגידי' האמת לא היו נצרכים לדין, ושיהי' החכמה נמשכת כ\"כ למטה הוא ע\"י יתרו התכללו' חכמה דקליפה בחכמה דקדושה כו', וזה הי' כל ענין המעשה בהנהגת משה ואהרן וכל זקני ישראל עם יתרו.\n<b>הנה</b> כתי' ויצא<sup data-n=\"1157\">15</sup> משה לקראת חותנו כי<sup data-n=\"1158\">16</sup> משה הוא בחי' חכמה דקדוש' ויצא לקראת העלא' החכמה דקליפה להיות מתכללת בו בקדושה, וזהו",[["1143","1","<b>ענין יתרו</b>: נמצא בגוכי\"ק הצ\"צ בס' תקע\"ב [1116 כז, ב]. ונמצא גם בס' מאמרי אדה\"ז עה\"ת ח\"א ע' ש."],["1144","2","<b>יתרו שיתר פרשה א' בתורה ואתה תחזה</b>: יתרו יח, כא-כב. שמו\"ר פכ\"ז, ח. ראה גם אוה\"ת יתרו ע' תשכא."],["1145","3","<b>כהן מדין הוא הי' מבחי' חכמה דקליפה</b>: ראה מאו\"א מע' מ, יג. לקו\"ת וס' הליקוטים להאריז\"ל ר\"פ יתרו."],["1146","4","<b>וכמ\"ש בזהר רזא דתרין ווין</b>: ראה זח\"ב סח, א."],["1147","5","<b>וכהן און יסוד דקליפה</b>: ראה ג\"כ ביאוה\"ז לכ\"ק אדהצ\"צ ח\"א ע' רג."],["1148","6","<b>זלע\"ז עשה האלקים</b>: קהלת ז, יד."],["1149","7","<b>חו\"ב דקדושה הם תרין ריעין</b>: ראה זח\"ג ד, א. וראה אוה\"ת נצבים ע' א'רכב. ביאוה\"ז לכ\"ק אדהצ\"צ ח\"ב ע' תקפא."],["1150","8","<b>נק' מדין מל' ריב ומדון</b>: ראה זח\"ב שם. וראה לקו\"ת וס' הליקוטים להאריז\"ל ר\"פ יתרו. רמ\"ז ומק\"מ לזח\"ב שם."],["1151","9","<b>כי יסוד דקדושה נק' ששון</b>: ראה זח\"ג ריב, ב (ובאור החמה שם)."],["1152","10","<b>מצאתי און לי</b>: הושע יב, ט. וראה מגלה עמוקות אופן קמ."],["1153","11","<b>בזהר שיתרו היה מג' יועצי פרעה</b>: ראה זח\"ב סט, א."],["1154","12","<b>איוב ששתק כו'</b>: סוטה יא, א."],["1155","13","<b>ויודע דעת עליון</b>: בלק כד, טז. וראה ע\"ח שער הארת המוחין (של\"ב) פ\"ב."],["1156","14","<b>עתה ידעתי</b>: יתרו יח, יא."],["1157","15","<b>ויצא משה לקראת חותנו</b>: יתרו יח, ז."],["1158","16","<b>כי משה הוא בחי' חכמה דקדוש'</b>: ראה אוה\"ת יתרו ע' תשכא שמוסיף: וכמ\"ש וירא ראשית לו. וראה בהמובא בלקו\"ש ח\"ו ע' 244 ואילך."]]],[2101920223,"וישתחוו<sup data-n=\"1159\">17</sup> איש אל אחיו שבהשתחוואה זו דמשה העלה את יתרו כו' ואח\"כ וישב<sup data-n=\"1160\">18</sup> אהרן וכל זקני ישראל לאכל לחם עם חותן משה כו' כי כולם הי' צריכים למלאכת עבודה עמו עד שיהי' נגמרת העלאותו והתכללותו בקדושה כו' ואחר אשר נגמרה בכי טוב אזי ניתנה התורה לישראל.\n<b>שיש</b><sup data-n=\"1161\">19</sup> יתרון<sup data-n=\"1162\">20</sup> לחכמה כו' זהו יתרו ע\"י סכלות נעשה יתרון ע'<sup data-n=\"1163\">21</sup> זהר תזריע, וע'<sup data-n=\"1164\">22</sup> מ\"ש חכמות בחוץ עי\"ז תרונה וזהו ענין תורה ירידה צורך עלי' ע\"י הבירור, וכללו' הירידה במ\"ת הי' צ\"ל תחלה תוס' אור בח\"ע כמו ארוממך<sup data-n=\"1165\">23</sup> כי דלתני וכו', ותוס' זה זהו ענין יתרון האור הנ\"ל שנמשך מהסכלו' בירור דחב\"ד דקליפה, ומשה מ\"ה רק הארה ועמ\"ש<sup data-n=\"1166\">24</sup> על סעודת בר מצוה (בוך נייר גדול קרוב לסופו) בענין וילבש המן את מרדכי ע\"ש ופורי'<sup data-n=\"1167\">25</sup> תקע\"ב בהביאור, עו\"ש מדין סד\"ה<sup data-n=\"1168\">26</sup> עד לא הוו מתקלא (בוך הנ\"ל) ושם ג\"כ מענין כהן און (ובכי\"ה<sup data-n=\"1169\">27</sup>), ותשבע ותותר רות ב' יד מ\"ב ד' ואת ובנייכי תחיי בנותר אוה\"מ<sup data-n=\"1170\">28</sup> פ' וירא או חיי, ויתרון<sup data-n=\"1171\">29</sup> ארץ בכל היא זהר פ' חיי, בכל<sup data-n=\"1172\">30</sup> עצב יהי' מותר, ויחי<sup data-n=\"1173\">31</sup> יתר שאת, משלי<sup data-n=\"1174\">32</sup> י\"ב כ\"ו, וז\"ש<sup data-n=\"1175\">33</sup> יתרו ברוך כו'.\n<b>יתרון</b> האור מן החושך ע' זהר ח\"א ד' ועמ\"ש<sup data-n=\"1176\">34</sup> ויהי הענן והחשך וכו' והיינו ענין התהפכות המדות ומזה נמשך יתרון האור מאדך נק' אור וז\"ש",[["1159","17","<b>וישתחוו איש אל אחיו</b>: ע\"פ יתרו שם. מכילתא ופירש\"י שם."],["1160","18","<b>וישב אהרן וכל זקני ישראל</b>: ע\"פ יתרו יח, יב."],["1161","19","<b>שיש יתרון לחכמה</b>: ההגהות דלהלן נכתבו בגוכי\"ק הצ\"צ בצדדי הגליון, וכולם שייכים לד\"ה ענין יתרו הנ\"ל."],["1162","20","<b>יתרון לחכמה</b>: קהלת ב, יג."],["1163","21","<b>ע' זהר תזריע</b>: זח\"ג מז, ב."],["1164","22","<b>ועי' מ\"ש חכמות בחוץ עי\"ז תרונה</b>: ע\"פ משלי א, כ. ראה לעיל ע' יח וע' כ, ובהמ\"מ שם."],["1165","23","<b>ארוממך כי דלתני</b>: תהלים ל, ב."],["1166","24","<b>ועמ\"ש על סעודת בר מצוה . . בענין וילבש המן</b>: ע\"פ אסתר ו, י. וראה גם שערי אורה עד, ואילך. ראה אוה\"ת מג\"א ע' סח."],["1167","25","<b>ופורי' תקע\"ב בהביאור</b>: ביאור ד\"ה יביאו לבוש מלכות, נדפס לעיל בס' זה. וש\"נ."],["1168","26","<b>סד\"ה עד לא הוו מתקלא (בוך הנ\"ל)</b>: גוכי\"ק הצ\"צ מס' 1114 (קלז, א). (ולא נדפס עדיין). וראה גם לקו\"ת מטות פז, א: אך ענין מדין הוא מ\"ש בספרא דצניעותא (בזהר פ' תרומה קע\"ו ב') עד לא הוו מתקלא לא הוו משגיחין אפין באפין שהיו בחי' אב\"א וזהו בחי' תהו זה תחת זה כו' שלא היה שייכות לחסד עם גבורה שהחסד היה חסד שבחסד והגבורה היה גבורה שבגבורה כו'. וראה גם שערי אורה שם עא, ב. לעיל ע' סח."],["1169","27","<b>ובכי\"ה</b>: ראה תו\"ח שמות (החדש) ח\"ב רסט, א ואילך. [וכאן הכוונה להנחת הר\"מ בן אדה\"ז ממאמר ההוא — ראה בהוספות לתו\"ח שמות תסג, א טור ג]."],["1170","28","<b>אוה\"מ פ' וירא או חיי</b>: אור המאיר ................."],["1171","29","<b>ויתרון ארץ בכל היא זהר פ' חיי</b>: קהלת ה, ח. זח\"א קכב, א."],["1172","30","<b>בכל עצב יהיה מותר</b>: משלי יד, כג."],["1173","31","<b>ויחי יתר שאת</b>: מט, ג."],["1174","32","<b>משלי י\"ב כ\"ו</b>: ל' הפסוק שם: יתר מרעהו צדיק ודרך רשעים תתעם."],["1175","33","<b>וז\"ש יתרו ברוך</b>: יתרו יח, י."],["1176","34","<b>ועמ\"ש ויהי הענן והחושך</b>: ע\"פ בשלח יד, כ. סה\"מ תקס\"ח ע' קעא (וע\"ש בהמ\"מ)."]]],[2101920224,"שחורה<sup data-n=\"1177\">35</sup> אני ונאוה וראיתי<sup data-n=\"1178\">36</sup> אני שכמ\"כ בחכמ' ג\"כ יש יתרון ע\"י בירור חב\"ד דקליפה הגם עיקר<sup data-n=\"1179\">37</sup> השבירה בזמ\"ל מ\"מ ג\"כ בג\"ר פגם וע'<sup data-n=\"1180\">38</sup> בענין קיני קניזי קדמוני שיהי' לע\"ל משא\"כ עכשיו רק ז' עמי' וקיני<sup data-n=\"1181\">39</sup> יתרו קין ועמ\"ש<sup data-n=\"1182\">40</sup> שופטי' תקס\"ה ע\"פ ויתר גוי ינחלום.\n<b>הנה</b> חכ' דקלי' נק' מדין עיין<sup data-n=\"1183\">41</sup> סד\"ה ביום השמיני עצרת תק\"ע איך החכמ' גורם יש ובקטני' שלו', ויש סיבת המדון.\n<b>ב'</b> יתרונות היינו בשני יצריך נר נשמת אדם ומתכלל נה\"ב באור נה\"א מאדך זהו יתרון א' אור מהחושך אח\"כ ותורה אור שיהי' שכל נפש השכלי' מתכלל בחכמ' תורה זהו יתרון חכמ' מהסכלו' ע'<sup data-n=\"1184\">42</sup> ע\"פ המגביהי וכו'.",[["1177","35","<b>שחורה אני ונאוה</b>: שה\"ש א, ה. וראה לעיל ד\"ה ע\"פ זה."],["1178","36","<b>וראיתי אני</b>: קהלת ב, יג."],["1179","37","<b>עיקר השבירה בזמ\"ל</b>: בז' מלכין. ראה ע\"ח שער דרושי הנקודות (ש\"ח) פ\"ב."],["1180","38","<b>וע' בענין קיני קניזי קדמוני שיהי' לע\"ל</b>: ראה סה\"מ תקס\"ה ח\"ב ע' תשצח ואילך. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' א ואילך, ובהמ\"מ שם."],["1181","39","<b>וקיני יתרו קין</b>: ראה ס' מאמרי אדה\"ז הקצרים ע' מז."],["1182","40","<b>ועמ\"ש שופטי' תקס\"ה ע\"פ ויתר גוי ינחלום</b>: צפני ב, ט. סה\"מ תקס\"ה ע' תשצח (נוסח שני) שם."],["1183","41","<b>עיין סד\"ה ביום השמיני עצרת תק\"ע</b>: ראה סה\"מ תק\"ע ע' רצא. וש\"נ."],["1184","42","<b>ע' ע\"פ המגביהי וכו'</b>: ראה אוה\"ת חנוכה כרך ה' תתקלא, א ואילך."]]],[2101920225,"<h3>זהר תרומה ואתערו חברייא</h3>\n<b>(זהר</b><sup data-n=\"1185\">1</sup> תרומה קל\"ב ע\"א) ואתערו חברייא דהני אינון תיקוני דעלמא עילאה אל אדון א\"ל ברו\"ך תיקוני דעלמא תתאה כו' בגין דאית אתוון רברבין ואתוון זעירין, אתוון זעירין מההוא עלמא תתאה, אתוון רברבן מההוא עלמא דאתי כו'.",[["1185","1","<b>זהר כו' ואתערו חבריא</b>: נדפס כאן מתוך גוכי\"ק הצ\"צ, הנחה של מאמר אדה\"ז משנת תקע\"ב (כת\"י מס' 1116 לו, א).\nבביאוה\"ז להצ\"צ ח\"ב ע' תתב מביא ממאמר זה, וז\"ל: ענין ההפרש בין אלף בית שאומרים בחול ביוצר אור אל ברוך גדול דעה, ובין א\"ב דשבת שאומרים אל אדון על כל המעשים כו', דא\"ב דחול אין בכל אות רק תיבה א' משא\"כ בא\"ב דשבת יש בשני אותיות ראשונים א\"ב בכל א' ה' תיבין ואח\"כ ח\"י אותיות בכל א' ד' תיבין ואח\"כ ב' אותיות אחרונים ש\"ת בכל א' ששה תיבין, והענין נתבאר בזהר פ' תרומה דקל\"ב ע\"א כו' עד נק' אתוון זעירין. [ור\"ל להעתיק לשם את המאמר שלפנינו. וכן הועתק בתוך מאמר הביאוה\"ז בכת\"י 2028 אחר דף עח, ב]. וע\"ש עוד בביאוה\"ז.\nוראה גם לקו\"ת צו יז, ב: שאותיות המחשבה נק' אתוון רברבין לפי שבמחשבה משיג במעט זמן מה שצריך ע\"ז בדבור זמן רב, ועיין בזח\"ב תרומה דקל\"ב א' שלכך בשבת אומרים א\"ב אל אדון כו' שכל אות יש בו ד' או ה' תיבות כו' לפי שא\"ב זה הוא מבחי' אתוון רברבין כו' דהיינו מחשבה כו'. וראה עוד מענין אתוון רברבין ואתוון זעירין להלן סד\"ה סוד ויקרא אל משה, ובמ\"מ שם."]]],[2101920226,"<b>הענין</b> כי אותיות המחשבה נק' אתוון רברבין ואותיו' הדיבור נק' אתוון זעירין והטעם הוא כמו שאנו רואים עד\"מ ששכל א' כשיחשבנו האדם באותיו' מחשבתו יחשוב אותו במעט רגע וכשירצה לספר דברים בדיבור אזי יומשך זמן כמה הרבה יותר והיינו מפני שאותיו' המחשבה הם גדולים יותר בעצם מציאותן, ומה שמחזיק אות א' מאותיו' המחשבה יצטרכו ע\"ז מאותיו' הדיבור כמה וכמה אותיות כו' עד שלכך מה שיחשוב במחשבתו ברגע עם היות כי יהי' מעט אותיות מ\"מ להיות' גדולים יחזיקו את הכל משא\"כ בדיבור יצטרך ע\"ז זמן רב עד שיוציא אותיו' הרבה שאז הוא שיחזיקו אותו המושכל שמעט מאותיו' המחשבה מחזיקו כו'.\n<b>ונמצא</b> שאותיות המחשב' הם כלליים לגבי הדיבור, פי' כי הרי באמת האותיות הן הפרטים היותר אחרונים שהרי מאות א' לא יוכל להיות התהוות והולדת אות אחר כ\"א כל א' הוא חלק לבדנו וכמו שהוא נולד ממקורו כן נשאר בלי תוספת ומגרעת ובלי הולדה שאינו מוליד עוד אותיו' אחרים ולכן אינו אלא פרט אבל לא כלל שהרי אינו כולל שום דבר חוץ ממנו ואין בו אלא מה שהוא, אמנם זהו באותיו' הדיבור אבל באותיות המחשבה אינו כן אלא שהמה כלליים שאות א' מהם כולל כמה וכמה אותיו' מאותיות הדיבור כמובן ממשל הנ\"ל שמה שיחשוב במחשבתו במעט אותיו' יצטרך ע\"ז בדיבור ריבוי אותיות והיינו לפי שכל א' מאותיות המחשבה גדול מאד וכולל כמה מאותיו' הדבור ולכן נק' אותיות המחשבה אתוון רברבין ואותיו' הדבור נק' אתוון זעירין כו'."],[2101920227,"<h3>כתיב כי מחה אמחה</h3>\n<b>כתיב</b><sup data-n=\"1186\">1</sup> כי<sup data-n=\"1187\">2</sup> מחה אמחה את זכר עמלק ולהלן הוא אומר מחה<sup data-n=\"1188\">3</sup> תמחה את זכר עמלק, הענין הוא כי הנה כתיב ראשית<sup data-n=\"1189\">4</sup> גוים עמלק. וביאור הדבר הנה נודע שיש באדם נרנח\"י, נשמה היא בינה, נשמת<sup data-n=\"1190\">5</sup> שדי תבינם, היא ההתבוננות שבנפש המשכלת ומתבוננת בגדולת א\"ס ב\"ה איך דכולא קמי' כלא ממש חשיבא ואין ערוך אליו אפי' כטפה מן הים, אך וגם שהמים מים הוא מסוג אחד, משא\"כ אליו ית' אין ערוך ויחוס כלל דלית<sup data-n=\"1191\">6</sup> מחשבה תפיסא בי' כלל, ורוח הוא בחי' התפעלות הנפש ע\"י הזכרת שירים ושבחים של מקום מעשה ידיו הרבים ועצומים כי הוא אבינו וחיינו האמיתי, אשר אלו וכיוצא כאלו מעוררים את הנפש באהבה טבעית ומסותרת שבה, ונפש היא הסכמת הלב לילך בדרך טובים ולקבל עליו עומ\"ש בסור מרע ועשה טוב בפועל ממש, אבל חיה יחידה היא בחי' חכ' שבנפש שהיא למעלה מעלה מבחי' בינה שהיא ההשגה בטעם ודעת המושג ומובן משא\"כ בחי' חכמה כח מה היא למעלה מהשגה בטעם ודעת רק היא שמאין תמצא וכלולה בבחי' אין ממש והיא כמעט היפוך מן הבינה שהיא ההשגה שההשגה בגדלות א\"ס ב\"ה הוא בחי' יש ודבר שמשיג ומבין בשכלו וכמ\"ש להנחיל<sup data-n=\"1192\">7</sup> אוהבי יש וגם לפי שהוא מלובש ביש גשמי לכך צריך להתבונן בשכלו שגם שכלו ישיג גדולתו ית' משא\"כ בחי' חכמה הוא בחי' ביטול באא\"ס שבאמת כולא קמי' כלא חשיב ואין צריך להתבונן בשכלו ורוח בינתו להעמיק דעתו בזה להתבטל אליו ית' כי ממילא ומעצמו נמשך לו בחי' ביטול בבחי' ראי' חושית והוא בחי' יחוד באא\"ס ב\"ה ששורה ומתגלה יחוד עליון בנפשו ממש.\n<b>והנה</b> זלעו\"ז עשה אלקי' וכנגד נר\"ן יש ע'<sup data-n=\"1193\">8</sup> אומות, ההתבוננות הוא דווקא בישותו וגסותו וכבוד עשרו, וכן ההתפעלות והסכמה בגמר דבריו ומעשיו הוא רק למשוך אחר גופו שע\"ז נאמר וכרות<sup data-n=\"1194\">9</sup> עמו הברית לתת את ארץ הכנעני והחיתי כו' והיינו בחי' ההתבוננות שמפני שבאמת אתה<sup data-n=\"1195\">10</sup> הוא ה' לבדך אלא אתה",[["1186","1","<b>כתיב כי מחה אמחה</b>: ראה לקמן נוסח שני (באריכות יותר) של מאמר זה. ונמצא ג\"כ בשינויים ואריכות בס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תקמג (ומתחיל: זכור את אשר עשה לך עמלך). ושם ע' תלה הנחת השומעים של מאמר אדהאמ\"צ (ומתחיל: ראשית גויים עמלק). תוכן של חלק מהמאמר נעתק באוה\"ת נ\"ך כרך א' ע' תשא (ומתחיל: ותקם את דבריך כי צדיק אתה פי' רבינו ז\"ל בד\"ה כי מחה אמחה כו'). ולקמן בהוספות נדפסו עוד הגהות וקיצורים מכ\"ק אדמו\"ר הצ\"צ על מאמר זה. לכללות המאמר ראה גם ד\"ה זכור בסה\"מ תרס\"ח ע' קמב. פר\"ת ע' רעח (והמשכו שם ע' רפז ואילך)."],["1187","2","<b>כי מחה אמחה</b>: בשלח יז, יד."],["1188","3","<b>מחה תמחה את זכר עמלק</b>: ע\"פ תצא כה, יט. [שם: והי' בהניח גו' תמחה את זכר עמלק. וכהל' כאן הובא גם בשו\"ע או\"ח סתר\"צ סי\"ז. לקו\"ת צו טז, א. סה\"מ תקס\"ה ח\"א ע' שפו. ס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תתקיב. ועוד]."],["1189","4","<b>ראשית גויים עמלק</b>: בלק כד, כ."],["1190","5","<b>נשמת שדי תבינם</b>: איוב לב, ח."],["1191","6","<b>דלית מחשבה תפיסא בי' כלל</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."],["1192","7","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1193","8","<b>ע' אומות</b>: כ\"ה בהכת\"י. ובנדו\"ד מבאר בז' אומות וז' מדות."],["1194","9","<b>וכרות עמו הברית</b>: נחמי' ט, ח."],["1195","10","<b>אתה הוא ה' לבדך . . ואתה מחי'</b>: שם, ו."]]],[2101920228,"עשית את השמים כו' ואתה מחי' כו' ולפיכך וכרות עמו הברית לתת את ארץ הכנעני כו' לתת לזרעו, ועוד זאת ותקם<sup data-n=\"1196\">11</sup> את דבריך כי צדיק אתה פי' דבריך היינו בחי' אותיות הקדושה המחי' את כולם ומתלבשת בהם כי חיותם ויניקתם הוא מהקדושה כנודע, ובהכרית את הגוים מה נעשה לחיות הקדושה הנמשך בהם לזה אמר ותקם את דבריך שהקמת והעלית אותם למקורם ושרשם דקדושה להיות עולים ונכללים באור ה' וקדושתו מפני כי צדיק אתה צדיק בחי' אות ברית שהוא בחי' התקשרות שנמשך מלמעלה למטה להעלותם ולהקימם מעפרם, והתקשרות זו היא צדקה גדולה וחסד שעושה הקב\"ה עם הבריות לבלתי<sup data-n=\"1197\">12</sup> ידח ממנו נדח ולכך ותקם את דבריך כי צדיק אתה וצדקו' אהב.\n<b>והנה</b> זהו ענין הנעשה בכל הגוים שמז' אומות, אבל<sup data-n=\"1198\">13</sup> עמלק הוא ראשית גוים שהוא נגד חי' יחידה שבנפש שנמשך אחר גופו בחוצפה וגסות רוח בלי טעם ודעת שאף אם הי' מתבונן בשכלו ורוח בינתו שהוא כאין וכלא ממש אינו נכנע ושב מידיעתו שאין ההתבוננות עושה רושם בגופו כלל להפוך ליבו כי חוצפא<sup data-n=\"1199\">14</sup> מלכותא בלא תגא היא, ולכן נק' עמלק<sup data-n=\"1200\">15</sup> מל' מליקה שהוא ממול ערפו דהיינו שעומד בבחי' עורף ואחוריים כו'.\n<b>והעצה</b> היעוצה לזה כי מחה אמחה את זכר עמלק, מלחמה<sup data-n=\"1201\">16</sup> להוי' בעמלק, כי מן השמים ילחמו בו ע\"י קיום האדם מצות<sup data-n=\"1202\">17</sup> זכירת מעשה עמלק שהיא מתרי\"ג מצות להרמב\"ן, ובקראו פ' זו הנה האותיות שהן דבר ה' שבפיו גדול ורב כחם לעקור בחי' זו מלהיות מונע לנפש בטמטום הלב אשר הוא מעשה עמלק שאף שמתבונן בגדלות א\"ס ב\"ה לא יוכל לפתוח לבו כו' שזהו מקליפה וס\"א שבבחי' חוצפה המגביה<sup data-n=\"1203\">18</sup> כנשר כמ\"ש בלק\"א, וע\"י קריאת אותיות שבפ' זו משם יורידנו ה'.",[["1196","11","<b>ותקם את דבריך</b>: שם, ח."],["1197","12","<b>לבלתי ידח ממנו נדח</b>: שמואל ב יד, יד."],["1198","13","<b>אבל עמלק הוא ראשית גוים שהוא נגד חי' יחידה</b>: ראה אוה\"ת שמות (דרושים לפ' זכור) כרך ח' ע' ג'צה: צ\"ע בזכור תקס\"ה נזכר עמלק למטה מפרעה כנגד דעת תחתון ובכי מחה תקע\"ב נזכר דעמלק נגד חי' שלמעלה מנשמה כו'."],["1199","14","<b>חוצפא מלכותא בלא תגא</b>: ראה סנהדרין צט, ב. קה, א. סה\"מ תקס\"ג ח\"א ס\"ע ר. ובכ\"מ."],["1200","15","<b>עמלק מל' מליקה</b>: ראה תו\"א פה, א ואילך."],["1201","16","<b>מלחמה להוי' בעמלק</b>: בשלח שם, טז."],["1202","17","<b>מצות זכירת מעשה עמלק שהיא מתרי\"ג מצות להרמב\"ן</b>: כ\"ה בכת\"י המעתיק. וכ\"ה להלן במאמר זה נוסח השני [ובכת\"י א': להרב\"ן]. ובס' מאמרי אדהאמ\"צ שם ע' תקסב הלשון: ועוד עצה לזה ע\"י מצות קריאת פ' זכור בתורה שהיא מ\"ע דאורייתא ממנין תרי\"ג כו'. וראה רמב\"ן עה\"ת ס\"פ כי תצא. ראב\"ן מגילה יח, א. מאמרי אדה\"ז עה\"ת ע' תקנג. וראה ס' השיחות תשמ\"ט ח\"א ע' 341 . וש\"נ."],["1203","18","<b>המגביה כנשר כמ\"ש בלק\"א</b>: פכ\"ב ופכ\"ז. ועוד."]]],[2101920229,"<b>אך</b> בהניח ה' מכל הגוים מסביב בארץ אשר ה' אלקי' נותן לך כו' שבא\"י הוא מקום השראת ח\"ע כמ\"ש תמיד<sup data-n=\"1204\">19</sup> עיני ה' אלקי' בה, ועינים הן בחי' חכמה, והחכמה<sup data-n=\"1205\">20</sup> מאין תמצא היא כנגד בחי'<sup data-n=\"1206\">21</sup> ולכן אזי יהי' לך בעצמך לבטל המלוכה<sup data-n=\"1207\">22</sup> וס\"א זו ותמחה בעצמך את זכר עמלק, אבל מדור דור דהיינו דור אחר דור שבחי'<sup data-n=\"1208\">23</sup> שאין שם גילוי השראת ח\"ע מחה אמחה אני לבדי דוקא, כי בכח הנשמה שהיא מבחי' בינה א\"א לבטל רק כח הז' אומות, ולכן בז' אומות כתי' ותקם את דבריך שהאותיות דקדושה עולות ונכללות במקורן ושרשם אבל בעמלק אין לו עלי' בקדושה כלל רק מחה אמחה לגמרי.\n<b>וזה</b> הי' טעות שאול שהביא ראשית החרם לזבוח לה' בגלגל ובזה אמר הקימותי<sup data-n=\"1209\">24</sup> את דבר ה' דהיינו כמו ותקם את דבריך כו', כי מה שאמר לו שמואל והמתה<sup data-n=\"1210\">25</sup> מאיש כו' משור עד שה כו' קיים בזבחתו על המזבח, אבל שמואל אמר לו כי שמוע<sup data-n=\"1211\">26</sup> מזבח טוב כו' שאין קליפות עמלק ראוי' לעלות על המזבח לזבח כי הזבח לא יעלה אותה כי הם<sup data-n=\"1212\">27</sup> מבחי' אחוריים דחכמה וד\"ל.",[["1204","19","<b>תמיד עיני ה' אלקי' בה</b>: עקב יא, יב."],["1205","20","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["1206","21","<b>בחי'</b>: בכת\"י ב: בחי' ח\"י שבלב ונפש."],["1207","22","<b>המלוכה</b>: בכת\"י ב: הקליפה."],["1208","23","<b>שבחי'</b>: בכת\"י ב: שבח\"ל [שבחוץ לארץ]."],["1209","24","<b>הקימותי את דבר ה'</b>: שמואל א טו, יג."],["1210","25","<b>והמתה מאיש כו' משור עד שה</b>: שם, ג."],["1211","26","<b>שמוע מזבח טוב</b>: שם, כב."],["1212","27","<b>הם</b>: בהכת\"י אינו ברור כאן, ואולי חסרים כמה תיבות."]]],[2101920230,"<h3><i>נוסח אחר</i>: כתיב מחה אמחה</h3>\n<b>כתיב</b><sup data-n=\"1213\">1</sup> מחה<sup data-n=\"1214\">2</sup> אמחה את זכר עמלק, ולהלן הוא אומר מחה<sup data-n=\"1215\">3</sup> תמחה את זכר עמלק, הענין הוא כי הנה כתיב ראשית<sup data-n=\"1216\">4</sup> גוים עמלק, וביאור הדבר הנה נודע שיש ה' מדריגות נר\"ן ח\"י, בחי' נשמה היינו בחי' החכמה שיש בנפש להתבונן ולהשיג בגדולת ה' ויחודו, שזהו בחי' בינה שבנפש, וכמ\"ש נשמת<sup data-n=\"1217\">5</sup> שדי תבינם, והוא מה שהנפש משכלת ומשגת השגות אלקות ביחו\"ע ויחו\"ת כמו איך דכולא<sup data-n=\"1218\">6</sup> קמי' כלא חשיב, ולית<sup data-n=\"1219\">7</sup> מחשבה תפיסא בי' כלל, והבנה והשגה זאת הוא ענין ההסבר לקרב אל השכל המושג עד שמשיג ותופס אמיתית הדבר איך הוא,",[["1213","1","<b>כתיב מחה אמחה</b>: נו\"א של מאמר הקודם. וראה המ\"מ בתחילת המאמר שם."],["1214","2","<b>מחה אמחה</b>: בשלח יז, יד."],["1215","3","<b>מחה תמחה את זכר עמלק</b>: ע\"פ ס\"פ תצא. וראה לעיל בהמ\"מ לנוסח הראשון."],["1216","4","<b>ראשית גוים עמלק</b>: בלק כד, כ. וראה ס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תצה. וש\"נ."],["1217","5","<b>נשמת שדי תבינם</b>: איוב לב, ח. וראה ס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תלה. וש\"נ."],["1218","6","<b>דכולא קמי' כלא חשיב</b>: זח\"א יא, ב (ע\"פ דניאל ד, לב)."],["1219","7","<b>ולית מחשבה תפיסא בי' כלל</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."]]],[2101920231,"והשגה זו הוא בשכלו ממש, והוא הנק' נשמה להיותה חלק אלוק' ממעל, ע\"כ יש לה בחי' השגה במושכל בבחי' אלקו' ומשכלת בכל ענין אלקו' דוקא (והיינו משום דאימא<sup data-n=\"1220\">8</sup> עילאה מקננא בכורסייא שהוא עולם הבריאה כידוע<sup data-n=\"1221\">9</sup> דנשמה בבריאה ורוח ביצירה ונפש בעשי', ובחי' בינה דאצי' גם שנק' מבין<sup data-n=\"1222\">10</sup> ולא בבינה ידיעא מ\"מ נתצמצם צמצום האור שלה גם בבריאה להיות ג\"כ בחי' השגת אלקות בנשמות) ומשכן הנשמה במוח, אבל בחי' רוח הוא רק בחי' התפעלות הנפש ביותר הבאה מההתבוננות דגדלות הוי' ושבחיו וגם מחסדיו הרבים והעצומים, ובפרט מאשר הוא מתבונן כי הוא חיינו ואבינו האמיתי וכה\"ג מזה יתפעל הנפש ביותר, וזהו בחי' כח מיוחד בנפש כי יש שאין טבע בנפש כ\"כ להתפעל מזה, וז\"ש כי תוכן<sup data-n=\"1223\">11</sup> רוחות ה', שיש כמה מדריגות חלוקות זו למעלה מזו בבחי' התפעלות הזאת, וכמו שיר המלאכים שמתפעלים ביותר משבחו של מקום באמרם קדוש, ונק' רוחות כמ\"ש עושה<sup data-n=\"1224\">12</sup> מלאכיו רוחות, שיש בהם כמה מדריגות זו למעלה מזו כו', וכך הוא ברוח<sup data-n=\"1225\">13</sup> האדם העולה למעלה בהתפעלות באמרו שיר ושבחו של מקום בפסוד\"ז וכה\"ג (וע\"כ מדריגת<sup data-n=\"1226\">14</sup> דוד בשירים ותשבחות הוא בבחי' רוה\"ק כידוע), וכמו שיש מדריגות חלוקות זו למעלה מזו בבחי' השגת הנשמות שנק' נשמת שדי כו', דהיינו משום דז\"א מקנן באצי' שהוא בחי' רוח, ושם עולם המלאכים שמתפעלים בשיר ובשבח כו', כל חד לפי קבלתו מבחי' רוח דאדם העליון, בחי' ז\"א שמתצמצם ומאיר בעולם היצירה כו', וע\"כ עיקר מדריגת המלאכים הוא באהוי\"ר, כי בחי' רוח זה שהוא כח ההתפעלות מן השבח הוא בחי' רוח אלקי שמעורר את האהבה האלקי' הטבעי' המוסתרת, ויש דו\"ר שכליי' כו', וז\"ש כי תוכן לבות הוי' יש שמתפעל כך ויש מתפעל כך, דהיינו לפי מדריגות חלוקים שבבחי' הרוח שלהם כו' וד\"ל, ובחי' נפש הוא כמו התפעלות המלאכים שנק' אופנים בעולם העשי' בבחי' הודאה בלבד שהוא רק בחי' הסכם הנפש בבחי' קעומ\"ש המביא לידי מעשה דוקא להיות סו\"מ ועשה טוב מפני היראה למרוד ולהפרד מיחוד העליון וכו' (והיינו משום דמל' מקנן בעשי' בחי' יראה תתאה דמל' בבחי' העשי' לבד, ויש בזה ב' מדריגות אופנים וחיות הקודש, שהאופנים רק בבחי' הודאה מרחוק כו', וחיות הקדש בבחי' דו\"ר טבעיים דהיינו שאין העיקר בהתפעלות מצד ההתבוננות בשבח דוקא, אלא היא טבעי' כמו מדות טבעים באדם וכמו שמבואר במ\"א וד\"ל). וג' מדריגות הללו נר\"ן הן ג' מדריגות בבחי' ג'",[["1220","8","<b>דאימא עילאה מקננא בכורסייא</b>: תקו\"ז ת\"ו (כג, א). וראה ס' מאמרי אדהאמ\"צ שמות ח\"א ע' ריז. דברים ח\"ד ע' א'תצ וע' א'קסו. וש\"נ."],["1221","9","<b>כידוע דנשמה בבריאה ורוח ביצירה ונפש בעשי'</b>: ראה תקו\"ז סוף תכ\"ב (סח, ב)."],["1222","10","<b>מבין ולא בבינה ידיעא</b>: תקו\"ז בהקדמה שם (יז, ב)."],["1223","11","<b>תוכן רוחות ה'</b>: ע\"פ משלי טז, ב. וראה ס' מאמרי אדהאמ\"צ בראשית ס\"ע ל ואילך. וש\"נ."],["1224","12","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["1225","13","<b>ברוח האדם העולה למעלה</b>: ע\"פ קהלת ג, כא."],["1226","14","<b>מדריגת דוד כו' בבחי' רוה\"ק כידוע</b>: ראה הגהות מהרח\"ו לזח\"ג לט, א. לקוטי שיחות חי\"ח ע' 275. וש\"נ."]]],[2101920232,"עולמות בי\"ע, נשמה<sup data-n=\"1227\">15</sup> בעולם הבריאה ורוח ביצי' ונפש בעשי' וכמ\"ש בזוהר, וכל עולם מג' עולמות כלול מבי\"ע שהוא נר\"ן שבכל עולם כידוע.\n<b>אך</b> הנה בחי' ח\"י הוא למעלה מבחי' נשמה כי הנשמה במוח ורוח בלב כו' שמתלבשים בכלי (כידוע<sup data-n=\"1228\">16</sup> דנר\"ן מתלבשים במוחא ולבא וכבדא כו'), אבל ח\"י אינן מתלבשים בכלי כלל כו', להיות<sup data-n=\"1229\">17</sup> כי בחי' ח\"י הוא בבחי' חכמה<sup data-n=\"1230\">18</sup> כח מ\"ה שלמעלה מבחי' השגה דבינה כמ\"ש והחכמה<sup data-n=\"1231\">19</sup> מאין תמצא שהוא בבחי' אין ממש, משא\"כ בחי' נשמה בחי' בינה הוא בחי' יש דוקא וכמ\"ש להנחיל<sup data-n=\"1232\">20</sup> אוהבי יש, דקאי בהשגות הנשמות בג\"ע ובעוה\"ב שנהנין<sup data-n=\"1233\">21</sup> ומשיגים מזיו השכינה.\n<b>וביאור</b> הדברים הנה מבואר למעלה שבחי' בינה שבנה\"א הוא כח הנפש לקרב אל השכל כל ענין אלוקי להביאו בבחי' השגה ותפיסא ממש בטוב טעם ודעת המושג ומובן לכל בר שכל, אבל בחי' כח מ\"ה דחכמה שמאין תמצא הוא למעלה מן ההשגה לגמרי אלא הוא ענין הכרה והבנה באמיתית ענין אור האלקי כמו שהוא לאמיתתו ממש כאלו רואה בראי' והסתכלות חושי' ונק' עין השכל ולא כמו שהוא מושג ומובן בהשגת שכל וההתבוננות בלבד, וע\"כ<sup data-n=\"1234\">22</sup> נק' החכמה בחי' ראי' כידוע שאין צריך להביא דבר האלקי בהסבר לקרב אל השכל כי נראה לו בעין השכל אמיתית הדבר כמו שהוא למעלה באמת, וע\"כ א\"צ להעמיק בשכלו עד שגם שכלו ישיג זה כי שכלו והבנתו לא ישיגו לאמיתתו כמו שהוא ממש מאחר שבא הענין בעומק השג' ושכל עד\"מ מי שראה את המלך א\"צ לשמוע הסבר הדברים שמספרים בשבחו כי<sup data-n=\"1235\">23</sup> אין דומה שמיעה לראי' שהרואה רואה עצם הדבר כמו שהוא ממש והשומע שומע ענינו שאינו רק שומע ומבין ענינו ומדותיו<sup data-n=\"1236\">24</sup> ולא מהותו, שהרי אין לו רק כפי הדמיון שנדמה לו מהותו ע\"פ ההשגה בלבד, וכה\"ג ממש הוא ההפרש בין חכמה ובינה כמ\"ש<sup data-n=\"1237\">25</sup> חבקוק שמעתי שמעך",[["1227","15","<b>נשמה בעולם הבריאה . . וכמ\"ש בזוהר</b>: נסמן לעיל בסמוך."],["1228","16","<b>כידוע דנר\"ן מתלבשים במוחא ולבא וכבדא</b>: ראה זח\"ג קנג, א. ז\"ח רות פ, א. ע\"ח שער המוחין (ש\"כ) פ\"ה. אבן עזרא משפטים כג, כה. וראה ס' מאמרי אדהאמ\"צ בראשית ח\"א ע' שסה. ח\"ב ע' תכד. וש\"נ."],["1229","17","<b>להיות כי בחי' ח\"י הוא בבחי' חכמה</b>: בס' מאמרי אדהאמ\"צ שמות ח\"ב שם ע' תקמח הל' הוא: דבחי' חיה הוא בחי' החכמה כו'. [וראה לקמן סוף פיסקא ודוגמא: ובחי' יחידה הוא למעלה גם מבחי' כח מ\"ה דחכמה כו']. וראה במ\"מ שם."],["1230","18","<b>חכמה כח מ\"ה</b>: זח\"ג כח, א. לד, א. וראה ס' מאמרי אדהאמ\"צ בראשית ע' ב. וש\"נ."],["1231","19","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["1232","20","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1233","21","<b>שנהנין ומשיגים מזיו השכינה</b>: ברכות יז, א."],["1234","22","<b>וע\"כ נק' החכמה בחי' ראי' כידוע</b>: ראה גם סידור עם דא\"ח קסה, א. מאמרי אדהאמ\"צ שמות ח\"ב ע' שלב. ויקרא ח\"ב ע' תעא. וש\"נ."],["1235","23","<b>כי אין דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. ס' מאמרי אדהאמ\"צ בראשית ע' כ. וש\"נ."],["1236","24","<b>ומדותיו</b>: בכת\"י ב: ענינו ואיכותו. [ובס' מאמרי אדהאמ\"צ שמות ח\"ב שם ע' תקמח: שהשמיעה הוא רק שמבין ומשיג מסיפור הדברים איכות הדבר ולא ישיג מהותו כלל כו']."],["1237","25","<b>כמ\"ש חבקוק שמעתי שמעך יראתי</b>: ג, ב."]]],[2101920233,"יראתי ואין דומה שמיעה לראי' לא מני' כו', כי השמיעה<sup data-n=\"1238\">26</sup> וההבנה מרחוק והראיה מקרוב כו' וכמ\"ש במ\"א.\n<b>ודוגמא</b> לדבר הנה כשיתבונן האדם ביחו\"ת איך שמהוה את הכל שמקרב אל השכל בהשגה שכליי' כמו ענין הסבר הדבר איך שהוא מהוה אם בבחי' אותיות או בבחי' זיו או בבחי' חיות הנפש בגוף כ\"ז אינו דומה לבחי' ראי' החכמה להכיר באמיתית הדבר הזה כמו שהוא ממש, דהיינו כמו שהוא באמת מהווה את הכל מאין ליש כמארז\"ל איזהו<sup data-n=\"1239\">27</sup> חכם הרואה את הנולד, פי' הנולד מאין ליש רואה ראי' שכלי' כו' וכך הוא בבחי' יחו\"ע איך שהאציל ע\"ס, אינו דומה השגה והסבר לבחי' ראי' שכלי' להכיר לאמיתתו כמו שהוא באמת מאציל ע\"ס כו', וזהו שהחכמה נק' כח מ\"ה בבחי' אין כי שרשה מבחי' אין ע\"כ ביכולתה לראות ולהסתכל בבחי' אין וע\"כ החכמה בבחי' ביטול במציאות ביטול עצמי וממילא ולא שצריך להתבונן בגדלותו בשכלו עד שמחמתו מתבטל אלא מעצמו וממילא נמשך לו בחי' ביטול מצד ששרשו בבחי' אין וכמ\"ש והחכמה מאין תמצא בבחי' אין ממש להיותו בבחי' ראי' כאדם שרואה את המלך שביטולו ביטול עצמי בלא שכל והשגה למה הוא בטל, משא\"כ ביטול הבא רק מצד ההשגה שמשיג בשכלו בגדולת המלך הרי זהו ביטול הנקנה שהוא יש רק שמתבטל מישותו מפני טו\"ד השגתו הוא לפי ערך השגתו בלבד כו', והיינו מפני דבחי' בינה נק' יש וה\"ז מלובש ביש והשגה ע\"כ גם בחי' ביטול מישותו צ\"ל ע\"פ השגה ששכלו משיג איך הוא גדולתו כך יבטל א\"ע, וגם למעלה בענין גדולת הוי' כמו שמתבונן איך דכולא קמי' כלא כו' לפי השגתו יבוטל מפני ששכלו יש ע\"כ צריך שגם שכלו משיג הביטול משא\"כ בחי' חכמה כח מ\"ה הוא בחי' ביטול עצמי וממילא מפני שהדבר אצלו בבחי' ראי' כמו שהוא באמת דכולא קמי' כלא כו' ולא כמו שהוא מושג בהשגה בלבד כו', וע\"כ ע\"י החכמה דוקא שורה אין האמיתי דאוא\"ס עצמו כידוע<sup data-n=\"1240\">28</sup> דראשית גלוי אוא\"ס בחכמה דוקא וד\"ל. ובחי' יחידה הוא למעלה גם מבחי' כח מ\"ה דחכמה הנ\"ל, שכח מ\"ה אינו רק שנמשך מאין אבל לא אין עצמו משא\"כ בחי' יחידה שהוא בחי' עצם הנה\"א כמו שמיוחדת בהתקשרות עצמי' באלקות ולא כמו בחי' ראי' בלבד וכמ\"ש רשב\"י בחד<sup data-n=\"1241\">29</sup> קטירא אתקטרנא בי' אחידא כו' שהוא בבחי' אין האלקי ממש. (וכמ\"ש במ\"א וד\"ל).",[["1238","26","<b>השמיעה וההבנה מרחוק והראיה מקרוב כו' וכמ\"ש במ\"א</b>: ראה ס' מאמרי אדה\"ז תקס\"ג ח\"א ע' רפז. תקס\"ד ע' רו. ובכ\"מ."],["1239","27","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א. וראה תניא פמ\"ג. מאמרי אדהאמ\"צ דברים ח\"א ע' רכא. וש\"נ."],["1240","28","<b>כידוע דראשית גלוי אוא\"ס בחכמה דוקא</b>: ראה תניא פל\"ה (בהגה\"ה). וראה מאמרי אדהאמ\"צ בראשית ע' כא. וש\"נ."],["1241","29","<b>בחד קטירא אתקטרנא בי' אחידא כו' . . וכמ\"ש במ\"א</b>: ראה זח\"ג רפח, א. רצב, א. וראה סידור עם דא\"ח קסג, א. סה\"מ תקס\"ז ע' עא וע' לו. מאמרי אדה\"ז עה\"ת ח\"א ע' רנז. ס' מאמרי אדהאמ\"צ בראשית ע' קעא. שמות ח\"ב ע' שכט. במדבר ח\"ב ע' תשא. דברים ח\"ב ע' שפה. (ובהנסמן בכל המ\"מ שם)."]]],[2101920234,"ב) <b>והנה</b> את זלעו\"ז עשה האלקים דכנגד נר\"ן דקדושה כנ\"ל יש ז' אומות הכנעני החיתי כו' שהוא בחי' מדות דקליפה כמו תאות רעות שהוא התפעלות הנה\"ב במדות רעות הנולד מהתבוננות דבחי' בינה דקליפה, וכמו שבחי' בינה דקדושה כוללת נו\"ן שערים דקדושה כך בחי' בינה דקליפה כוללת נ' שע\"ט וזהו הבא<sup data-n=\"1242\">30</sup> לטמא פותחין לו כו', אך בהתגברות בחי' בינה שבנה\"א עם בחי' רוח ונפש המסתעפים ממנה כנ\"ל, אזי מתהפכים ז' מדות רעות דקליפה עם בחי' מקורן ושרשן אל הקדושה האלקי דהיינו שמתברר מהן בחי' הטוב מבחי' נצוצי קדושה שנתלבשו בהן להחיותן שהוא מבחי' רפ\"ח נצוצין דקדושה שנפלו בשה\"כ בז' מלכין דתהו שמתו כידוע שמהם יש יניקה לז' אוה\"ע ואעפ\"י שנא' בז' אוה\"ע לא<sup data-n=\"1243\">31</sup> תחי' כל נשמה מ\"מ הרי ארצם נתן לישראל לירושה להעלות כל בחי' הטוב שבקדושה שנפלו שם וזהו ונתן<sup data-n=\"1244\">32</sup> ארצם לנחלה כו' כי כל המצות נעשו בארץ ונק' א\"י כו'. וזהו וכרות<sup data-n=\"1245\">33</sup> עמו הברית לתת את ארץ הכנעני וכו' עד לתת לזרעו ותקם את דבריך כי צדיק אתה ויש להבין בזה המשך הדברים מה שייכות יש לזה עם מה שקדם אליהם במ\"ש אתה<sup data-n=\"1246\">34</sup> הוא ה' לבדך אתה עשית כו' אתה בחרת באברם כו' וכרות עמו כו' עד ותקם את דבריך כו'. אך הענין הוא דתחלה מדבר בבחי' התבוננות בגדולת הוי' בבחי' יחו\"ע דעצמו' אוא\"ס איך שאתה הוי' לבדך והשמים ושמי השמים והארץ כו' בחי' מקיפים דחיה יחידה, ובחי' ים וארץ בינה ומל' הכל בבחי' יחודא עילאה המושג בשכל וההשגה שהוא ע\"י בחי' בינה שבנפש שנאמר בה נשמת שדי תבינם עי\"ז נולד התפעלות הנפש במדות בחי' רוח ונפש הנ\"ל, וזהו אתה בחרת באברם שרוחו רוח אלקי בתוקף ההתפעלות בנפשו מההתבוננות כמארז\"ל בן<sup data-n=\"1247\">35</sup> ג' שנים הכיר את בוראו וכו' היינו ומצאת את לבבו נאמן לפניך, וע\"כ ממילא וכרות עמו הברית לתת לו את ארץ הכנעני כו' שהוא היפך ז' מדות רעות שמנגד לקדושה ונתונים המה לזרעו אחריו שיש בכל דור כח<sup data-n=\"1248\">36</sup> בנש\"י לאהפכא חשוכא לנהורא ע\"י עבודת נפשם בדו\"ר שכליי' כידוע, ולא עוד אלא שגם בחי' ניצוצות דקדושה שנפלו בהם מתבררים ועולים ונכללים בקדושה, וזה ותקם את דבריך כו' כי הנה גם בהכרית כל נשמה מז' אומות מה נעשה לניצוץ האלקי וחיות הקדושה האלקי הנמשך ומתלבש בהן לזה אמר ותקם את דבריך פי' דבריך הם בחי' אותיות הקדושה שנפלו בשבירה הקמת והעלית אותם למקורן ושרשן הראשון באור ה' וקדושתו כמו שהי' קודם השבירה כו' מפני כי צדיק אתה כמ\"ש אמרו<sup data-n=\"1249\">37</sup> צדיק כי טוב שטבע<sup data-n=\"1250\">38</sup> הטוב להטיב לרוח שפלים שנפלו להקימן ולהעלותן מעפרן להיות כי בחי' צדיק עליון הוא בחי' התקשרות המשפיע למטה במקבלים והוא שנמשך מלמעלה למטה מטה להקים ולהרים את",[["1242","30","<b>הבא לטמא פותחין לו</b>: ראה יומא לח, ב."],["1243","31","<b>לא תחי' כל נשמה</b>: דברים כ, טז."],["1244","32","<b>ונתן ארצם לנחלה</b>: תהלים קלו, כא."],["1245","33","<b>וכרות עמו הברית</b>: נחמי' ט, ח."],["1246","34","<b>אתה הוא ה' לבדך . . אתה בחרת . . ותקם את דבריך</b>: נחמי' שם, ו ואילך."],["1247","35","<b>בן ג' שנים הכיר את בוראו</b>: נדרים לב, א."],["1248","36","<b>כח בנש\"י</b>: בכת\"י ב: כח בבואם."],["1249","37","<b>אמרו צדיק כי טוב</b>: ישעי' ג, י."],["1250","38","<b>שטבע הטוב להטיב</b>: ראה תניא שעהיחוה\"א פ\"ד. ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתמג. וש\"נ."]]],[2101920235,"הנופל לבלתי<sup data-n=\"1251\">39</sup> ידח ממנו נדח ח\"ו, וזהו רק מצד בחי' עצם הטוב והצדקה וחסד שעושה ה' עם הבריות לבלתי ידח ממנו נדח כמ\"ש החפץ<sup data-n=\"1252\">40</sup> אחפוץ במות הרשע כו' לפי שצדיק<sup data-n=\"1253\">41</sup> ה' ע\"כ צדקות אהב להחיות רוח שפלים שירדו למטה מטה ולהשיב את הנדחים ולקרב את הרחוקים כו', וזהו ותקם את דבריך שנפלו ונתרחקו ולהשיב את נדחו מפני כי צדיק אתה וד\"ל.\n<b>והנה</b> מ\"ש ותקם את דבריך פי' שיש עלי' ובירור לטוב מן הרע הוא דוקא ענין הנעשה בכל הגוים שמז' אומות לפי ששרשם בזלע\"ז דקדושה רק בבחי' בינה ומדות (שהוא בבחי'<sup data-n=\"1254\">42</sup> ס\"ג שבו הי' השבירה), אבל עמלק נק' ראשית גוים ששרשו בזלע\"ז דקדושה למעלה מכל הגוים לפי שבחי' עמלק הוא בבחי' המנגד לבחי' יחידה<sup data-n=\"1255\">43</sup> שלמעלה מבחי' נר\"ן כמבואר למעלה שבחי'<sup data-n=\"1256\">44</sup> יחידה הוא בבחי' ביטול העצמי דכח מה שלמעלה מן הטעם וההשגה לגמרי כך לעו\"ז דקליפה הוא בחי' חוצפא דעמלק שנמשך אחר עצמו דוקא להיות בחי' יש וגסה\"ר בלי שום טו\"ד כלל, כי הנה כמו שיש ב' מיני ביטול א' מצד טעם והשגה, והב' ביטול העצמי בבחי' אין דחכמה כח מ\"ה למעלה מן הטעם כנ\"ל באריכות, כך הוא במנגד לבחי' הביטול שהוא בחי' יש ודבר, יש ב' סוגים א' הבא מהטעם וההשגה כמו עשיר גדול שיענה עזות<sup data-n=\"1257\">45</sup> וחוצפה יתירה מצד עושרו או חכם גדול שמתגאה מצד חכמתו או גבור מצד גבורתו ומכש\"כ מלך שמרומם ומנושא על הכל בעושר וגבורה וחכמה וכה\"ג, אבל יש בחי' חוצפה ועזות בבחי' יש וגסה\"ר שלמעלה מן הטעם כגון שאינו עשיר ולא חכם כו' והוא בתכלית הפחיתות וגם הוא בעצמו יודע שהוא שפל בכל הדברים וכאין וכלא חשיב בעיני הכל מ\"מ לא נכנע לבבו כלל וכלל, כי הגם שמתבונן היטב בשכלו ורוח בינתו בכל הפחיתות שלו אינה מועלת זאת ההתבוננות בנפשו כלל ולא תעשה שום רושם הכנעה בגופו כלל להפוך לבו מן החוצפה אל השפלות והכנעה אפילו כחוט השערה אלא עומד ברום לבבו וגסות רוחו להעיז לכל נכבד כו' וא\"כ מזה הוראה גמורה שיש בחי' חוצפה שלמעלה מן הטו\"ד ונק' חוצפה זו מלכותא<sup data-n=\"1258\">46</sup> בלא תגא כידוע (כי יש מלך מרומם מצד עצם הרוממות ויש מלך מתרומם מצד ההתנשאות בלא טעם כו'), ולכך אין בחי' התבוננות מועלת לו להכניע א\"ע, וזהו בחי' המנגד לבחי' הביטול דחכמה שבבחי' אין שלמעלה מן הטעם כו' והוא ענין קליפת עמלק שנק' ראשית גוים שלמעלה מבחי' בינה דקליפה שהמדות רעות דז' אומות יצאו משם כו', אלא",[["1251","39","<b>לבלתי ידח ממנו נדח</b>: שמואל ב יד, יד."],["1252","40","<b>החפץ אחפוץ במות הרשע</b>: ע\"פ יחזקאל לג, יא. וראה ס' מאמרי אדהאמ\"צ קונטרסים ע' תפד."],["1253","41","<b>שצדיק ה' ע\"כ צדקות אהב</b>: תהלים יא, ז."],["1254","42","<b>בבחי' ס\"ג שבו הי' השבירה</b>: ראה ע\"ח שער דרושי הנקודות (ש\"ח) פ\"א. ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' שעט. וש\"נ."],["1255","43","<b>יחידה</b>: בכת\"י ב: חי' יחידה. בכת\"י ג: חי'. [וראה ס' מאמרי אדהאמ\"צ שמות ח\"ב שם ע' תקנח: הוא בחי' מנגד לבחי' המקיפים דחי' יחידה כו'. וכ\"ה לעיל בנוסח הראשון]."],["1256","44","<b>שבחי' יחידה הוא</b>: בכת\"י ב: שבח\"י הוא."],["1257","45","<b>שיענה עזות</b>: ע\"פ משלי יח, כג."],["1258","46","<b>מלכותא בלא תגא</b>: ראה סנהדרין צט, ב. קה, א. וראה סה\"מ תקס\"ג ח\"א ע' ר."]]],[2101920236,"הוא בבחי' חכמה דקליפה ולכך נק' עמלק<sup data-n=\"1259\">47</sup> מל' מליקה שהוא ממול העורף שעומד בבחי' עורף ואחוריים דחכמה כח מ\"ה שבפנים שנאמר בו חכמת אדם תאיר פניו כו', וע\"כ אין לקליפה זו בירור ותיקון כלל מצד נה\"א עצמו שנק' נשמה שהיא רק בבחי' בינה בלבד כנ\"ל, אבל שרש קליפת עמלק למעלה מבחי' נר\"ן וכו', ולזה אין עצה לתקנו ולבררו למטה ע\"י נש\"י אלא מחה אמחה כו' אמחה אני בעצמי דוקא כי מן השמים דוקא ילחמו בו כמ\"ש מלחמה<sup data-n=\"1260\">48</sup> לה' בעמלק, להוי' דוקא מלחמה זאת לנצח ולהכניע קליפת עמלק שאין זה בכח כנ\"י למטה מטעם הנ\"ל וד\"ל.\nג) <b>והנה</b> ענין מלחמה להוי' בעמלק במה ינוצח מן השמים, הנה הוא בדבר שבקדושה האלקי' המנגד אליו דוקא והוא ע\"י בחי' הארת אוא\"ס בכח מ\"ה דחכמה שהחכמה מאין תמצא כנ\"ל שבזה דוקא יפול בחי' יש וחוצפה דעמלק שלמעלה מן ההשגה והטעם כו', ולמטה יכול להיות ג\"כ בחי' ביטול היש והחוצפה דעמלק שיש בנה\"ב למעלה מן הטעם עד שלא יועיל לו כלל התבוננות פחיתות ערכו להשפיל א\"ע וכו' כנ\"ל, והיינו ע\"י בחי' גלוי אור אלקי בכח מ\"ה שבנה\"א שבבחי' ראי' השכל שלמעלה מן השגה כנ\"ל באריכות וד\"ל.\n<b>ובזה</b> יובן ענין נפלא א' שאנו רואים גם במבקשי ה' וקרבת אלקים יחפצון שלפעמים גם שיעמיק דעתו ורוח בינתו בהתבוננות בגדולת ה' ביחו\"ע ויחו\"ת לא יתפעל מאומה בלבו והעולם קוראים לחולה רעה זו בחי'<sup data-n=\"1261\">49</sup> טמטום הלב, שהלב מטומטם כאבן, ונדמה להם שטמטום זה מצד הלב הוא בא מפני שנתגשם בחומריות כמו עבירה<sup data-n=\"1262\">50</sup> שמטמטמת לבו של אדם, וכן תאות היתר כמו נואף אשה חסר לב<sup data-n=\"1263\">51</sup> כו', אך באמת שרש חולי רעה זו למעלה הרבה מטומאת הלב אלא נוגעת עד הנפש עצמה שהוא בחי' טומאת הנפש עצמה ומהותה שלמעלה גם מבחי' בינה שבנפש כו', והוא ענין התוקף הגדול בבחי' חוצפה וגסות הנפש כמו קליפת עמלק ממש אשר ע\"כ גם שמתבונן היטיב בהעמקת הדעת בבחי' בינה שבנפש לא יועיל להכניע לבבו בבחי' התפעלות וביטול אלא לבו כלב האבן בקשיו לא יפול לבבו מכל התבוננות בכל גדולת הוי' בהשגת נפלאות הוי' איך דכולא קמי' כלא כו', ונק' אבירי<sup data-n=\"1264\">52</sup> לב הרחוקים מאחדותו כו' שזהו רק מבחי' הקליפה וס\"א דעמלק המגביה<sup data-n=\"1265\">53</sup> כנשר כו', למעלה מן השכל שלא יועיל שם שום שכל והתבוננות כנ\"ל באריכות כו', והוא סיבת חולי רעה הנמצאת הנק' טמטום",[["1259","47","<b>עמלק מל' מליקה</b>: ראה גם תו\"א תצוה פה, א ואילך. ובכ\"מ."],["1260","48","<b>מלחמה לה' בעמלק</b>: בשלח יז, טז."],["1261","49","<b>בחי' טמטום הלב</b>: ראה גם תניא פכ\"ט. מאמרי אדה\"ז הקצרים ס\"ע תפב ואילך. שערי תשובה לאדהאמ\"צ ג, ג ואילך. דרך חיים יט, ב. שער התפילה פ, ג. עטרת ראש מו, א. ובכ\"מ."],["1262","50","<b>עבירה שמטמטמת לבו של אדם</b>: יומא לט, א. וראה גם מאמרי אדהאמ\"צ שמות ח\"א ע' נד. וש\"נ."],["1263","51","<b>נואף אשה חסר לב</b>: משלי ו, לב."],["1264","52","<b>אבירי לב</b>: ישעי' מו, יב. ברכות יז, ב."],["1265","53","<b>המגביה כנשר</b>: ראה לקמן בסמוך."]]],[2101920237,"הלב שזה ענין קושי' הלב שקשה כאבן דומם ולא שנסתם ונטמטם ע\"י סיבות אחרות שזהו רק היפך פתיחות הלב שאין לבו פתוח בתורה ויראת ה' מפני שנסתם ונטמטם בתאות וכה\"ג וזהו בנקל להתקין כי יטהר הלב ויפתח ע\"י מעט יגיעה בתפלה כי הבא<sup data-n=\"1266\">54</sup> לטהר לבו מסייעין לו כו', אבל בחי' טמטום הנק' קושי הוא הנק' לב האבן כמ\"ש והסירותי<sup data-n=\"1267\">55</sup> את לב האבן מבשרכם ונתתי לכם לב בשר כו', ה\"ז מצד החוצפה שבנפשו בבחי' מעשה עמלק דוקא מטעם הנ\"ל וד\"ל, ואין עצה להסיר לבחי' טמטום לב האבן הזה אלא רק ע\"י בחי' גלוי אלקות בכח מ\"ה שבנפש בבחי' ביטול אמיתי הנ\"ל, ומלחמה זו לה' הוא שמתגלה בכח מ\"ה שבנה\"א להכניע לבחי' יש וחוצפה בלי טעם הנ\"ל וד\"ל.\n<b>ועוד</b> יש עצה לזה ע\"י מצות זכירת מעשה עמלק שהוא<sup data-n=\"1268\">56</sup> מתרי\"ג מצות להרמב\"ן, שבקראו פ' זו שהוא דבר ה' בפיו, שבה גלוי אוא\"ס בחכמה שבפ' זו, הרי בזה יש כח גדול ורב להכניע לבחי' חוצפה דעמלק שבנפשו, כמ\"ש אם<sup data-n=\"1269\">57</sup> תגביה כנשר משם אורידך נאום ה', הוי' דוקא, כמ\"ש מלחמה לה' בעמלק, והיינו ע\"י שאומר פ' זו דמחה אמחה, וכל האותיות דפ' זו כו' וד\"ל.\nד) <b>ומעתה</b> י\"ל בתירוץ שני הפסוקים הללו דסתרי אהדדי לכאורה, דכאן א' מחה אמחה כו' ולהלן א' מחה תמחה כו', ולפי הנ\"ל אין כח כלל בנש\"י למחות כי מלחמה לה' בעמלק כו' כנ\"ל, אך הענין הוא דמ\"ש מחה תמחה קאי בהיות ישראל שרוים על אדמתם בא\"י דוקא וכמ\"ש בסוף פ' כי תצא והי' בהניח<sup data-n=\"1270\">58</sup> ה' אלקיך לך מכל אויבך מסביב בארץ אשר ה' אלקיך נותן לך נחלה לרשתה תמחה את זכר עמלק כו', אבל מ\"ש מחה אמחה כו' מלחמה לה' בעמלק הוא בפ' בשלח מיד אחר מלחמת יהושע בעמלק, הענין הוא מטעם הנ\"ל שא\"א להכניע לקליפת עמלק כ\"א בבחי' גלוי אוא\"ס והשראתו בח\"ע בחי' כח מ\"ה שמאין תמצא כנ\"ל, וע\"כ קודם כניסתן לארץ א' מחה אמחה שמן השמים ילחמו בו כנ\"ל, אבל בבואם לארץ יש ביכולת ישראל להכניע לעמלק מצד עצמם וכחם והוא מ\"ש תמחה את כו', והטעם הוא להיות ידוע שבחי' ושורש ארץ ישראל הוא המקום שבו הוא בחי' גילוי והשראת ח\"ע דוקא כמ\"ש עיני<sup data-n=\"1271\">59</sup> ה' אלקיך בה מראשית השנה כו', וידוע דהעינים הוא בבחי' חכמה כמו עיני העדה ומאחר שנאמר עיני הוי' אלקיך בה הרי תמיד מאיר בה מבחי' פנימי' ח\"ע שהוא בחי' אין כמ\"ש והחכמה<sup data-n=\"1272\">60</sup> מאין תמצא וכמו שמבואר למעלה שהראי' בבחי' חכמה דוקא",[["1266","54","<b>הבא לטהר לבו מסייעין לו</b>: ראה יומא שם. וראה מאמרי אדהאמ\"צ דברים ח\"ד ע' א'תקב. וש\"נ."],["1267","55","<b>והסירותי את לב האבן</b>: יחזקאל לו, כו."],["1268","56","<b>שהוא מתרי\"ג מצות להרמב\"ן</b>: ראה רמב\"ן ס\"פ תצא. וראה במ\"מ לעיל בנוסח הראשון."],["1269","57","<b>אם תגביה כנשר</b>: עובדי' א, ד. וראה תניא פכ\"ב ופכ\"ז. ס' מאמרי אדהאמ\"צ שמות ח\"ב שם ע' תקסג. וש\"נ."],["1270","58","<b>והי' בהניח ה' אלקיך</b>: ס\"פ תצא שם."],["1271","59","<b>עיני ה' אלקיך בה</b>: עקב יא, יב."],["1272","60","<b>והחכמה מאין תמצא</b>: איוב כח, יב."]]],[2101920238,"כמו בבהמ\"ק בכל רגל דכתיב יראה<sup data-n=\"1273\">61</sup> כל זכורך את פני הוי' כו', וכשם שבא לראות כו', הרי הי' בזה בחי' הסתכלות ראי' דחכמה דכנ\"י ממטה למעלה בבחי' ביטול הפנימי דכח מ\"ה לאסתכלא<sup data-n=\"1274\">62</sup> ביקרא דמלכא לאמיתתו כמו שהוא מהוה מאין ליש ביחו\"ת וכן ביח\"ע כו' כנ\"ל, וכמ\"כ מלמעלה למטה עיני הוי' אלקיך כו', כשם שבא לראות וכמ\"ש<sup data-n=\"1275\">63</sup> עיניך יונים וכתיב עיניו כיונים כו', וכמ\"ש במ\"א, וע\"כ בזה דוקא יש כח בכנ\"י בעצמם לבטל ולהכניע קליפת עמלק המנגד לבחי' ביטול זה, וזהו והי' בהניח ה' אלקיך לך מכל אויבך מסביב שהוא התהפכות ז' מדות רעות דז' אומות בכניסתם לא\"י, ותהי' הארץ להם לנחלה להעלות כל ניצוצי הקדושה שנפלו שם, וזהו בארץ אשר ה' אלקיך נותן לך נחלה לרשתה, אז תמחה את זכר עמלק, שתמחה בכח עצמך ולא תצטרך לעזר מלחמה מן השמים וכו', מטעם הנ\"ל, לפי שארץ זו עיני ה' אלקיך בה כו' ארץ אשר ה' אלקיך דורש אותה כו' שגלוי עצמות אוא\"ס בחכ\"ע מלובש שם (ודוקא לאחר שהניח ה' אלקיך מכל אויבך כו', שזהו תנאי ב' מלבד מעלת א\"י מצד עצמה אשר היא ארץ אשר הוי' אלקיך דורש אותה כו', משום דהא בהא תליא, שאם אין בירור לז' אומות אינה נק' א\"י ואין ה' דורש אותה כלל, לפי שאין בחי' תיקון אלא לאחר בחי' הבירור דתהו, וגם באדם למטה אם אין בירור בז' מדות רעות אין בחי' ביטול בכח מ\"ה שבנפשו כלל, ומשום דבחכ'<sup data-n=\"1276\">64</sup> איתברירו אמר והי' בהניח ה' אלקיך לך מכל אויבך וכן אשר ה' אלקיך נותן לך נחלה כו', ואז עיני ה' אלקיך בה כו' וד\"ל).\n<b>וזהו</b> שבפ' בשלח א' מחה אמחה אני בעצמי וכ' שם מלחמה לה' בעמלק מדור דור דשם מדבר בדור אחר דור עד ימוהמ\"ש שזהו בחו\"ל שאין שם גילוי השראת ח\"ע, לא מצד הבירור שבחכמה אתברירו ז' אומות מלמטה למעלה, ולא מצד גילוי השראת ח\"ע מלמעלה למטה כו' כנ\"ל, ע\"כ מחה אמחה אני לבדי כי אין בכח הנשמה שהיא בינה רק לברר ז' אומות ולכך בז' אומות נאמר ותקם את דבריך כנ\"ל, שהאותיות דקדושה שנפלו בהם עולות לשרשן בקדושה, אבל בעמלק אין לו עלי' לקדושה רק מחי' (וכן בכח נש\"י מצד עצמם א' שתמחה את זכר כו' כי אין לו עלי' ותיקון כשאר אומות כו') לגמרי. והטעם הוא כי אין תיקון ובירור רק למה שנפל בשבירה שהן ז' מדות שכאשר מתהפכים למדות הרי הן ז\"מ דקדושה, משא\"כ קליפת עמלק למעלה מהשבירה שבמדות דבינה שם ס\"ג כי הוא רק חוצפה שכנגד בחי' ח\"י כנ'ל, כי אין לה תיקון רק אבוד וכליון למחות שרשו לגמרי, (כי א\"א להיות מזה בחי' התנשאות דקדושה כמו<sup data-n=\"1277\">65</sup> שמינית שבשמינית כו'",[["1273","61","<b>יראה כל זכורך כו' וכשם שבא לראות</b>: דברים טז, טז. חגיגה ב, א."],["1274","62","<b>לאסתכלא ביקרא דמלכא</b>: ראה זח\"א לח, א-ב. קצט, א. זח\"ב קלד, א. רמז, ב. ועוד."],["1275","63","<b>וכמ\"ש עיניך יונים וכתיב עיניו כיונים כו' וכמ\"ש במ\"א</b>: שה\"ש א, טו. ד, א. ה, יב. ראה לקו\"ת ואתחנן ב, ד. ג, ג ואילך. שה\"ש יד, ב. לד, ג. לט, א. ובכ\"מ."],["1276","64","<b>דבחכ' אתברירו</b>: ראה זח\"ב רנד, ב. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ בראשית ע' סב. דברים ח\"א ע' רצה."],["1277","65","<b>כמו שמינית שבשמינית</b>: סוטה ה, א. וראה תו\"א קכ, א. ובכ\"מ."]]],[2101920239,"מאחר שהן ב' הפכים זה תכלית היש וזה תכלית האין, רק לעתיד כתיב אז<sup data-n=\"1278\">66</sup> אהפוך אל עמים שפה ברורה שגם עמלק יתברר לפי שיהופך מתכלית היש לתכלית האין כו'. ומ\"ש בלעם ואחריתו<sup data-n=\"1279\">67</sup> עדי אובד קאי עכשיו עד ימוהמ\"ש וראי' שהרי מקבלים גרים מעמלק, כידוע<sup data-n=\"1280\">68</sup> דבני בניו של המן כו' וד\"ל).\n<b>וזה</b> הי' טעות שאול שהביא<sup data-n=\"1281\">69</sup> ראשית החרם מעמלק לזבוח לה' בגלגל כי סבור הי' שיש עלי' להטוב שבעמלק כמו לז' אומות וז\"ש הקימותי<sup data-n=\"1282\">70</sup> את דבר ה' שבפ' בעמלק וכמו ותקם את דבריך כנ\"ל בז' אומות, והשיב לו שמואל שמוע<sup data-n=\"1283\">71</sup> מזבח טוב כו', כי אין עלי' כלל לקליפת עמלק בזבחים ועולות שהוא בחי' בירור דז' מלכים דתוהו שנפלו, מאחר ששרשו למעלה מבחי' השבירה שבמדות דבינה בחי' ס\"ג כו', אלא הוא נגד בחי' ח\"י כו', אשר ע\"כ אין לו תיקון ועלי' רק למחות שמו בבחי' ביטול לגמרי דוקא. וזה רמז לו שמוע מזבח טוב שהוא בחי' ביטול שבחכמה שלמעלה מן הטעם כמ\"ש<sup data-n=\"1284\">72</sup> במ\"א בענין נעשה ונשמע כו' וד\"ל.",[["1278","66","<b>אז אהפוך אל עמים</b>: צפני' ג, ט."],["1279","67","<b>ואחריתו עדי אובד</b>: בלק כד, שם."],["1280","68","<b>כידוע דבני בניו של המן כו'</b>: גיטין נז, ב."],["1281","69","<b>שהביא ראשית החרם מעמלק</b>: שמואל א טו, טו. כא."],["1282","70","<b>הקימותי את דבר ה'</b>: שם, יג."],["1283","71","<b>שמוע מזבח טוב</b>: שם, כב."],["1284","72","<b>כמ\"ש במ\"א בענין נעשה ונשמע</b>: משפטים כד, ז. ראה לקו\"ת שה\"ש כב, א. תו\"א מג\"א צא, א. ובכ\"מ."]]],[2101920240,"<h3>צאינה וראינה</h3>\n<b></b><b>בעז\"ה תורת אדמו\"ר נבג\"מ</b>\n<b>צאינה</b><sup data-n=\"1285\">1</sup> וראינה<sup data-n=\"1286\">2</sup> בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו וביום שמחת לבו, ואמרז\"ל ביום<sup data-n=\"1287\">3</sup> חתונתו זה מ\"ת. הנה יש להבין לשון צאינה מהיכן תצאנה ומה ענין יציאה זו, והנה אמרז\"ל לא<sup data-n=\"1288\">4</sup> זז הקב\"ה מחבבה לכנ\"י עד שקראה אמי, וזה פלא האיך כנ\"י בחי' מקבל תקרא אמי להקב\"ה כו'. אך הנה תחילה יש להבין פי' לשון זה שבחרו חכמים לקרות לה' בשם הקב\"ה",[["1285","1","<b>צאינה וראינה</b>: נו\"א נדפס בלקו\"ת שה\"ש כא, ב (וכאן הוא הנחת כ\"ק אדהאמ\"צ). וראה בשינויים באוה\"ת שה\"ש כרך ג' ע' תתצג (וכרך ב' ע' שפח). וראה בלקו\"ת שם עוד ביאור על המאמר וע\"ש בהוספות להערות וציונים קל, ד. המאמר בנוסח הנדפס כאן נמצא ג\"כ באיזה שינויים במאמרי אדהאמ\"צ נ\"ך ע' רמט (וחסר שם, וכאן המאמר בשלימות). וראה ד\"ה זה בפלח הרמון שה\"ש ע' 90. וראה עוד אודות המאמר להלן ברשימת הכת\"י.\nמאמר זה הוא מליל ש\"פ תצוה, ובעת ההיא היתה חתונת ר' מנחם נחום בן כ\"ק אדמו\"ר האמצעי, ראה להלן ברשימת הכת\"י."],["1286","2","<b>צאינה וראינה בנות ציון</b>: שה\"ש ג, יא."],["1287","3","<b>ביום חתונתו זה מ\"ת</b>: תענית כו, ב. וראה רש\"י ומצו\"צ עה\"פ. ובס' הערכים חב\"ד ח\"ב ע' תי (הע' 104)."],["1288","4","<b>לא זז הקב\"ה מחבבה</b>: שמו\"ר פנ\"ב, ה. זח\"ג רסב, א. ובכ\"מ. [וראה בהמ\"מ ללקו\"ת שה\"ש כא, ב]."]]],[2101920241,"דוקא, כי הנה פי' קדוש בוי\"ו הוא בחי' המשכה מקודש העליון שהוא בחי' עצמיות אא\"ס שנק' קדש ומובדל בעצם להיותו בבחי' אחדות פשוטה ממש בתכלית הפשיטות ובחי' המשכת קדושתו למטה הוא הוי\"ו דקדוש שכולל ב' בחי' סכ\"ע וממכ\"ע והיינו פי' ברוך הוא שיתברך ויומשך מן ההעלם לגילוי, משא\"כ בבחי' קדושת עצמותו לא שייך עדיין לומר בחי' העלם וגילוי כו', אמנם בחי' המשכה זו הוא רק בחי' הארה בעלמא מצומצמת מאוד כדמיון צורת הוי\"ו שהולך ונמשך בקוצר כך מיו\"ד דטהירו עילאה נמשך להיות קו וחוט שזהו בחי' סובב וממלא בכלל ואין לו ערך כלל לגבי עצמיות אא\"ס שהוא אח\"פ ממש. והטעם שנתצמצם כ\"כ האור בבחי' וי\"ו זה היינו לפי שעלה ברצונו הפשוט להיות ד' עולמות אבי\"ע והרי כל הנבראי' בבי\"ע הן בבחי' גבול ובבחי' מספר וגם שאמרו היש<sup data-n=\"1289\">5</sup> מספר לגדודיו מ\"מ הרי הן בבחי' התחלקות והריבוי עכ\"פ שגם שאין קץ ותכלית למספרם מ\"מ בבחי' התחלקות וריבוי הוא רק שאין קץ לריבוי התחלקות זו. וכמו\"כ גם בעולם הנאצל הרי האור בא בבחי' התחלקות ע\"ס ומתחלקות לרבבות מדריגות כמו חסד שבחכמה שבנצח כו' כידוע, וכ\"ז לא שייך כלל וכלל בבחי' עצמיות אא\"ס שהוא אח\"פ בתכלית שא\"א לומר שיבא אורו הפשוט בבחי' ריבוי והתחלקות כידוע שמן האח\"פ לא יסתעף הריבוי כו', אך ע\"י בחי' הארה מצומצמת הנ\"ל יכול האור והשפע לבא בבחי' התחלקות וריבוי מדריגות שונות כאו\"א לפי מדריגתו, והן כל פרטי המדריגות שבד' עולמות דאבי\"ע מראש כל דרגין עד סוף עוה\"ז השפל בהתהוות דצח\"מ גשמי' [וזהו ענין מ\"ש בע\"ח<sup data-n=\"1290\">6</sup> דהארת הקו שהוא בבחי' ממלא בכלל הנמשך מבחי' סובב הכללי אינו רק להיות בחי' מעלה ומטה ובחי' התחלקות וכו'], אמנם גם בחי' ההארה המצומצמת הנ\"ל נק' קדוש ומובדל מד' עולמות אבי\"ע גם שבא אור זה בבחי' סובב וממלא כנ\"ל והענין הוא כי שרש בחי' ההארה זאת שנק' קדוש הוא ענין מחשבה אחת הנק' מחשבה הקדומה שצופה<sup data-n=\"1291\">7</sup> ומביט עד סוף כל הדורות בסקירה אחת כמ\"ש היוצר<sup data-n=\"1292\">8</sup> יחד לבם שהוא רק בחי' השגחה בעלמא שצופה ומביט על הכל כו' ואינה נתפסת מחשבה זו בתוך כל עלמין ממש כדמיון הנפש שמתלבשת בתוך אברי הגוף כו' ע\"כ נק' קדוש ומובדל דהיינו שהוי\"ו שהוא בחי' המשכת ההשגחה הכללי בסקירה א' הנ\"ל הוא ג\"כ קדוש ומובדל כו'.\n<b>וביאור</b> הדבר הנה אנו רואים שהנפש המתלבשת בגוף להחיותו מתפעלת ממקרי הגוף, גם שהנפש עצמה מושללת לגמרי מבחי' תוארי הגשם של הגוף מ\"מ בבחי' הלבשה ותפיסא עכ\"פ הרי היא נתפסת ממש בתוך הגוף ויש לה קשר וחיבור עמו ע\"י בחי' תפיסא זאת עד שמתפעלת ממקרי הגוף כו', וגם מתחלקת לחלקי' בחלקי' פרטי' של אברי הגוף כמו הראי' בעין והשמיעה באוזן והשכל",[["1289","5","<b>היש מספר לגדודיו</b>: איוב כה, ג."],["1290","6","<b>בע\"ח דהארת הקו</b>: ראה ע\"ח דרוש עגולים ויושר (ש\"א) ענף ב'."],["1291","7","<b>שצופה ומביט עד סוף כל הדורות</b>: ע\"פ נוסח ברכת זכרונות במוסף דר\"ה ויוהכ\"פ. ר\"ה יח, א. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' קעה. דברים ח\"ג ע' תשצד. וש\"נ."],["1292","8","<b>היוצר יחד לבם</b>: תהלים לג, טו."]]],[2101920242,"במוח וכו'. ועוד זאת אנו רואים שהנפש בגוף כאשר תתלבש במח' אחת הרי כולה נתפסת ומוקפת בה עד שא\"א לה לצאת ממחשבה זו ולהתלבש במחשבה אחרת (מפני שהנפש נתפסת בגוף ממש ע\"כ במח' א' שמחשב במוח נתפסת כולה וכשצריך לחשוב מחשבה אחרת יוצא' מזו ונתפסת באחרת אבל<sup data-n=\"1293\">9</sup> א\"א לה להתלבש בב' וג' מחשבות כא' אלא בכ\"א בפני עצמה וכשהיא מלובשת בזו אינה נמצאת באחרת כלל כו'). אבל למעלה באח\"פ נא' כי<sup data-n=\"1294\">10</sup> לא מחשבותי מחשבותיכם כו' דאעפ\"י שהארה המצומצמת הנ\"ל הוא בחי' המשכה להיות ממלא כ\"ע וכו' בריבוי ההתחלקות למדריגות שונות עד אין קץ כו' אבל אין זה כדמיון התלבשות המשכת החיות של הנפש בגוף להיות נתפס ממש בתוך כ\"ע להיות מתפעל כו' שהרי נאמר אני<sup data-n=\"1295\">11</sup> הוי' לא שניתי כו', רק היא בחי' המשכת השגחה וידיעה צופה ומביט על הכל בסקירה א' כמ\"ש היוצר יחד לבם כו', ואין השגחה וידיעה זו נתפסת בתוך כ\"ע בכל א' בפרט אלא כוללם יחד בסקירה א' ממש ע\"כ נק' מחשבה א' הכללי' שכוללת את הכל והוא קדוש ומובדל מהכל כו'. והמופת לדבר זה הוא ממה שאנו רואי' בהתהוות ריבוי רבבות עלמין ומדריגות שונות שבוודאי אין דעותיהם שוות ואין מחשבותיהם בהשגת אלקו' שוות אלא כ\"א כפי מקור חוצבו באלקי' חיים כו' ואם הי' בחי' התלבשות הארת אור א\"ס בבחי' ממלא בתוך כ\"ע בבחי' תפיסא והלבשה ממש הרי הוא נתפס בכ\"א לפי מדריגתו וא\"כ הרי זה כדמיון הנפש שכאשר תתלבש במח' א' שא\"א לה להתלבש באחרת ואם מתלבשת באחרת אינה מלובשת בזו כנ\"ל וזה דבר שא\"א לומר למעלה שכאשר יתלבש בתוך עולם זה אינו מלובש בזולתו שהרי הוא ממלא כ\"ע וד\"ל. אלא בהכרח לומר דבחי' מחשבה עליונה שצופה ומביט כו' אינה באה בבחי' תפיסא והלבשה ממש וכמאמר דאיהו<sup data-n=\"1296\">12</sup> תפיס בכולהו עלמין ולית מאן דתפיס בי' כו', ע\"כ כוללם יחד בסקירה א' וגם מחשבה ודיעה א' פרטי' הנמשך בעולם זה אינו מטריד ומבלבל שלא יתלבש במח' ודיעה אחרת שבעולם זולתו כמ\"ש כי לא מחשבותי כמח' אדם, ואעפ\"י שיש ריבוי רבבות מדריגות עולמות וכולם אין דעותיהם שוות כו', מ\"מ בכולם הוא משגיח וצופה ומביט במחשבה א' ואין א' מניעה לזולתו וכמ\"ש כי<sup data-n=\"1297\">13</sup> אל דעות הוי' כו' וז\"ש היוצר<sup data-n=\"1298\">14</sup> יחד לבם כו' מפני שאין מחשבותי כמחשבותיכם [ולא שאין משגיח בפרט רק בכלל שהרי נאמר עיניך<sup data-n=\"1299\">15</sup> פקוחות על כל כו' וכן המבין אל כל מעשיהם בפרטי פרטיות, כמ\"ש מחשבותי לשון רבים לפי שמתחלקת בכל פרטי חלקי המדריגות מראש עד סוף אלא הפרט נחשב כמו כלל מפני שסוקרם בסקירה א' להיותו קדוש ומובדל דלית מאן דתפיס בי' כו', והרי זה",[["1293","9","<b>אבל א\"א לה להתלבש בב' וג' מחשבות כא'</b>: ראה גם שו\"ע אדה\"ז הל' ק\"ש סי' ע\"ג בקו\"א אות ג', ובהמ\"מ לשם (בהוצאת קה\"ת תשס\"א)."],["1294","10","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["1295","11","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["1296","12","<b>דאיהו תפיס בכולהו עלמין</b>: ראה זח\"ג רכה, א. [וראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' קפב]."],["1297","13","<b>כי אל דעות הוי'</b>: שמואל א ב, ג."],["1298","14","<b>היוצר יחד לבם . . המבין אל כל מעשיהם</b>: תהלים לג, טו."],["1299","15","<b>עיניך פקוחות על כל</b>: ירמי' לב, יט."]]],[2101920243,"עד\"מ כמו אדם שיודע מעצמותו מראש ועד סוף בסקירה א' גם שיודע בפרט כל אבר ואבר עד צפורן הרגל מ\"מ הרי סוקר במח' א' כל גופו ומדותיו ושכלו ורצונו כו' וכמ\"ש<sup data-n=\"1300\">16</sup> ברמב\"ם בידיעת עצמו יודע את הכל כו', אך הרי ידיעת עצמו ממש הוא בחי' אח\"פ ואיך בידיעה זו יודע בחי' הריבוי כו', אבל הענין הוא שבחי' ידיעת עצמו זה אין זה עצמו אלא רק בחי' צמצום ההמשכה להיות סובב וממלא שהוא רק בחי' וי\"ו דקדוש הנ\"ל שע\"ז ג\"כ אמר לית<sup data-n=\"1301\">17</sup> מחשבה תפיסא בי' אפי' מחשבה א' הקדומה מפני שהיא רק הארה מאוד מאוד ואין לה ערך כלל לגבי עצמיו' אוא\"ס ממש שנק' קדש בעצם כנ\"ל וד\"ל]. וזהו שהמלאכים<sup data-n=\"1302\">18</sup> אומרים ג' פעמים קדוש עד שאומרים ה' צבאות אות<sup data-n=\"1303\">19</sup> הוא בצבאות שלו כו'.\n<b>והנה</b> כתיב שאו<sup data-n=\"1304\">20</sup> ידיכם קודש וברכו את ה' ולכאורה מה ענין ברכה לקודש, אך הענין הוא דהמשכת קודש העליון נק' ברכה לפי שצריכה לבחי' ברכה והמשכה תמיד בכל דור ודור מחדש כי יוכל להסתלק מפני מעשה הדור שאינו כראוי להעלות אתעדל\"ת להיות מזה אתעדל\"ע להיות חפץ חסד זה להמשיך מקדושתו העצמי' להיות בבחי' סובב וממלא (שהוא הוי\"ו דקדוש הנ\"ל, שאין לו ערך לגבי עצמו' אא\"ס שלמעלה מבחי' גדר עלמין גם מהיות בחי' סובב כו' וכמ\"ש<sup data-n=\"1305\">21</sup> בע\"ח דבתחלת ההשתלשלות הי' חפץ חסד מעצמו ואח\"כ תלוי במעשה התחתונים כו' ע\"ש), ע\"כ צריך לברך ולהמשיך תמיד מקודש העליון כדי שלא יסתלק האור הזה ויוכשר<sup data-n=\"1306\">*21</sup> בעצמיות כמו שהי' טרם ההשתלשלות כמו אלכה<sup data-n=\"1307\">22</sup> אשובה אל מקומי כו', וזה ענין הברכה כמו ברוך כבוד הוי' ממקומו העצמי משום דלית מאן דתפיס בי' כו' כנ\"ל וכמו שאמרו הוא<sup data-n=\"1308\">23</sup> מקומו של עולם ואין העולם מקומו כו' ולהיות כי בבחי' קודש העליון שהוא בחי' אח\"פ שלמעלה מבחי' סובב אין כל ההשתלשלות תופס מקום אצלו כלל וכלל עד דקמי' כחשיכה כאורה רוחני' וגשמי' שווין (כי הרי הוא למעלה מבחי' מעלה ומטה שבבחי' הקו כו' וגם למעלה מבחי' המקיף דקו זה הנק' מקיף הכללי שמקיף וסובב לד' עולמות אבי\"ע בשוה כו'), וע\"כ שם נאמר אם<sup data-n=\"1309\">24</sup> צדקת מה תתן לו כו' שאין המצות מוסיפין אור שם ואין העבירות פוגמין שם כלל וזה שא' אם רבו פשעיך מה תעשה לו כו'",[["1300","16","<b>וכמ\"ש ברמב\"ם בידיעת עצמו</b>: הל' יסוה\"ת פ\"ב ה\"י."],["1301","17","<b>לית מחשבה תפיסא בי'</b>: ת\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["1302","18","<b>שהמלאכים אומרים ג' פעמים קדוש</b>: ע\"פ ישעי' ו, ג."],["1303","19","<b>אות הוא בצבאות שלו</b>: ע\"פ חגיגה טז, א (ע\"ש בע\"י). [וראה מאמרי אדהאמ\"צ בראשית ע' שלה. ובאוה\"ת שה\"ש שם ע' תתצד].."],["1304","20","<b>שאו ידיכם קודש</b>: תהלים קלד, ב."],["1305","21","<b>וכמ\"ש בע\"ח שבתחלת ההשתלשלות הי' חפץ חסד</b>: ראה ע\"ח שער דרושי הנקודות (ש\"ח) ספ\"ו. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתמג]."],["1306","*21","<b>ויוכשר</b>: כ\"ה בכת\"י המעתיק, ואוצ\"ל: ויוכלל"],["1307","22","<b>אלכה אשובה אל מקומי</b>: הושע ה, טו."],["1308","23","<b>הוא מקומו של עולם</b>: ב\"ר פס\"ח, ט. [וראה בהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"א ע' קסז. דברים ח\"א ע' רצא]."],["1309","24","<b>אם צדקת כו' אם רבו</b>: ע\"פ איוב לה, ו-ז."]]],[2101920244,"אשר ע\"כ אין מעשה התחתונים בסו\"מ ועש\"ט מגיע לשם להיות עי\"ז גרעון אור או תוספות אור לכך משם דוקא מברכי' וממשיכי' אא\"ס בעולמות גם שלא לפי מעשה הדור, שבחי' ברכה והמשכה זו מקודש העליון שלא ע\"י מעשה התחתוני' מטעם הנ\"ל נק' קדוש מצד עצמו כי<sup data-n=\"1310\">25</sup> חפץ חסד הוא ע\"כ ממשיך הארה מקדושתו להיות בבחי' סובב וממלא כו'. וזהו קדוש ה' צבאות להיות ה' לצבאות בבחי' סובב וממלא בריבוי ההתחלקות עד אין קץ כו' ואעפ\"כ אות הוא בצבאות שלו משום דאעפ\"י דאיהו תפיס בכולהו עלמין הרי לית מאן דתפיס בי' וכולם אומרים קדוש ומובדל כו' וד\"ל.\n<b>וזהו</b> לשון חכמים שקורין לעצמות אא\"ס בשם הקב\"ה ולא אמרו קדוש וברוך אלא הקדוש ברוך, מפני שבחי' וי\"ו דקדוש הוא עצמו ענין הברכה שברוך ונמשך מקודש העליון בכל עת גם שלא לפי מעשה התחתוני' מטעם הנ\"ל, אך הגורם להיות בחי' ברכה ושפע זו מקודש העליון שהוא וי\"ו דקדוש הרי הוא ע\"י ישראל דוקא. וזהו שאו ידיכם קדש פי' שישראל ישאו ידיהם לבחי' קדש העליון הנ\"ל ומשם יברכו את ה' להיות בבחי' סובב כו'. והענין הוא כי הנה אמר ידיכם ב' ידים דוקא והוא יד ימין ויד שמאל, חסד<sup data-n=\"1311\">26</sup> דרועא ימינא הוא בחי' וימינו<sup data-n=\"1312\">27</sup> תחבקני כו' ודרועא שמאלא בבחי' הדין שמאל<sup data-n=\"1313\">28</sup> דוחה כו' וב' הידים ישאו ויעלו אל בחי' קודש העליון הנ\"ל.\n<b>וביאור</b> הדברים הנה ב' הידים הללו הם לנגד ב' פסוקים הראשוני' שבק\"ש שמע<sup data-n=\"1314\">29</sup> ישראל ובשכמל\"ו שהוא ב' יחודים יחודא עילאה ויח\"ת כידוע. וענין יחודא עלאה הוא למסור נפשו באחד ממש דהיינו בבחי' אח\"פ שנק' קדש העליון מפני ההתבוננות איך שהוא אח\"פ ממש וכל מה שנמשך מאורו הפשוט להיות בבחי' סובב וממלא אינו רק הארה מצומצמת שהוא וי\"ו דקודש הנ\"ל, ולזאת תכלה הנפש האלקי' ליכלל במהותו ועצמותו ית' דוקא ולא תחפוץ בשום דבר זולתו כלל וכלל כמ\"ש מי<sup data-n=\"1315\">30</sup> לי בשמים ועמך כו' כלה שארי כו', וזהו ענין מס\"נ באחד ממש לצאת לגמרי מנרתיק הגוף שהוא נפרד גמור כמו ר\"ע<sup data-n=\"1316\">31</sup> שהי' מאריך באחד עד שיצאת נשמתו באח\"ד כו'. אבל בחי' יח\"ת הוא ההתבוננות איך שנמשך הארת עצמו' אא\"ס להיות ממלא כ\"ע להוות כל העולמות מאין ליש, וזהו ענין ברוך שכמל\"ו בחי' שם ומלכות כמ\"ש מלכותך<sup data-n=\"1317\">32</sup> מלכות כל עולמים כידוע.\n<b>והנה</b> בבחי' יח\"ת היינו לאחר שכבר נמשך שם כבוד מלכותו להיות מלך על עם להוות מאין ליש דוקא אז עיקר היחוד הזה הוא להיות בחי' ביטול היש",[["1310","25","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["1311","26","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה שם."],["1312","27","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג."],["1313","28","<b>שמאל דוחה</b>: ע\"פ סוטה מז, א."],["1314","29","<b>שמע ישראל ובשכמל\"ו שהוא ב' יחודים יחודא עילאה ויח\"ת כידוע</b>: ראה זח\"א יח, ב."],["1315","30","<b>מי לי בשמים כו' כלה שארי</b>: תהלים עג, כה-כו."],["1316","31","<b>ר\"ע שהי' מאריך באחד</b>: ברכות סא, ב."],["1317","32","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."]]],[2101920245,"לאין כמ\"ש כגוונא<sup data-n=\"1318\">33</sup> דאינון כו' אוף הכי אתיחדת לתתא בכורסייא ברזא דאחד כו' וה\"ז בהיפך בחי' יח\"ע שהוא בחי' ביטול והתכללות אמיתי בעצמות המאציל כמו שהוא טרם היותו בחי' ממלא כו' ובבחי' יחו\"ת הרי נעשה עכ\"פ בחי' יש מאין רק שהוא בטל ונכלל באין ועולה מן הפירוד אל היחוד האלקי כו'. וכמו\"כ בנפש האלקי' בבחי' יחו\"ת הוא להיות ביטול היש לאכפיי' כו' דהיינו שלא להיות נפרד מאלקו' ע\"י הרע כמו עוצם עיניו מראות ברע וכל עניני שמירת המחשבות והרהורים רעים אשר לא לה' המה כמ\"ש לא<sup data-n=\"1319\">34</sup> תתורו כו', ובמעשה סור מרע בל\"ת וכל איסורי דרבנן וכה\"ג הכל הוא בחי' ביטול היש בטל<sup data-n=\"1320\">35</sup> רצונך מפני רצונו כו' כמו אל<sup data-n=\"1321\">36</sup> יאמר אדם אי אפשי כו' אלא אפשי אבל אבי שבשמים כו'. וזהו בע\"כ<sup data-n=\"1322\">37</sup> אתה חי שהוא חי בבחי' יש נפרד כדי להיות בחי' ביטול היש כו' וזהו היפך בחי' מס\"נ ביח\"ע הנ\"ל שלא יחפוץ בחיי הגוף כלל כמו כלה שארי כו'. וזהו בחי' רצוא ושוב כמ\"ש אם<sup data-n=\"1323\">38</sup> רץ לבך ביחו\"ע שוב בבחי' יחו\"ת להיות בע\"כ אתה חי בבחי' ביטול היש כו'. וזהו שאמר אם<sup data-n=\"1324\">*38</sup> ישים אליו לבו, אליו<sup data-n=\"1325\">39</sup> ולא למדותיו בחי' סובב וממלא רק אליו לבדו כמ\"ש מי לי בשמים וכו' כנ\"ל שזהו בבחי' יחו\"ע ואח\"כ רוחו ונשמתו אליו יאסף בבחי' יחו\"ת להיות בחי' המשכת אא\"ס בעולמות מאין ליש בחי' וי\"ו דקדוש הנ\"ל והוא ענין בשכמל\"ו להיות הוי' צבאות כנ\"ל וד\"ל. וזהו ענין ב' ידים הנ\"ל יד ימין בחי' רב חסד וימינו תחבקני הוא בבחי' יח\"ע שהוא בחי' היחוד והדיבוק בתכלית הדביקות באח\"פ ממש דוקא כמ\"ש כלה שארי ולבבי וכנ\"ל, ועי\"ז מלמעלה למטה וימינו תחבקיני בחיבוק דוקא שהוא בבחי' מקיף כאדם שחובק את חבירו שלא יזוז ממנו כלל דהיינו שא\"א להיות בבחי' נפרד ויש כלל, משא\"כ בבחי' יחו\"ת שנעשה בבחי' יש נפרד רק שהיש בטל לאין כו' הרי זה בחי' יד שמאל שהוא בחי' דין שמאל דוחה בבחי' הגבורות דוקא שהרי כל בחי' ביטול היש נפרד לאין האלקי א\"א כ\"א ע\"י בחי' הגבורות כמו שאמרו שירגיז<sup data-n=\"1326\">40</sup> אדם כו' לדחות את הרע מפני שצריך להתגבר על בחי' המנגד לה' כמו בראותו גשמי' העולם בבחי' יש נפרד וכן כל עניני תענוגי עוה\"ז צריך לדחותם בבחי' שמאל דוחה בהיותו מתבונן עליהם שהן הוין ונפסדים כו' ומכש\"כ רע גמור כמו עוצם עיניו כו', שכל דחי' ודחי' שדוחה בלבו את הרע וגם במח' ומעשה הכל הוא ע\"י בחי' גבורות דוקא וזהו בחי' יד שמאל, וגם",[["1318","33","<b>כגוונא דאינון כו'</b>: ע\"פ זח\"ב קלה, א."],["1319","34","<b>לא תתורו</b>: שלח טו, לט."],["1320","35","<b>בטל רצונך</b>: אבות פ\"ב מ\"ד."],["1321","36","<b>אל יאמר אדם אי אפשי</b>: ראה תו\"כ ס\"פ קדושים."],["1322","37","<b>בע\"כ אתה חי</b>: אבות ספ\"ד. וראה תניא ספ\"נ."],["1323","38","<b>אם רץ לבך</b>: ס' יצירה פ\"א מ\"ח. ת\"ז בהקדמה ז, א."],["1324","*38","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["1325","39","<b>אליו ולא למדותיו</b>: ראה פרדס של\"ב (שער הכוונה) פ\"ב בשם ספרי. אילמה רבתי מעין א' תמר א'. ס' חרדים המצוה העיקרית רפ\"ה. ובהמ\"מ בס' מאמרי אדהאמ\"צ שמות ע' תרד."],["1326","40","<b>שירגיז אדם</b>: ברכות ה, א. וראה גם תניא פכ\"ט. לקו\"ת שלח מא, א. דרך חיים לאדהאמ\"צ קא, ב ואילך. תו\"ח בשלח רכו, ב ואילך (ובהוצאה הקודמת של תו\"ח הוא בדף שכח, ב ואילך)."]]],[2101920246,"בועשה טוב כמו בת\"ת וצדקה צריך להיות בחי' התגברות לעשות יותר מן כח טבעו כמו ק' פעמים וא' שלא כפי הרגילות וכמ\"ש<sup data-n=\"1327\">41</sup> בלק\"א וד\"ל. וזהו שאו ידיכם קודש בחי' ב' ידים הללו שהן בבחי' יחו\"ע ויחו\"ת שניהם צריכים להיות בבחי' נשיאות והעלאה למעלה מעלה בבחי' קודש העליון שאינו בגדר עלמין כלל והוא למעלה מבחי' סובב וממלא כנ\"ל (וגם שיד שמאל הוא בבחי' שוב בע\"כ אתה חי כנ\"ל, מ\"מ הרי זה בא ג\"כ בבחי' ביטול היש לאין כמו בטל רצונך כו' בסו\"מ ועש\"ט כו' שביטול זה עולה עד רום המעלות והוא בבחי' עצמו' קודש העליון כמ\"ש מי לי בשמים ועמך לא חפצתי רק בעצמותו דוקא). וזהו שע\"י שאו ידיכם קודש ב' ידים אז וברכו את הוי' כו' וי\"ו דקדוש להיות נמשך שפע ברכה והמשכה מקודש העליון להיות גילוי אא\"ס למטה מטה בד' עולמות אבי\"ע וכמ\"ש אם ישים אליו לבו בבחי' ב' ידים רוחו ונשמתו אליו יאסוף בבחי' ירידת קדש העליון למטה מטה דוקא וד\"ל.\n<b>ובכל</b> זה יובן מארז\"ל לא זז מחבבה עד שקראה אמי, כי הנה פי' הקב\"ה מבואר למעלה שזהו בחי' ההמשכה דקדש העליון בחי' עצמיות אא\"ס ממש והוא וי\"ו דקדוש המורה על בחי' המשכה זאת, וכנ\"י ע\"י שמייחדים ב' יחודים יחו\"ע ויחו\"ת בב' פסוקי' הראשוני' שמע ישראל ובשכמל\"ו שזהו מ\"ש שאו ידיכם קודש העליון ב' ידים דוקא כנ\"ל הרי עי\"ז מברכים לאביהם שבשמים כבי' וכמ\"ש וברכו את הוי' דהיינו שהם הם הממשיכים לבחי' קודש העליון להיות הוי' צבאות ע\"י נשיאות ידיהם לקודש העליון כנ\"ל. וזהו לא זז הקב\"ה מחבבה לכנ\"י עד שקראה אמי ועד\"מ האם שמברכת את בנה כך כנ\"י מברכים להקב\"ה שיהי' נק' קדוש בוי\"ו וע\"כ הקדוש ב\"ה בוי\"ו קורא לכנ\"י אמי מפני שהן הממשיכים להיות קדוש (וכידוע דוי\"ו דקדוש הוא בחי' ז\"א ונק' אדם ולמעלה מעלה הוא בחי' א\"ק אדם דבריאה שבראשית הקו ונמשך מקודש העליון בחי' עצמות אא\"ס שלפני הצמצום הנק' מק\"פ<sup data-n=\"1328\">42</sup> כו' ע\"כ קורא לכנ\"י ששרשם הוא בחי' מל' דא\"ס אמי כו' וד\"ל).\n<b>והנה</b> בחי' ההמשכה המצומצמת הנ\"ל דבחי' וי\"ו דקדוש הנה היא נמשכת בדרך כלל ובדרך פרט, דרך כלל הוא נמשך בבחי' החכ' שבתורה דאורייתא<sup data-n=\"1329\">43</sup> מח\"ע נפקת, וזהו מ\"ש והיו<sup data-n=\"1330\">44</sup> הדברים האלה אשר אנכי מצוך כו' פי' מצוך הוא לשון צוותא וחיבור התקשרות מן עצמו' המאציל בעולמות והוא בחי' המשכת ח\"ע שהוא יו\"ד דשם הוי', וזהו שאמר אשר אנכי<sup data-n=\"1331\">45</sup> מי שאנכי בחי' סדכ\"ס בחי' קודש העליון הנ\"ל מצווך בבחי' התקשרות למטה והוא ע\"י בחי' החכ' שבתורה כי",[["1327","41","<b>וכמ\"ש בלק\"א</b>: פט\"ו."],["1328","42","<b>מק\"פ</b>: מקום פנוי. בכת\"י ב כאן: מקיף כללי."],["1329","43","<b>דאורייתא מח\"ע נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. זח\"ג פא, א. קפב, א. רסא, א."],["1330","44","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["1331","45","<b>אנכי מי שאנכי</b>: ראה פי' הראב\"ע תולדות כז, יט. תניא מהדו\"ק ספמ\"ט (ע' תו). וראה מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. אדה\"ז עה\"ת ח\"א ע' רט. וש\"נ."]]],[2101920247,"ראשית<sup data-n=\"1332\">46</sup> בחי' גילוי אא\"ס הוא בחכ' דוקא, אך דרך פרט המשכה זאת נמשכת בבחי' ציור אדם ברמ\"ח אברים והוא ע\"י רמ\"ח תיבין דק\"ש כמ\"ש<sup data-n=\"1333\">47</sup> בכוונת ק\"ש שע\"י רמ\"ח תיבין דק\"ש ממשיכים לבחי' אא\"ס בבחי' רמ\"ח אברי' עילאין דאדם העליון כמ\"ש על<sup data-n=\"1334\">48</sup> הכסא דמות כמראה אדם להמשיך לבחי' אדם מקודש העליון הנ\"ל דכתי' בי' כי<sup data-n=\"1335\">49</sup> לא אדם הוא כו' (וב' המשכות הללו דרך כלל הוא בחכ' הקדומה שנק' אדם קדמאה ודרך פרט הוא במדות דאדם דאצי', וזהו מה<sup data-n=\"1336\">50</sup> שמו ומה שם בנו כו' כמ\"ש<sup data-n=\"1337\">51</sup> במ\"א בענין חכ' בחוץ כו').\n<b>ולהבין</b> ביאור כ\"ז הגם שא\"א להשכיל ולהבין ענין זה בפרטיות, כי אין<sup data-n=\"1338\">52</sup> לו דמות הגוף כו' ח\"ו אך מ\"מ דברה תורה דרך משל ומליצה לשכך האוזן כו' וגם בדרז\"ל אמרו מעלה<sup data-n=\"1339\">53</sup> אני עליכם כאלו עשאוני ופי' עשאוני בציור אדם בבחי' ראש ומוחין ומדות כו'. והענין הוא כי הנה ביעקב כתיב ויקרא<sup data-n=\"1340\">54</sup> שמו ישראל, לי<sup data-n=\"1341\">55</sup> ראש, שכנ\"י מלמטה עושין למעלה בחי' ראש ומוחין להקב\"ה כבי' והיינו עד\"מ באדם התחתון למטה שיש ראש ומוחין חב\"ד שהוא ג' חללי' שבמוח המונח בראש והראש עצמו הוא עצם הגולגולת החופה על המוח ומכסהו מלמעלה כו', כך ישראל הם הממשיכים למעלה להיות בחי' ב' מדריגות הללו ראש וגולגולת ובחי' המוחין חב\"ד כו'. וביאור הדברים הנה ע\"י עסק התורה למטה נמשך למעלה בחי' ח\"ע חכ'<sup data-n=\"1342\">56</sup> מוחא מחשבה מלגאו שנק' חכים ולא בחכ' ידיעא שהוא בחי' מקור כל המשכות חכ' בכל העולמות כידוע מפני שבחי' ח\"ע מלובשת בענינים גשמיי' שבתורה, שהרי אנו רואים שאין שכל וחכמת התורה המלובש בגשמי' כמו שכל וחכ' אנושית המושגת לא מינה כו', כי כל המקראות שבתנ\"ך לא ידע אנוש סודם שלפי פשוטו כל המקרא תנ\"ך הוא מלא סיפורי' פשוטי' שאין בהם שכל אנושי כלל, וזה דבר הנראה שיוצא משכל אנושי לגמרי. וגם תושבע\"פ בהלכות ודינין אין שרש יסודם מוסד עפ\"י טעם ושכל אנושי כלל",[["1332","46","<b>ראשית בחי' גילוי אא\"ס הוא בחכ' דוקא</b>: ראה תניא פל\"ה (בהגה\"ה). ובס' מאמרי אדהאמ\"צ בראשית ע' כא. שמות ח\"ב ע' תקנב. וש\"נ."],["1333","47","<b>כמ\"ש בכוונת ק\"ש שע\"י רמ\"ח תיבין דק\"ש</b>: ראה פע\"ח שער ק\"ש (ש\"ח) פכ\"ה. שער הכוונות ענין ק\"ש דרוש ח'."],["1334","48","<b>על הכסא דמות כמראה אדם</b>: ע\"פ יחזקאל א, כו. וראה מאמרי אדהאמ\"צ במדבר ח\"ג ע ' תתצז. דברים ח\"ב ע' תקעד. וש\"נ."],["1335","49","<b>כי לא אדם הוא</b>: שמואל א טו, כט."],["1336","50","<b>מה שמו ומה שם בנו</b>: משלי ל, ד."],["1337","51","<b>כמ\"ש במ\"א בענין חכמות בחוץ</b>: משלי א, כ. ראה לעיל ריש ד\"ה צדיקים מה הם עושים, ורד\"ה להבין מ\"ש במדרש ע\"פ וקוי ה'. ובהמ\"מ שם."],["1338","52","<b>אין לו דמות הגוף כו'</b>: ע\"פ פיוט יגדל."],["1339","53","<b>מעלה אני עליכם כאילו עשאוני</b>: ראה זח\"ג קיג, א. ויק\"ר פל\"ה, ס. [וראה בהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"א ע' קא]."],["1340","54","<b>ויקרא שמו ישראל</b>: ע\"פ וישלח לה, י."],["1341","55","<b>לי ראש</b>: ראה פע\"ח שער הלולב (שכ\"ט) פ\"א. ובכ\"מ. וראה המ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' צה. דברים ח\"ב ע' שצ."],["1342","56","<b>חכ' מוחא . . חכים ולא בחכ'</b>: ע\"פ ת\"ז בהקדמה ד\"ה פתח אליהו (יז, א-ב)."]]],[2101920248,"וכלל, כידוע לכל מבין ומעיין בכל הלכות דאיסור והיתר כשר ופסול, וגם בדיני ממונות חייב זכאי הוא למעלה מסברת שכל אנושי, ומכש\"כ בדיני טומאה וטהרה כמו שהנוגע<sup data-n=\"1343\">57</sup> יטמא כו' שהוא למעלה משכל אנושי כו' (כמ\"ש בזוהר<sup data-n=\"1344\">58</sup> דכיין ומסאבין הם טעמי תורה ורזין דאוריי' כו'), אלא שרשן ויסודם בהררי קדש שהוא בבחי' חכ' נפלאה מן ההשגה גם בעולמות עליוני' הרוחני', ואף גם מה שנודע טעמי התורה עפ\"י סוד שנק' חכמת הקבלה כמו ע\"י ספר הזוהר וכתבי האריז\"ל הנה מעט מזעיר הוא מאוד, וגם בזה אין ביאור בפרטי העניני' להשיגם לעומקם רק הן חתומי' ונעלמי' לי\"ח ועומדים בסוד ה' כו' וד\"ל.\n<b>והנה</b> בחי' המשכה זו דח\"ע שמתלבשת בגשמיו' תלוי' דוקא בישראל שהן הממשיכים אותה, כי ידוע דעצמו' אא\"ס רם ונשא הגבוה למעלה גם מבחי' ח\"ע וכמ\"ש והחכ'<sup data-n=\"1345\">59</sup> מאין תמצא כו' בבחי' הארה בעלמא בלבד מעצמות אא\"ס, ומאחר שעכ\"פ בחי' ח\"ע שרש התורה אעפ\"י שנפלאה היא מן ההשגה בעולמות מ\"מ בשם חכ' תקרא, וגם שנק' בשרשה במאצי' בשם חכים ולא בחכ' ידיעא בחי' פלאות<sup data-n=\"1346\">60</sup> חכ' או תעלומות<sup data-n=\"1347\">61</sup> חכ' הקדומה כו' מ\"מ בשם חכמה תקרא דכלא וכאין חשיבא לגבי עצמו' המאציל ממש וכמ\"ש בזוהר<sup data-n=\"1348\">62</sup> דאפי' אור צח כו' אוכם הוא לגבי עה\"ע כמ\"ש עושה<sup data-n=\"1349\">63</sup> פלא דגם פלאות חכ' הנ\"ל נק' בחי' עשי' בלבד, והיינו שאמר לית<sup data-n=\"1350\">64</sup> מח' תפיסא בך אפי' מחשבה וחכ' הקדומה, וזהו שאמר מאין תמצא מאין האמיתי תמצא כמו מציאה בעלמא כו', אך ע\"י ישראל ע\"י שאו ידיכם קדש לקדש העליון הנ\"ל ביחודי' דק\"ש יחו\"ע ויחו\"ת אח\"כ והיו<sup data-n=\"1351\">65</sup> הדברים האלה כו' אשר אנכי כו' ודברת בם כו' שאנכי מצוך כו' נמשך בחכ' ודבור, וזהו ישראל לי ראש בבחי' המוחין חכ' מוחא שיהי' נמשך גילוי אא\"ס בח\"ע כו', אך תחלה והיו הדברים האלה אשר אנכי מצוך שהוא בחי' רצה\"ע הפשוט שרש כל המצות שהוא למעלה בחי' ארחין<sup data-n=\"1352\">66</sup> דגלגלתא הנק' ראש והוא עד\"מ כמו עצם הגולגולת המקיף ומכסה על המוחין חב\"ד כו' כי הרצון הוא למעלה מן הטעם והשכל המושג (וגם למעלה מן טעם הכמוס שנק' בחי' ח\"ס פלאות חכ' הנ\"ל). וזהו בעצם הגולגולת שחופה על המוחין (כידוע<sup data-n=\"1353\">67</sup> שבמצחא מתגלה בחי' רדכ\"ר",[["1343","57","<b>שהנוגע יטמא</b>: ע\"פ לשון הפסוק — שמיני יא, כד. ועוד."],["1344","58","<b>בזוהר דכיין ומסאבין הם טעמי תורה ורזין דאורייתא</b>: ראה זח\"ג קלו, א."],["1345","59","<b>והחכ' מאין תמצא</b>: איוב כח, ב."],["1346","60","<b>פלאות חכ'</b>: ראה גם ס' מאמרי אדהאמ\"צ בראשית ע' שנ. שמות ח\"ב ע' תנב. וש\"נ."],["1347","61","<b>תעלומות חכ' הקדומה</b>: ראה מאמרי אדהאמ\"צ שמות ח\"ב ע' תרנג. וש\"נ."],["1348","62","<b>בזוהר דאפי' אור צח</b>: ת\"ז ת\"ע (קלה, ב)."],["1349","63","<b>עושה פלא</b>: בשלח טו, יא. וראה מאמרי אדהאמ\"צ דברים ח\"ג ע' תתמט וש\"נ."],["1350","64","<b>לית מח' תפיסא בך</b>: ת\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["1351","65","<b>והיו הדברים . . ודברת בם</b>: ואתחנן ו, ו-ז."],["1352","66","<b>בחי' ארחין דגלגלתא</b>: ראה זח\"ג קכט, א. קלו, ב."],["1353","67","<b>כידוע שבמצחא מתגלה בחי' רדכ\"ר</b>: [רעוא דכל רעוין]. ראה זח\"ג שם."]]],[2101920249,"כו') והיינו לי ראש ממש, וזהו סדר הפסוקים אשר אנכי מצוך בבחי' הרצון בגולגלתא דחפי' על מו\"ס ואח\"כ ושננתם לבניך ודברת כו' בבחי' ח\"ע שרש התורה כנ\"ל. אמנם במ\"ש אשר אנכי מצוך הוא דרך כלל בלבד שהוא בבחי' הראש עצמו אבל אח\"כ נמשך דרך פרט בציור אדם והן רמ\"ח פיקודין רמ\"ח אברי' דמלכא כידוע וזהו כאילו עשאוני בציור אדם כנ\"ל וד\"ל. והנה דרך כלל ציור אדם הוא ראש ומוחין ודרועא ימינא ודרועא שמאלא חו\"ג וגופא שהוא תפארת וירכין שהן נו\"ה ויסוד סיומא דגופא כו' ובחי' מל' פה כו'.\n<b>ולהבין</b> כ\"ז איך ובמה עושין כנ\"י למעלה כל בחי' ציור אדם כזה, הנה בחי' הראש עושין ע\"י ביטול הרצון שלהם דוקא וכמ\"ש רז\"ל בטל<sup data-n=\"1354\">68</sup> רצונך מפני רצונו שהרי ביטול רצון שהוא בלא טעם ודעת כלל, כי גם מה שאינו משיג בטעמי המצות ולא בח\"ע שבתורה וגם אין בו חכ' והתבוננות בגדולת ה' כלל רק אמונה פשוטה כו', גם הוא יש לו ביטול רצון, מפני שביטול רצון הוא בחי' ביטול פשוט בלא טעם ודעת להיותו למעלה מן הטעם והשכל. וכמו\"כ מעורר עי\"ז למעלה בחי' גילוי רצון העליון הפשוט שלמעלה מן החכ' שבמוחין והוא מ\"ש יהי<sup data-n=\"1355\">69</sup> רצון מלפניך וכן עושים<sup data-n=\"1356\">70</sup> רצונו של מקום להיות בחי' המשכת רצה\"ע שהוא בבחי' גלגלתא דחפי' על מו\"ס כו', וזהו שעושין בחי' ראש כנ\"ל בפי' ישראל לי ראש, ראש ממש וד\"ל.\n<b>ואח\"כ</b> ממשיכים בחי' חכ' מוחא מלגאו כנ\"ל, ואח\"כ ממשיכים בחי' תרין דרועין חסד דרועא ימינא דקודב\"ה כו' והוא ע\"י מעשה הצדקה וחסד שעושים ישראל למטה כידוע דכמו שלמטה משפיע הנותן לעני בידו הימנית להחיות רוח שפלים כך למעלה נמשך חסד דרועא ימינא דקודב\"ה להחיות<sup data-n=\"1357\">71</sup> רוח שפלים בחי' ההשפעה מאין ליש כמ\"ש כי<sup data-n=\"1358\">72</sup> אמרתי עולם חסד יבנה, ובחי' גבורה דרועא שמאלא דקודב\"ה הוא בחי' שמאל דוחה למנוע יניקת ושפע לחיצוני' כו' היינו ע\"י בחי' שמאל דוחה למטה לדחות הרע ולבערו בבחי' גבורות כענין לעולם<sup data-n=\"1359\">73</sup> ירגיז כו' והוא בבחי' מלחמה בכח וגבורה להתגבר לעשות נגד רצונו הטבעי הנמשך אחרי תאוות גופו החומרי כמ\"ש איזהו<sup data-n=\"1360\">74</sup> גבור הכובש את יצרו כו', ובחי' תפארת גופא למעלה הוא בחי' מדת הרחמים מדתו<sup data-n=\"1361\">75</sup> של יעקב בריח<sup data-n=\"1362\">76</sup>",[["1354","68","<b>בטל רצונך</b>: נסמן לעיל."],["1355","69","<b>יהי רצון</b>: אבות פ\"ה, מ\"כ. נוסח תפילת השחר. ועוד."],["1356","70","<b>עושים רצונו של מקום</b>: ברכות לה, ב. וראה גם ס' מאמרי אדהאמ\"צ נ\"ך ע' רעא. וש\"נ."],["1357","71","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["1358","72","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["1359","73","<b>לעולם ירגיז</b>: ברכות ה, א. וראה גם תניא פכ\"ט. לקו\"ת שלח מא, א. דרך חיים לאדהאמ\"צ קא, ב ואילך. תו\"ח בשלח רכו ב (בהוצאה הקודמת הוא בסף שכח, ב)."],["1360","74","<b>איזהו גבור הכובש את יצרו</b>: אבות פ\"ד מ\"א."],["1361","75","<b>מדתו של יעקב</b>: ראה זח\"א פז, ב. ובהמ\"מ בס' מאמרי אדהאמ\"צ בראשית ע' קנו."],["1362","76","<b>בריח התיכון</b>: ראה זח\"ב קעה, ב. ובהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"א ע' יט."]]],[2101920250,"התיכון כו', וזה נעשה ע\"י בחי' הרחמים שישראל מעוררים על נפשם האלקי' שעי\"ז מעוררים מדת הרחמים למעלה כמ\"ש הבן<sup data-n=\"1363\">77</sup> יקיר לי כו' המו מעי לו רחם ארחמנו כו', דבאמת א\"א לומר בחי' התפעלות רחמי' בבחי' אחדות פשוטה כי בחי' התפעלות הוא בחי' שינוי רק ע\"י החכ' נמשך מדת הרחמי' כמו שנמשך בחי' החסד כמ\"ש לך<sup data-n=\"1364\">78</sup> הוי' הגדולה כו' והתפארת שהוא בחי' הרחמי', אלא מעוררים בחי' רחמים פשוטי' שלמעלה מן החכ' והוא מ\"ש המו מעי לו רחם ארחמנו כו' (שזהו בבחי' עצמות עד\"מ בן יקיר לאב שהמו מעיו ברחמנות בבחי' פנימי' ועצמות ביותר, כך נש\"י להיותם בבחי' עצמיו' ופנימי' המאציל כמ\"ש כי<sup data-n=\"1365\">79</sup> אתה אבינו ע\"כ המו מעי כו' משום דנש\"י נק' אדם כמ\"ש ויפח<sup data-n=\"1366\">80</sup> באפיו נשמת חיים ומאן דנפח מתוכו ופנימיותו נפח כמ\"ש אתה<sup data-n=\"1367\">81</sup> נפחת בי כו' וזהו שבחי' רחמים דיעקב<sup data-n=\"1368\">82</sup> נק' נחלה בלי מצרים שהוא בחי' רחמים פשוטי' שבעצמות כמ\"ש המו מעי לו כו' וד\"ל).\n<b>ובחי'</b> נצח והוד תרין ירכין הנה בחי' נצח דז\"א הוא מ\"ש וגם<sup data-n=\"1369\">83</sup> נצח ישראל לא ישקר כו' שבחי' נצח אינה חולפת ועוברת וע\"כ לא ישקר שאין לו הפסק, וזהו לא יכזב מל' נהרות<sup data-n=\"1370\">84</sup> הכוזבים כו'. וזה נעשה ע\"י בחי' הנצח שלמטה בכנ\"י שהוא ענין ההסכם החזק שנעשה בבחי' ניצוח גם לאחר שחלפה ועברה האהבה וההתפעלות שבתפלה לגמרי, כמו כל היום בטרדתו בעסקיו מ\"מ עומד בניצוח לנגד רצון הגוף בדרך אתכפיי' בלי טעם ודעת בלי אור אהבה שבתפלה רק מצד ההסכמה שנשאר אצלו בתוקף לילך בדרכי הוי' ולא להיות נפרד מיחודו כו'. וכן בבחי' ההוד שאין בזה בחי' טעם ודעת רק בבחי' הודאה בלבד כענין מודים<sup data-n=\"1371\">85</sup> אנחנו לך כו' שמודה שצריך להיות בטל לרצון הוי' ולהתגבר לנגד כל מונע ומסתיר אור ה' כו', וגם דבינה<sup data-n=\"1372\">86</sup> עד הוד אתפשטת אבל הוא רק בחי' רשימו בעלמא מצומצמת ביותר, וכן בניצוח אין בו רק בחי' רשימו בעלמא מן ההתבוננות שבתפלה שהוא מה שנשאר ההסכם אצלו כך כנ\"ל, אך אנו רואי' שיש",[["1363","77","<b>הבן יקיר</b>: ירמי' לא, יט."],["1364","78","<b>לך הוי' הגדולה</b>: דה\"א כט, יא."],["1365","79","<b>כי אתה אבינו</b>: ישעי' כג, טז."],["1366","80","<b>ויפח באפיו נשמת חיים ומאן דנפח</b>: בראשית ב, ז. וראה (בשם הזוהר) תניא פ\"ב. תניא אגה\"ק סט\"ו. תניא אגה\"ת מהדו\"ק ע' תקס. [וראה בהמ\"מ לתניא שם]. וראה סה\"מ אתהלך לאזניא ע' קה (בשם מארז\"ל)."],["1367","81","<b>אתה נפחת בי</b>: ברכות ס, ב (ברכת אלקי נשמה). וראה גם בהמ\"מ בס' מאמרי אדהאמ\"צ בראשית ע' עא."],["1368","82","<b>דיעקב נק' נחלה בלי מצרים</b>: שבת קיח, א. וראה מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'קח ואילך."],["1369","83","<b>וגם נצח ישראל לא ישקר</b>: שמו\"א טו, כט."],["1370","84","<b>נהרות הכוזבים</b>: ע\"פ פרה פ\"ח מ\"ט."],["1371","85","<b>מודים אנחנו לך</b>: נוסח תפילת העמידה."],["1372","86","<b>דבינה עד הוד אתפשטת</b>: ראה זח\"ג רכג, ב. וראה גם בהמ\"מ בס' מאמרי אדה\"ז עה\"ת ח\"ב לע' תקפה. ובס' אמרי בינה (קה\"ת תשמ\"ה) שער התפילין קכ, ד."]]],[2101920251,"תוקף וחוזק גדול בניצוח שלא יופסק לעולם, וזהו דגם שנו\"ה נק'<sup data-n=\"1373\">87</sup> בזהר בשם בדי ערבות שאין בהם טעם וריח מבחי' המוחין ומדות רק בחי' רשימו בעלמא מ\"מ תקיפים וחזקים ביותר וכמו עד\"מ השוקין וירכין שהן מעמידין כל הגוף ועיקר כחו של אדם הוא כשיוכל לעמוד כו' וד\"ל.\n<b>ובחי'</b> יסוד סיומא דגופא הוא בחי' אות ברית קודש שהוא ע\"י בחי' התקשרות כנ\"י שמתקשרים ודבקי' ונמשכים רק באלקי' חיים כו' ואין להם תשוקה לדבר אחר כמו היונה<sup data-n=\"1374\">88</sup> שאינה נזקקת רק לבן זוגה ולא כמו הזונה כו' וכמ\"ש ולא<sup data-n=\"1375\">89</sup> תתורו כו' וכמ\"ש ואל<sup data-n=\"1376\">90</sup> אישך תשוקתך [שהוא בחי' יסוד דנוק'] כך מלמעלה נמשך בחי' התקשרות דקודב\"ה בכנ\"י שהוא בחי' יסוד העליון כו' וד\"ל. ובחי' מל' פה תושבע\"פ קרינן לה זהו ע\"י עסק התורה דכנ\"י בדיבור בפה שנק' תושבע\"פ דוקא הרי נאמר ודברי<sup data-n=\"1377\">91</sup> אשר שמתי בפיך שמעוררי' לבחי' דיבור דפה העליון כמו שאמרו כל<sup data-n=\"1378\">92</sup> הקורא ושונה הקב\"ה יושב ושונה כנגדו כמ\"ש את<sup data-n=\"1379\">93</sup> ה' האמרת היום כו' כידוע וד\"ל. ונמצא שכל בחי' ציור אדם העליון בחי' קומה שלימה שנק' שיעור<sup data-n=\"1380\">94</sup> קומה של יוצר בראשית להתלבש בבחי' ע\"ס עליונות אורות וכלים כמו חכ' מוחא חסד דרועא כו' הכל נעשה ע\"י כנ\"י שמשעבדים כחות נפשם כמו חכ' ורצון ומדות חו\"ג כו' שבהן וע\"י נמשך ג\"כ מלמעלה מעצמות המאציל להתלבש בע\"ס אורות וכלים כנ\"ל. וזהו שקרא הקב\"ה לכנ\"י בשם אמי כאם המגדלת הולד כו' וכנ\"ל שזהו משארז\"ל כאלו עשאוני כו' וד\"ל.\n<b>אך</b> הנה מ\"ש בעטרה שעטרה לו אמו בחי' עטרה זו הוא בחי' כתר מל' שהוא ע\"ג ראש המלך מלמעלה עד\"מ כשמכתירין למלך שעושין עטרה מאבנים טובות המאירים ונותנים אותה ע\"ג הראש להיות לו לתפארת הוד מלכות בראשו כך למעלה בחי' עטרה וכתר על ראשו של הקב\"ה להיות לו לתפארת כו' נעשה ג\"כ מאבנים טובות המאירות דוקא והן הן בחי' אותיו' התורה שנק' אבנים להיותם מלובשים בדברים גשמיים כמו גדילים<sup data-n=\"1381\">95</sup> תעשה לך כו' עשר<sup data-n=\"1382\">96</sup> תעשר כו' וכה\"ג אבל בהן דוקא נעשה בחי' העטרת עטרת תפארת בראש המלך מלך מלכי המלכים כו' וד\"ל. והענין הוא כי הנה אמרז\"ל בשעה<sup data-n=\"1383\">97</sup> שהקדימו ישראל נעשה",[["1373","87","<b>נק' בזהר בשם בדי ערבות</b>: ראה זח\"א רכ, ב (ובאור החמה שם). רסב, א. זח\"ג קצג, ב (ובמקדש מלך שם)."],["1374","88","<b>היונה שאינה נזקקת רק לבן זוגה</b>: ראה שהש\"ר רפ\"ד."],["1375","89","<b>ולא תתורו</b>: שלח טו, לט."],["1376","90","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1377","91","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["1378","92","<b>כל הקורא ושונה</b>: ראה תדא\"ר רפי\"ח. ובהמ\"מ במאמרי אדהאמ\"צ שמות ח\"ב ע' שסז. דברים ח\"ד ע' א'שעד."],["1379","93","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["1380","94","<b>שיעור קומה של יוצר בראשית</b>: ע\"פ פרקי היכלות. ראה במילואים להמ\"מ בסו\"ס מאמרי אדהאמ\"צ במדבר ע' דש. ובהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשצו. דברים ח\"ג ע' תתיט. אוה\"ת ואתחנן כרך ו' ע' ב'רלג."],["1381","95","<b>גדילים תעשה לך</b>: תצא כב, יב."],["1382","96","<b>עשר תעשר</b>: פ' ראה יד, כב."],["1383","97","<b>בשעה שהקדימו</b>: ראה שבת פח, א."]]],[2101920252,"לנשמע באו מה\"ש וכתרו להם ב' כתרים על כאו\"א אחד כנגד נעשה ואחד כנגד נשמע. וביאור הדברים הנה פי' נשמע לשמוע אל הרצון העליון ובחי' ח\"ע שבתורה כשאומר דבר<sup data-n=\"1384\">98</sup> ה' זו הלכה דהיינו שיהי' בטל במציאות לד\"ת הנאמרים בפיו שהיא רצונו וחכמתו ית' כאלו שומע מפי השכינה ממש כי דבריו חיים וקיימים וכמ\"ש ודברי אשר שמתי בפיך וה\"ז כאלו השכינה מדברת מתוך גרונו והוא שומע לקול השכינה שבפי' בבחי' ביטול גמור בשמיעה זו כמו ששומע העבד דבר המלך ששומע בתכלית הביטול, וז\"ש תען<sup data-n=\"1385\">99</sup> לשוני אמרתך מפני שאין דבר ההלכה דברי עצמו אלא דבר ה' הוא ונק' אמרתך רק שלשוני תען אמרתך כו' וכענין השמע<sup data-n=\"1386\">100</sup> לאזניך מה שאתה מוציא מפיך, בחי' אתה הוא בחי' ואתה<sup data-n=\"1387\">101</sup> מחי' את כולם, ואתה זה הוא המוציא דבר הוי' בפיך, וא\"צ רק לשמוע באזניך מה שאתה זה מוציא מפיך כו' וד\"ל, ועכ\"פ בחי' ביטול זה הוא לרצון וח\"ע שבתורה הנאמר בפיו בגילוי שזהו ונשמע והוא נק' כתר להיותו בבחי' ביטול רצון לשמוע רק אל רצה\"ע (וכמ\"ש למעלה בענין יהי רצון עושין רצונו כו' שעי\"ז ממשיך לבחי' רצה\"ע כו' שעושין בזה בחי' ראש ולא עטרה ע\"ג הראש, היינו רק ביטול הרצון מפני רצה\"ע בלבד משא\"כ בבחי' הביטול בשמיעה אל הרצון שעי\"ז ממשיך ממקור הרצה\"ע להיות גילוי רצון כו' שזה דוקא נק' עטרה ע\"ג הראש כו' וד\"ל).\n<b>ובחי'</b> כתר הב' שלמעלה מבחי' כתר זה הוא מ\"ש ונעשה והוא אשר הקדימו לנשמע, והענין הוא כי פי' ונעשה הוא בחי' ביטול הרצון לגמרי דהיינו לא כמו ביטול בשמיעה בפרט שהוא אל אותו הרצון ששומע בלבד, אבל ונעשה הוא כל מה שיעלה ברצונו נעשה גם טרם ששומע הרצון שהוא בחי' ביטול לבעל הרצון דוקא שממנו נשמע כל רצון בפרט אח\"כ א\"כ זהו בחי' כתר בכלל ונק' רדכ\"ר שהוא בחי' בעל הרצון לפי שנעשה זה הוא ג\"כ בחי' ביטול כללי והיולי לבטל כל הרצונות ולא ביטול רצון בפרט שאינו ביטול עצמותו לגמרי כמו נעשה מה שנשמע אח\"כ שהוא בחי' ביטול העצמי' מכל וכל דהיינו בחי' הביטול בעצם הרצון שעי\"ז מעורר למעלה בבחי' בעל הרצון שממנו נמשך בחי' רדכ\"ר (כי בעל הרצון הוא למעלה גם מרדכ\"ר, שרדכ\"ר אינו רק מקור הרצון ונק' בשם רעוא ורצון עכ\"פ משא\"כ בעל הרצון שעליו אמר שעלה<sup data-n=\"1388\">102</sup> ברצונו הפשוט הרי מה שעלה ברצונו הפשוט הוא רק הארה בעלמא מעצמותו כו' וד\"ל), ודרך כלל ב' כתרים הללו נעשה הוא בחי' כתר שבכתר ונשמע הוא בחי' כתר שבחכ' כו' שהוא רצון הגלוי ומורכב בחכ' שנק' טעם כמוס לרצון כו', וזהו מי<sup data-n=\"1389\">103</sup> גילה לבני רז זה שהקדימו נעשה כתר הכללי לנשמע כתר הפרטי בביטול דשמיעה לכל רצון הבא בגילוי (כי גם הוא ביטול כללי לכל רצון הנגלה אבל עכ\"פ לרצון הגלוי בשמיעה",[["1384","98","<b>דבר ה' זו הלכה</b>: ע\"פ שבת קלח, ב."],["1385","99","<b>תען לשוני אמרתך</b>: תהלים קיט, קעב. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'סג. דברים ח\"ג ע' א'ע."],["1386","100","<b>השמע לאזניך</b>: ברכות יג, א. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ נ\"ך ע' יט."],["1387","101","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["1388","102","<b>שעלה ברצונו הפשוט</b>: ע\"ח דרוש עגולים ויושר (ש\"א) ענף ב'."],["1389","103","<b>מי גילה לבני רז זה</b>: שבת שם."]]],[2101920253,"הוא בטל ולא לבעל הרצון כו'), ומבחי' כתר דנעשה נמשך בחי' כתר דנשמע דוקא, דהיינו שתחילה צריך להיות ביטול עצמי לבעל הרצון כמו ביטול דנעשה ואח\"כ ממילא יבא ביטול הב' דנשמע לרצון הגלוי בדיבור בד\"ת כנ\"ל כי רוח<sup data-n=\"1390\">104</sup> אייתי רוח ואמשיך כו' דהיינו שבחי' ביטול דבחי' נעשה הוא בבחי' העלאה דרצוא להבטל מכל וכל ולהכלל בבחי' עצמות אא\"ס בעל הרצון דוקא ואז יומשך בחי' המשכה דנשמע שהוא קבלת הרצון הבא בגילוי כו' וד\"ל. וזהו שאמרז\"ל כל<sup data-n=\"1391\">105</sup> האומר אין לי אלא תורה אפילו תורה אין לו, פי' אין לי דוקא דהיינו שאין לו אלא בחי' ביטול הב' דנשמע בקבלת הרצון וחכמה שבתורה הבא בדיבור כנ\"ל ואינו חפץ בביטול העצמי שקודם השמיעה שהוא לבעל הרצון שהוא בחי' מקור ההיולי וכללי לבחי' ביטול הב' דנשמע כנ\"ל אז אפילו תורה אין לו, אין לו דייקא שאפי' בחי' ביטול זה דנשמע בדברו בד\"ת גם אין לו כלל דהיינו שאין לתורה זו שהוא דבר ה' וגילוי רצונו וחכמתו שייכה אליו כלל ואין לה חיבור וקשר בנפשו כלל, וזהו אפי' תורה אין לו להיות שאין לתורה זו שאומר בפיו מקור מוצא מעצמות אא\"ס שנק' בעל הרצון, כי אין התורה נמשכת מעצמות אא\"ס רק ע\"י בחי' ביטול העצמי דנעשה שקודם לביטול דשמיעה שהוא לבעל הרצון שממנו נמשך בחי' ונשמע, כי רוח אייתי רוח כו' ואם אין העלאה אין המשכה כו' כידוע וד\"ל.\n<b>והנה</b> כמו שאמר דמה\"ש כתרו ב' כתרים על כאו\"א מישראל מטעם הנ\"ל כמו\"כ נמשך בחי' כתרים הללו בראשו של הקב\"ה א' כנגד נעשה וא' כנגד נשמע ע\"ד הנ\"ל בבחי' ב' מיני ביטול דכנ\"י מלמטה למעלה כך מלמעלה למטה בחי' כתר הא' (שנק' כתר שבכתר) הוא בחי' ביטול עצמו' רצונו ית' כבי' שמבטל א\"ע כדי להשפיל א\"ע להיות לו רצון בגילוי שבחי' ביטול זה העצמי כבי' גורם בחי' המשכת גילוי הרצון שבתו\"מ מבעל הרצון עצמו כי בעהר\"צ עצמו הרי עצם הרצון ג\"כ כלול בעצמותו ממש בבחי' א\"ס ואין תכלית וכאשר בא רצונו בתו\"מ הרי זה בחי' צמצום עצמותו מאד רק כי חפץ חסד הוא להחיות רוח שפלים להיות מקור לעולמות ע\"כ המשיך צמצום הראשון בתו\"מ. וראי' לדבר זה מה שמצינו שכל<sup data-n=\"1392\">106</sup> המצות נק' בשם צדקה וחסד כמ\"ש וצדקה תהי' לנו כי נשמור כו' וכן אמר תען לשוני אמרתך כי כל מצותיך צדק הרי כל מצותיו ורצונותיו אינו רק בחי' צדק וחסד ולכאורה אין זה מובן מהו ענין החסד וצדק בגילוי רצון במצות, אך מפני שבעל הרצון הוא רם ונשא הגבה למעלה מבחי' רצון זה המלובש במצות ולא צמצם א\"ע כ\"כ רק מפני כי חפץ חסד הוא כדי להיטיב לברואיו עי\"ז כמארז\"ל רצה<sup data-n=\"1393\">107</sup> הקב\"ה לזכות את ישראל לפיכך הרבה להם תו\"מ",[["1390","104","<b>רוח אייתי רוח</b>: ע\"פ זח\"ב קסב, ב. וראה בהמ\"מ בס' מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדהאמ\"צ בראשית ע' רל."],["1391","105","<b>כל האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["1392","106","<b>שכל המצות נק' בשם צדקה וחסד וכמ\"ש וצדקה תהי' לנו</b>: ואתחנן ו, כה. וראה גם תו\"א בשלח סג, א-ג. תצוה פב, ד. ובמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' עדרת. ובתו\"ח שמות יט, א."],["1393","107","<b>רצה הקב\"ה לזכות . . למען צדקו</b>: מכות כג, ב. ישעי' מב, כא."]]]]});
